window.HH_LEARN.burn={"id":"burn","title":"الاحتراق الوظيفي","sub":"من الاحتراق إلى الإشراق","lead":"برنامج يجمع دليلاً إرشادياً حديثاً وثلاث دراسات ميدانية عربية في رحلة واحدة: تفهم الظاهرة وأبعادها وأسبابها، وتتعرف إلى مؤشراتها في نفسك وفي من حولك، ثم تبني خطتك للوقاية والتعافي.","note":"هذا برنامج توعوي من مصادر علمية، يساعدك على الفهم والوقاية، ولا يقدّم تشخيصاً. فحصك الذاتي وخطتك يُحفظان على جهازك فقط، ولا يراهما أحد.","credit":"المصادر: الدليل الإرشادي «من الاحتراق إلى الإشراق» الصادر عن المركز الوطني لتعزيز الصحة النفسية (2025) هو العمود الفقري للبرنامج، وترافقه ثلاث دراسات: رسالة سماهر أبو مسعود (الجامعة الإسلامية بغزة، 2010)، وبحث منار الصبحي (جامعة جدة، 2022)، وبحث هبة تراس (المعهد العالي لإدارة الأعمال، سورية). النصوص منقولة من مصادرها، ولم تُنقل فقرات مقياس ماسلاك لأنه محمي الحقوق.","sources":[{"id":"guide","short":"الدليل","kind":"دليل إرشادي","t":"من الاحتراق إلى الإشراق: دليل إرشادي للوقاية والتعافي من الاحتراق الوظيفي","by":"إعداد أ. ندى عقاب بن عبود، وأ. هدى حسين السعد","where":"المركز الوطني لتعزيز الصحة النفسية، الرياض","year":"2025"},{"id":"gaza2010","short":"دراسة غزة","kind":"رسالة ماجستير","t":"ظاهرة الاحتراق الوظيفي لدى الموظفين الإداريين العاملين في وزارة التربية والتعليم العالي بقطاع غزة: أسبابها وكيفية علاجها","by":"سماهر مسلم عياد أبو مسعود، الجامعة الإسلامية بغزة","where":"قطاع غزة","year":"2010"},{"id":"jeddah","short":"دراسة جدة","kind":"بحث ماجستير منشور","t":"الاحتراق الوظيفي وتأثيره على أداء العاملين في وزارة الشؤون البلدية والقروية (دراسة تطبيقية على الإداريين العاملين بأمانة محافظة جدة)","by":"منار محمد الصبحي، جامعة جدة، كلية الأعمال","where":"جدة","year":"2022"},{"id":"syria","short":"دراسة سورية","kind":"بحث ماجستير","t":"أثر الاحتراق الوظيفي على أداء العاملين ومعدل دوران العمل في المنظمات الانسانية (دراسة تطبيقية على عدد من المنظمات الإنسانية تحت مظلة الأمم المتحدة في سورية)","by":"هبة تراس، المعهد العالي لإدارة الأعمال HIBA","where":"سورية","year":"بلا تاريخ"}],"chapters":[{"k":"what","t":"ما الاحتراق الوظيفي؟","ic":"fire","q":"ما هذه الظاهرة، ولماذا صارت في دائرة الضوء، وكيف تطور فهمها؟","sections":[{"t":"ما الاحتراق الوظيفي؟","src":"guide","pg":1,"p":["خلق الله الإنسان لعمارة الأرض، وسخّر له مواردها لتكون تحت تصرّفه، وميّزه بالعقل وحثّه على العلم والعمل، فمن خلالهما، يساهم الأفراد في بناء الأرض وتطويرها في مختلف المجالات والمستويات المهنية. ومع ذلك، فإن بيئات العمل المختلفة لا تخلو من الضغوط التي قد تتفاقم وتؤدي إلى الاحتراق الوظيفي، وهو حالة من الإجهاد العاطفي والجسدي والعقلي الناتج عن ضغوط العمل المستمرة، مما يؤثر سلبًا على إنتاجية العاملين وكفاءتهم.","في ظل تزايد ظاهرة الاحتراق الوظيفي في بيئات العمل، قمنا بإعداد هذا الدليل الإرشادي الشامل الذي يعتمد على منهجية التساؤلات والسرد ودراسات المواقف الواقعية لتقديم توصيف دقيق للاحتراق الوظيفي، بما في ذلك علاماته، وأسبابه، ومراحله، وطرق الوقاية منه والتغلّب عليه.","إن التعرّف على الأعراض ومعرفة كيفية التعامل معها يعدُّ من أنجح استراتيجيات الوقاية التي يجب على كل مسؤول في أي منظمة الإلمام بها لتجنّب تبعات الاحتراق الوظيفي على العاملين.","يساعد هذا الدليل العاملين على التعامل بفعالية مع الضغوط المهنية، مما يحقّق توازنًا بين العمل والحياة الشخصية، كما يساهم في الوقاية من الاحتراق الوظيفي والتعافي منه، مما يحسّن جودة الحياة المهنية، هذا التوازن يعزّز الحياة الشخصية والاجتماعية للأفراد بشكل تدريجي ومُستدام."],"key":"الاحتراق الوظيفي، وهو حالة من الإجهاد العاطفي والجسدي والعقلي الناتج عن ضغوط العمل المستمرة، مما يؤثر سلبًا على إنتاجية العاملين وكفاءتهم.","quote":{"x":"﴿هُوَ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ ذَلُولًا فَامْشُوا فِي مَنَاكِبِهَا وَكُلُوا مِن رِّزْقِهِ وَإِلَيْهِ النُّشُورُ﴾","by":"قال تعالى (الملك: 15)"}},{"t":"لماذا صار في دائرة الضوء؟","src":"guide","pg":3,"p":["ما الذي جعل الاحتراق الوظيفي في دائرة الضوء؟","الاحتراق الوظيفي أصبح في الآونة الأخيرة موضوعًا ذا أهمية كبيرة بسبب تأثيراته العميقة على الأفراد والمجتمعات. تؤكد الدراسات أن الاحتراق الوظيفي والضغوطات المرتبطة ببيئة العمل مستفحلة، وأن الاهتمام بها ليس ترفًا أو أمرًا ثانويًا. يجب النظر إلى هذه القضية بجدية، لما لها من انعكاسات اقتصادية، مادية، وصحية كبيرة، وما يزيد من خطورتها أنها مشكلة خفية وشخصية، مما يتطلّب اهتمامًا خاصًا للتعامل معها بفعالية."],"key":"وما يزيد من خطورتها أنها مشكلة خفية وشخصية، مما يتطلّب اهتمامًا خاصًا للتعامل معها بفعالية.","items":[{"h":"خفية","x":"يبدأ الاحتراق الوظيفي بشكل غير ملحوظ، حيث يختلط التعب والإرهاق مع ضغوط العمل اليومية، مما يجعل من الصعب على الشخص تحديد ما إذا كان يعاني من ضغوط العمل العادية أو وصل إلى مرحلة الاحتراق. تبدأ الأعراض بالشعور المستمر بالتعب أو فقدان الحماس للعمل."},{"h":"شخصية","x":"تختلف تأثيرات الاحتراق الوظيفي من شخص لآخر بناءً على ظروفهم الشخصية والمهنية، يمكن أن تتراوح هذه التأثيرات من أعراض بسيطة إلى مشاكل صحية خطيرة مثل نوبات القلب، وارتفاع ضغط الدم، وأمراض الجهاز الهضمي، هذه التأثيرات يمكن أن تؤدي إلى التفكير بالانتحار، مما يجعل من الضروري الوعي بهذه الأعراض ومعالجتها في وقت مبكّر."}]},{"t":"أهمية فهم الاحتراق الوظيفي","src":"guide","pg":2,"key":"فهم الاحتراق الوظيفي يساعدها في التعرّف على الأعراض والأسباب، وبالتالي يمكّنها من اتخاذ التدابير الوقائية والعلاجية المناسبة لدعم العاملين","items":[{"h":"ماذا سيحدث إذا تجاهلت المنظمات أهمية فهم الاحتراق الوظيفي؟","x":"إذا تجاهلت المنظمات أهمية فهم الاحتراق الوظيفي، فقد تفشل في توفير بيئة عمل صحية وداعمة، مما يؤدي إلى ارتفاع معدلات الغياب، وزيادة دوران العاملين، وانخفاض الروح المعنوية والإنتاجية، وصعوبة جذب المواهب والاحتفاظ بها، مما يؤثر سلبًا على أدائها العام. وعلى النقيض، فإن فهم الاحتراق الوظيفي يساعدها في التعرّف على الأعراض والأسباب، وبالتالي يمكّنها من اتخاذ التدابير الوقائية والعلاجية المناسبة لدعم العاملين، مما يعزّز الرضا والارتباط الوظيفي لديهم، ويؤدي إلى زيادة الإنتاجية وتحسين بيئة العمل.","grp":"المنظمة"},{"h":"ماذا لو لم يعِ الموظف أنه يمرُّ بمرحلة احتراق وظيفي؟","x":"إذا لم يدرك الموظف أنه يمر بمرحلة احتراق وظيفي، فقد يستمر في العمل تحت ضغوط شديدة دون البحث عن حلول أو دعم، مما يؤدي إلى تدهور حالته الصحية والنفسية، وانخفاض إنتاجيته، وزيادة احتمالية ارتكاب الأخطاء، وقد يصل به الأمر إلى ترك العمل أو التسبّب في أضرار جسيمة لصحته. وعلى النقيض، فإن وعي الموظف بأنه يمر بمرحلة احتراق وظيفي ومعرفة مستوى شدته، والسعي للحصول على الدعم اللازم يمكن أن يساعد في تحسين حالته الصحية والنفسية، وزيادة إنتاجيته، وتقليل احتمالية ارتكاب الأخطاء، مما يعزّز من استمراريته في العمل ويحافظ على صحته.","grp":"الموظف"}]},{"t":"إحصائيات حول الاحتراق الوظيفي","src":"guide","pg":4,"p":["من الضروري أن تتبنّى الجهات المعنية سياسات وبرامج تهدف إلى تعزيز الصحة النفسية وتقديم الدعم اللازم للأشخاص الذين يعانون من هذه الاضطرابات، لضمان تحسين جودة الحياة والرفاهية العامة في المجتمع.","لا شكَّ بالتأكيد أن نتائج الإحصائيات مقلقة للغاية وتدق ناقوس الخطر بشأن مدى انتشار الاحتراق الوظيفي وتأثيره السلبي على العاملين والمنظمات، هذه الأرقام تكشف عن التأثير العميق لهذه المشكلة على الصحة النفسية والجسدية للعاملين، وكذلك على إنتاجية المنظمات، لذا، فإن دعم العاملين ليس مجرّد رفاهية، بل هو ضرورة حتمية.","وقد تتساءل، عزيزي القارئ: كيف يمكنني معرفة ما إن كنت أمرُّ بمرحلة الاحتراق الوظيفي؟ وما هي تداعياته؟ وكيف يمكنني التعافي منه؟ بل ما هو الاحتراق الوظيفي بالتحديد؟ والكثير من التساؤلات حول هذا القاتل الصامت!"],"key":"فإن دعم العاملين ليس مجرّد رفاهية، بل هو ضرورة حتمية.","stats":[{"n":"76%","x":"من الموظفين يتعرّضون للاحتراق الوظيفي على الأقل في بعض الأحيان","src":"استطلاع مؤسسة غالوب (gallup.com)، بلا سنة في الدليل"},{"n":"28%","x":"منهم يعانون منه بشكل دائم أو في أغلب الأحيان","src":"استطلاع مؤسسة غالوب (gallup.com)، بلا سنة في الدليل"},{"n":"190 مليار دولار سنويًا","x":"نفقات الرعاية الصحية الناجمة عن الاحتراق الوظيفي","src":"دراسة لجامعة ستانفورد (gsb.stanford.edu)، بلا سنة في الدليل"},{"n":"8%","x":"من إجمالي نفقات الرعاية الصحية","src":"دراسة لجامعة ستانفورد (gsb.stanford.edu)"},{"n":"120,000 موظف سنويًا","x":"وفيات تسبّب فيها الاحتراق الوظيفي","src":"دراسة لجامعة ستانفورد (gsb.stanford.edu)"},{"n":"70%","x":"الموظفون الذين لديهم وقت كافٍ لأداء عملهم أقل عرضة بهذه النسبة للإرهاق الشديد","src":"تقرير مؤسسة غالوب 2018م"},{"n":"70%","x":"الموظفون الذين يشعرون بدعم قوي من مديرهم أقل عرضة بهذه النسبة للاحتراق الوظيفي","src":"تقرير مؤسسة غالوب 2018م"},{"n":"44%","x":"من الأطباء يعانون من الاحتراق الوظيفي رغم أن وظائفهم كانت شبه مكتبية","src":"دراسة طبية صدرت عام 2019م حول الاحتراق والاكتئاب والانتحار (لم يسمّها الدليل)"},{"n":"2.78 مليون","x":"شخص يموتون كل عام حول العالم بسبب وظائفهم","src":"إحصائيات منظمة العمل الدولية (ILO)، أبريل 2019م"},{"n":"374 مليون","x":"شخص يصابون أثناء العمل","src":"إحصائيات منظمة العمل الدولية (ILO)، أبريل 2019م"},{"n":"19","x":"خطرًا وظيفيًا تمّت دراستها لتحديد أخطرها","src":"تقرير مشترك بين منظمة الصحة العالمية (WHO) ومنظمة العمل الدولية (ILO) نُشر في 2021م (تقديرات 2000، 2016)"},{"n":"750 ألف (750,000)","x":"شخص يموتون سنويًا بسبب ساعات العمل الطويلة، وهو الخطر الأكبر","src":"تقرير WHO وILO المشترك، 2021م"},{"n":"450 ألف (450,000)","x":"شخص يموتون سنويًا بسبب التعرّض للهواء الملوّث في بيئة العمل","src":"تقرير WHO وILO المشترك، 2021م"},{"n":"29%","x":"زيادة نسبة الوفيات بسبب الهواء الملوّث في بيئة العمل منذ عام 2000م","src":"تقرير WHO وILO المشترك، 2021م"},{"n":"42%","x":"ارتفاع نسبة الوفيات بسبب أمراض القلب بين 2000 و2016 بسبب ساعات العمل الطويلة","src":"تقرير WHO وILO المشترك، 2021م"},{"n":"19%","x":"ارتفاع نسبة الوفيات بسبب السكتات الدماغية بين 2000 و2016 بسبب ساعات العمل الطويلة","src":"تقرير WHO وILO المشترك، 2021م"},{"n":"1.9 مليون","x":"شخص يموتون سنويًا بسبب الأمراض والإصابات المرتبطة بالعمل","src":"تقرير WHO وILO المشترك، 2021م"},{"n":"4,764","x":"عاملًا لقوا حتفهم بسبب ظروف العمل الخطرة في الولايات المتحدة","src":"مكتب إحصاءات العمل الأمريكي (BLS)، ملخص تعداد الإصابات المهنية القاتلة 2022"},{"n":"120,000","x":"عامل توفّوا نتيجة لأمراض مهنية في الولايات المتحدة","src":"ذكره الدليل ضمن إحصائيات BLS لعام 2022"},{"n":"343","x":"عاملًا يموتون يوميًا بسبب ظروف العمل الخطرة","src":"تقرير AFL-CIO لعام 2023 (Death on the Job: The Toll of Neglect)"},{"n":"3.6 لكل 100,000 عامل","x":"معدل الوفيات المهنية","src":"تقرير AFL-CIO لعام 2023"},{"n":"أكثر من 450 مليون","x":"شخص حول العالم يعانون من اضطرابات نفسية","src":"المسح الوطني للصحة النفسية وضغوط الحياة، سبتمبر 2020، مركز الملك سلمان لأبحاث الإعاقة مع جامعة هارفارد وجامعة الملك سعود ومنظمة الصحة العالمية (kscdr.org.sa/ar/research/3046)"},{"n":"ثلاث سنوات تقريبًا","x":"مدة أعمال المسح الميداني","src":"المسح الوطني للصحة النفسية وضغوط الحياة، 2020"}]},{"t":"تاريخ تطور مفهوم الاحتراق الوظيفي","src":"guide","pg":7,"p":["تاريخ هذه الظاهرة قديم قدم العمل والإنسان. تطوّر فهمنا لمفهوم الاحتراق الوظيفي عبر العقود، حيث انتقل من مفهوم عام للإرهاق العصبي إلى تعريف محدّد ودقيق، مدعوم بأدوات قياس وأبحاث علمية تعكس تأثيراته على الأفراد والمنظمات."],"key":"انتقل من مفهوم عام للإرهاق العصبي إلى تعريف محدّد ودقيق، مدعوم بأدوات قياس وأبحاث علمية","items":[{"h":"البدايات الأولى: القرن التاسع عشر وأوائل القرن العشرين","x":"ظهرت مفاهيم مبكّرة تتعلّق بالإجهاد المهني تحت مسميات مثل الوهن العصبي (Neurasthenia)، الذي وصفه لأول مرة الطبيب الأمريكي جورج بيرد في عام 1869. كان الوهن العصبي يستخدم لوصف حالات الإرهاق النفسي والجسدي نتيجة للضغوطات المهنية.","grp":"1869"},{"h":"في الستينيات","x":"بدأ الاهتمام يتزايد بمفهوم الإجهاد المرتبط بالعمل، خاصة في أوروبا وأمريكا الشمالية. وظهرت العديد من الدراسات التي تناولت حالات الإرهاق المهني بين العاملين في مجالات مثل الرعاية الصحية والتعليم.","grp":"الستينيات"},{"h":"عام 1969: الكاروشي","x":"عام 1969، تم توثيق أول حالة للكاروشي لموظف يبلغ من العمر 29 عامًا يعمل في قسم النشر في إحدى الصحف الكبرى، وتوفي نتيجة سكتة قلبية بسبب ضغوط العمل، الكاروشي مصطلح ياباني يعني (الموت من الإرهاق)، ويشير إلى الوفاة المفاجئة الناتجة عن العمل المفرط، غالبًا بسبب النوبات القلبية أو السكتات الدماغية. وفي الثمانينات، بدأت الظاهرة تكتسب اهتمامًا أكبر، حيث بدأ الأطباء والمحامون في اليابان بتوثيق الحالات وتقديم الدعم للأسر المتضررة، وتم إنشاء خطوط ساخنة للكاروشي في عام 1988 لتقديم الاستشارات والمساعدة، فالاحتراق الوظيفي يمكن أن يكون مرحلة سابقة للكاروشي، حيث يشعر الفرد بالإرهاق الشديد وفقدان الحافز قبل أن تتفاقم الحالة إلى مشاكل صحية خطيرة.","grp":"الستينيات"},{"h":"في السبعينيات: عام 1974، هربرت فرويدنبرجر","x":"عام 1974، نشر عالم النفس الألماني الأمريكي هربرت فرويدنبرجر، ورقة بحثية بعنوان (Staff Burn-Out) في مجلة Journal of Social Issues، حيث قدّم مفهوم الاحتراق الوظيفي لأول مرة، ووصفه بأنه حالة تتميز بالإرهاق الجسدي والعاطفي نتيجة الضغوط المستمرة في مكان العمل، وتشمل الشعور بالفشل وتدهور الأداء المهني والشخصي.","grp":"السبعينيات"},{"h":"قصة عيادة فرويدنبرجر","x":"هربرت فرودنبيرجر كان متخصّصًا في الصحة النفسية، خاصةً في مشاكل الإدمان، وهو أول من تحدث عن ظاهرة الاحتراق الوظيفي. افتتح عيادة مجانية في ألمانيا لمواجهة وباء الإدمان، ولكن بسبب مجانية العيادة وانتشار الوباء، كانت تواجه ضغطًا كبيرًا. في البداية، تطوّع مجموعة من الشباب والشابات المليئين بالحماس لمساعدته في هذا العمل الخيري. لكن مع مرور الوقت واستمرار الضغط، لاحظ فرويدنبرجر بعد عدة أشهر أن المتطوعين الذين كانوا في البداية متحمّسين ومؤمنين بقيمة عملهم، وبدأوا يظهرون علامات سلبية لم تكن موجودة من قبل. أبرز العلامات التي لاحظها كانت النظرة السلبية والمشاعر السلبية والتبرّم العام المرتبط بالعمل. كان فرويدنبرجر يلاحظ أعراض الإرهاق والاستنزاف الداخلي والشعور المستمر بالإرهاق على مرضاه المدمنين. لكن نظرته تغيّرت عندما لاحظ نفس الأعراض على المتطوعين الشباب في عيادته مع زيادة ضغط وكثافة العمل. رغم محاولاته لتعويضهم ماديًا، استمرت الحالة معهم لدرجة أنهم أهملوا العمل والمرضى. بعد عدة أشهر من الملاحظة والدراسة، استنتج فرويدنبرجر أن هؤلاء المتطوعين يمرّون بحالة من الإرهاق العام، أدّت إلى انخفاض الإحساس بالقيمة التي يقدّمونها، وانخفاض كفاءتهم وإنتاجيتهم، وأحيانًا عدم قدرتهم على الحضور إلى العمل. بعد فترة، بدأ فرويدنبرجر في دراسة هذه الظاهرة وكتب أول ورقة علمية تصفها، وأطلق عليها اسم الاحتراق الوظيفي. كانت هذه الكلمة تُستخدم سابقًا في الأدب والروايات، لكنه كان أول من استخدمها في المجال الصحي الأكاديمي.","grp":"السبعينيات"},{"h":"تعريف فرويدنبرجر","x":"عرف فرويدنبرجر الاحتراق الوظيفي بأنه حالة من الإنهاك النفسي والبدني والعاطفي التي تستنزف الإنسان في جميع هذه الجوانب، مما قد يؤثر على قدرته على الإحساس بقيمة العمل الذي يقدّمه وربما يؤثر على ثقته بنفسه في جودة وكفاءة تقديم العمل.","grp":"السبعينيات"},{"h":"في الثمانينات: عام 1980","x":"عام 1980، بدأ مفهوم الاحتراق الوظيفي يكتسب شهرة واسعة في الأوساط الأكاديمية والمهنية. قامت كريستينا ماسلاك وسوزان جاكسون بتطوير أدوات قياس مثل Maslach Burnout Inventory (MBI) لتقييم مستويات الاحتراق الوظيفي بين العاملين.","grp":"الثمانينات"},{"h":"عام 1981: كريستينا ماسلاش","x":"عام 1981، قامت أستاذة علم النفس كريستينا ماسلاش (Maslach)، بدراسة مفاهيم الاحتراق الوظيفي، ووصفته بأنه مجموعة من أعراض الإجهاد النفسي، وتشمل الإرهاق العاطفي، والتبلّد الشخصي، والإحساس بعدم الرضا عن المنجز الشخصي والأداء المهني، مما ساهم في تعميق الفهم العلمي لهذه الظاهرة ووضع أسس لتحليلها وقياسها.","grp":"الثمانينات"},{"h":"عام 1988: بينس","x":"عام 1988، عرّفت بينس (PINES)، وهي واحدة من الباحثين البارزين في مجال الاحتراق الوظيفي، الاحتراق الوظيفي على أنه حالة من الإرهاق الجسدي والعاطفي والعقلي التي تحدث نتيجة الانخراط طويل الأمد في مواقف تتطلّب جهدًا عاطفيًا كبيرًا.","grp":"الثمانينات"},{"h":"في التسعينيات: عام 1994","x":"عام 1994، أدرجت منظمة الصحة العالمية الاحتراق الوظيفي ضمن التصنيف الدولي للأمراض (ICD-10) كظاهرة مهنية، مما يعكس الاعتراف المتزايد بأهمية هذه الحالة وتأثيرها على الصحة النفسية والجسدية للموظفين.","grp":"التسعينيات"},{"h":"في أواخر التسعينيات","x":"في أواخر التسعينيات، بدأت الأبحاث تركّز بشكل أكبر على العوامل المؤثرة في الاحتراق الوظيفي، مثل بيئة العمل، العلاقات مع الزملاء، ومتطلّبات العمل.","grp":"التسعينيات"},{"h":"في القرن الواحد والعشرين: ديسمبر 2017","x":"في ديسمبر 2017، نشر الباحثان الجزائريان الدكتور علوطي عاشور والدكتور مغار عبد الوهاب دراسة بعنوان \"الاحتراق الوظيفي تعريف وأعراض\"، عرّفا فيها الاحتراق الوظيفي كحالة نفسية تتضمّن مجموعة من الأعراض مثل الإجهاد العاطفي، الاستجابة العدائية تجاه الآخرين، والشعور بانخفاض الإنجاز الشخصي. غالبًا ما تصيب هذه الحالة الأفراد الذين تتطلّب وظائفهم تفاعلًا مستمرًا مع الناس.","grp":"القرن الواحد والعشرون"},{"h":"عام 2019: ICD-11","x":"في عام 2019، أصدرت منظمة الصحة العالمية (WHO) تحديثًا للتصنيف الدولي للأمراض (ICD-11)، حيث أدرجت الاحتراق الوظيفي باعتباره ظاهرة مهنية بشكل رسمي، محددةً أبعاده الثلاثة: الإرهاق العاطفي، والتباعد الشخصي، وانخفاض الكفاءة المهنية.","grp":"القرن الواحد والعشرون"},{"h":"عام 2022: ICD-11 وDSM-5-TR","x":"في عام 2022، أدرجت منظمة الصحة العالمية (WHO) الاحتراق الوظيفي ضمن التصنيف الدولي للأمراض (ICD-11) باعتباره ظاهرة مهنية، وليس حالة طبية. أما بالنسبة للدليل التشخيصي والإحصائي للاضطرابات النفسية (DSM-5)، فقد صدر آخر تحديث له في مايو 2013. ومع ذلك، فقد تم إصدار نسخة محدّثة تُعرف باسم DSM-5-TR (النص المنقّح) في مارس 2022، والتي تضمّنت بعض التعديلات والإضافات على الإصدار السابق، ولكنها لم تصنف الاحتراق الوظيفي على أنه اضطراب نفسي، وإنما يُعترف بالاحتراق الوظيفي باعتباره حالة تؤثر على الصحة النفسية والجسدية نتيجة للإجهاد المزمن في مكان العمل.","grp":"القرن الواحد والعشرون"}]},{"t":"مفاهيم متداخلة مع الاحتراق الوظيفي","src":"guide","pg":11,"p":["يعرّف علماء النفس الاحتراق الوظيفي: بأنه حالة من الإرهاق العاطفي والجسدي والعقلي الناتج عن التعرّض المطوّل والمفرط للإجهاد والضغوطات في بيئة العمل. يحدث الاحتراق الوظيفي عندما يشعر الشخص بعدم الفاعلية وفقدان الدافعية، مما يؤدي إلى انخفاض الأداء والشعور بالإحباط والانعزال.","ومع ذلك، هناك مفاهيم أخرى تتداخل معه وتشترك في بعض الأعراض، لكنها تختلف في السياق والتأثيرات. هذه المفاهيم تعكس جوانب مختلفة من الضغوط النفسية والجسدية التي يمكن أن تؤثر على الأفراد في بيئات العمل المختلفة."],"key":"هناك مفاهيم أخرى تتداخل معه وتشترك في بعض الأعراض، لكنها تختلف في السياق والتأثيرات.","items":[{"h":"الاحتراق النفسي","x":"عبارة عن خبرة نفسية سلبية داخلية تتضمّن المشاعر والاتجاهات والدوافع وتشمل استجابات سلبية وغير ملائمة نحو الغير ونحو الذات، تؤدي إلى فقدان الحيوية والنشاط بشكل عام، وليس فقط في سياق العمل."},{"h":"الضغوط النفسية","x":"هي العوامل الخارجية التي تسبب التوتر والقلق، والتي يمكن أن تؤدي إلى الاحتراق النفسي عند تراكمها بشكل عام، وليس فقط في بيئة العمل، بينما يكون الاحتراق الوظيفي نتيجة تراكم هذه الضغوط في بيئة العمل بشكل خاص."},{"h":"الإجهاد العادي","x":"حالة مؤقتة يمكن التعامل معها من خلال الراحة والاسترخاء، وتكون أعراضها أقل شدة ولا تؤدي إلى تأثيرات طويلة الأمد على الصحة النفسية والجسدية."},{"h":"الإجهاد المزمن","x":"يشمل الإجهاد المستمر الذي يمكن أن يؤدي إلى مشاكل صحية طويلة الأمد، مثل أمراض القلب وارتفاع ضغط الدم، بينما يركز الاحتراق الوظيفي على التأثيرات النفسية والجسدية الناتجة عن بيئة العمل."},{"h":"ضغط العمل","x":"يُعرف بأنه حالة من الإجهاد الجسدي والنفسي الناتجة عن تراكم المسؤوليات والضغوطات التي تتجاوز قدرة الفرد على التحمل، وهو ظرف مؤقت يشعر به الموظف بوضوح، مما يسمح له باتخاذ خطوات للتعامل معه. إذا لم يتم التعامل مع ضغط العمل بشكل فعّال، فإنه يمكن أن يتطور إلى احتراق وظيفي، بينما ينتج الاحتراق الوظيفي عن التعرّض المطول والمفرط للإجهاد والضغوطات في بيئة العمل. وهو يحدث بشكل تدريجي وقد لا يدرك الموظف أنه يعاني منه حتى يصل إلى مراحل متقدمة، حيث يتّسم بفقدان الدافعية والشعور بالإرهاق العاطفي والجسدي."},{"h":"الاكتئاب","x":"اضطراب مزاجي يسبب شعورًا دائمًا بالحزن وفقدان الاهتمام، ويؤثر على كيفية شعور الشخص وتفكيره وسلوكه، مما يمكن أن يؤدي إلى مشاكل عاطفية وجسدية متعددة."},{"h":"القلق","x":"حالة من التوتر المستمر التي يمكن أن تؤثر على الأداء الوظيفي والشخصي، وتزيد من احتمالية الشعور بالإرهاق، بينما الاحتراق الوظيفي هو نتيجة تراكم الضغوط في العمل بشكل خاص."}],"table":{"head":["المفهوم","تعريفه في الدليل","وجه الاختلاف عن الاحتراق الوظيفي كما ورد"],"rows":[["الاحتراق النفسي","خبرة نفسية سلبية داخلية تتضمّن المشاعر والاتجاهات والدوافع","بشكل عام، وليس فقط في سياق العمل"],["الضغوط النفسية","العوامل الخارجية التي تسبب التوتر والقلق","الاحتراق الوظيفي نتيجة تراكم هذه الضغوط في بيئة العمل بشكل خاص"],["الإجهاد العادي","حالة مؤقتة يمكن التعامل معها من خلال الراحة والاسترخاء","لا تؤدي إلى تأثيرات طويلة الأمد"],["الإجهاد المزمن","الإجهاد المستمر الذي يمكن أن يؤدي إلى مشاكل صحية طويلة الأمد","الاحتراق الوظيفي يركز على التأثيرات الناتجة عن بيئة العمل"],["ضغط العمل","ظرف مؤقت يشعر به الموظف بوضوح","الاحتراق يحدث بشكل تدريجي وقد لا يدرك الموظف أنه يعاني منه"],["الاكتئاب","اضطراب مزاجي يسبب شعورًا دائمًا بالحزن وفقدان الاهتمام",""],["القلق","حالة من التوتر المستمر","الاحتراق الوظيفي نتيجة تراكم الضغوط في العمل بشكل خاص"]]},"quote":{"x":"روّحوا القلوب ساعة بعد ساعة فإن القلوب إذا كلّت عميت.","by":"جاء في الأثر"}}],"ev":[{"sid":"gaza2010","x":"العاملين في الوظائف الإدارية في وزارة التربية و التعليم العالي بقطاع غزة والمديريات التابعة لها يعانون بصفة عامة درجات متوسطة من الاحتراق الوظيفي على بعدي الإجهاد الانفعالي و عدم الانسانية، أما على البعد الثالث (الانجاز الشخصي) فقد أظهرت النتائج انخفاض مستوى الاحتراق الوظيفي لدى المبحوثين."},{"sid":"gaza2010","x":"مما سبق نستطيع أن نرى أن ما نسبته 83.7% يعانون من احتراق وظيفي متوسط في حين كان ما نسبته 13.2% يعاني من ارتفاع في مستوى الاحتراق الوظيفي."}],"match":{"t":"رحلة المفهوم عبر الزمن","s":"صل كل سنة بما حدث فيها كما يرويه الدليل.","l":"السنة","r":"ما حدث","pairs":[["1869","جورج بيرد يصف الوهن العصبي"],["1969","توثيق أول حالة كاروشي في اليابان"],["1974","هربرت فرويدنبرجر ينشر مفهوم الاحتراق الوظيفي"],["1981","ماسلاش تصف الاحتراق بثلاثة أعراض"],["2019","ICD-11 يدرج الاحتراق ظاهرةً مهنية بأبعاده الثلاثة"]]},"quiz":[{"q":"لماذا يصف الدليل الاحتراق الوظيفي بأنه مشكلة «خفية»؟","o":["لأنه يبدأ بشكل غير ملحوظ، ويختلط فيه التعب بضغوط العمل","لأن تأثيراته تختلف من شخص لآخر بحسب ظروفه الشخصية والمهنية","لأن صاحبه يكون واعياً به لكنه يخفيه عن زملائه","لأن المنظمات تتجاهله فلا تُرصد أعراضه ولا أسبابه"],"src":"guide","why":"يبدأ الاحتراق الوظيفي بشكل غير ملحوظ، حيث يختلط التعب والإرهاق مع ضغوط العمل اليومية","pg":3},{"q":"بحسب استطلاع غالوب الذي أورده الدليل، كم نسبة الموظفين الذين يتعرضون للاحتراق على الأقل في بعض الأحيان؟","o":["76%","28%","44%","70%"],"src":"guide","why":"من الموظفين يتعرّضون للاحتراق الوظيفي على الأقل في بعض الأحيان","pg":4},{"q":"من نشر مفهوم الاحتراق الوظيفي عام 1974؟","o":["هربرت فرويدنبرجر","كريستينا ماسلاش","الطبيب جورج بيرد","الباحثة سوزان جاكسون"],"src":"guide","why":"هربرت فرودنبيرجر كان متخصّصًا في الصحة النفسية، خاصةً في مشاكل الإدمان، وهو أول من تحدث عن ظاهرة الاحتراق الوظيفي.","pg":7},{"q":"ما معنى «الكاروشي» كما في الدليل؟","o":["مصطلح ياباني يعني الموت من الإرهاق","مقياس ياباني لتقييم مستويات الإرهاق","اسم قديم للوهن العصبي في اليابان","مرحلة الانهيار التام باللغة اليابانية"],"src":"guide","why":"الكاروشي مصطلح ياباني يعني (الموت من الإرهاق)","pg":7},{"q":"كيف أدرج تصنيف ICD-11 الاحتراق الوظيفي؟","o":["ظاهرة مهنية، لا حالة طبية","اضطراباً نفسياً مستقلاً بذاته","مرضاً عضوياً مزمناً يحتاج علاجاً","نوعاً من الاكتئاب المهني"],"src":"guide","why":"باعتباره ظاهرة مهنية، وليس حالة طبية.","pg":7},{"q":"ما الفرق بين الإجهاد العادي والاحتراق الوظيفي كما يعرضه الدليل؟","o":["الإجهاد العادي مؤقت، ويزول بالراحة والاسترخاء","الإجهاد العادي يركز على آثار بيئة العمل دون غيرها","الإجهاد العادي يحدث تدريجياً فلا يدركه الموظف","الإجهاد العادي يؤدي إلى مشاكل صحية طويلة الأمد"],"src":"guide","why":"حالة مؤقتة يمكن التعامل معها من خلال الراحة والاسترخاء","pg":11}]},{"k":"why","t":"أبعاده وأسبابه","ic":"layers","q":"ممّ يتكون الاحتراق الوظيفي، وما الذي يشعله؟","sections":[{"t":"أبعاد الاحتراق الوظيفي","src":"guide","pg":16,"p":["وفقاً للتحليل المفاهيمي الذي قام به كل من ماسلاش وجاكسون يُنظر إلى الاحتراق على أنه متلازمة تتكوّن من أبعاد ثلاثة:"],"key":"يُنظر إلى الاحتراق على أنه متلازمة تتكوّن من أبعاد ثلاثة","items":[{"h":"الإنهاك العاطفي","x":"شعور الموظف باستنزاف موارده العاطفية، مما يؤدي إلى فقدان الثقة بالنفس والروح المعنوية، وفقدان الاهتمام بالمستفيدين من الخدمة، يصاحب هذا الشعور بالإحباط والتوتر، ويشعر الموظف بعدم القدرة على الاستمرار في أداء مسؤولياته بنفس الكفاءة. من الأعراض الشائعة لهذا الإنهاك الشعور بالرهبة عند التفكير في الذهاب إلى العمل، ويحدث عادة بسبب المتطلّبات النفسية والعاطفية المفرطة من الجمهور."},{"h":"الشعور بتدني الإنجاز الشخصي","x":"الإحساس بانخفاض الكفاءة والإنتاجية، مما يؤدي إلى تقييم الذات بشكل سلبي والشعور بالفشل. يحدث هذا عندما يفقد الموظف الالتزام الشخصي في العمل، خاصة عند تكرار محاولاته الفاشلة في تحقيق نتائج إيجابية، مما يسبب له التوتر والاكتئاب. عندما يعتقد الموظف أن جهوده لن تكون فعّالة، فإنه يتخلّى عن المحاولات."},{"h":"فقدان العنصر الإنساني أو الشخصي في التعامل","x":"يشير إلى استجابة سلبية تتمثّل في تجريد المستفيدين من الصفة الشخصية، مما يؤدي إلى معاملة الأفراد باعتبارهم أشياء وليسوا بشرًا. يتصف الموظفون في هذه الحالة بالقسوة والتشاؤم وكثرة الانتقاد، مما يؤثر سلبًا على زملائهم والمستفيدين من الخدمة. هذا التجريد يمكن أن يقلّل من التأجّج العاطفي المفرط ويعمل كوسيلة دفاعية للتقليل من الشعور بالذنب والإحباط. المستويات المتوسطة من هذا التجريد قد تكون ضرورية للأداء الفعّال في بعض الوظائف."}]},{"t":"مثلث الاحتراق: الحرارة والوقود والأكسجين","src":"guide","pg":17,"p":["د. هربرت فرودبنجر كان أول من وضع مفهوم الاحتراق الوظيفي، مشبّهاً إياه بمبنى محترق يبدو هيكله الخارجي سليماً بينما كان داخله مدمراً. عندما ترى شيئًا يحترق، قد يحتفظ بشكله الخارجي بعد الاشتعال، لكنه ينهار بالكامل عند ملامسته. الموظفون يمرون بحالة مشابهة بسبب التوترات الناتجة عن العمل؛ يحترقون من الداخل رغم أنهم قد يظهرون طبيعيين من الخارج.","تخيّل ورقة تتعرّض لمصدر حرارة حتى تصل إلى درجة الاشتعال، يمكن إطفاء الحريق في مراحله الأولى، مما يترك الورقة محافظة على شكلها الخارجي، لكنها تصبح هشّة من الداخل وتتناثر عند ملامستها، وإذا لم نتدخل لإطفاء الحريق في الوقت المناسب، قد لا تحافظ الورقة حتى على شكلها الخارجي.","هذا يشبه حالة الموظف الذي يعاني من الاحتراق الوظيفي، حيث يبدو متماسكًا من الخارج لكنه هش من الداخل. الاحتراق الوظيفي هو نتيجة لفترة طويلة من الإنهاك والضغوط المستمرة، مما يؤثر على الموظف.","من الذي يتعرض للاحتراق الوظيفي؟ مثلث الاحتراق، المعروف أيضًا بمثلث النار، يوضح العناصر الثلاثة الأساسية اللازمة لاشتعال النار: الحرارة، والوقود، والأكسجين وإذا غاب أي من هذه العناصر، فإن النار تنطفئ. يمكن تطبيق هذا المفهوم بشكل مجازي على بيئة العمل لفهم العناصر الأساسية التي تؤدي إلى الاحتراق الوظيفي، هذا التشبيه يساعد في توضيح كيف يمكن لعوامل مثل: التعرض للضغط، فقد الدافع، غياب الدعم أن تؤثر على صحة الموظف النفسية والجسدية. يمكن تشبيه الاحتراق الوظيفي بمثلث الاحتراق الفيزيائي، فمثلما يتكون مثلث النار من الحرارة والوقود والأكسجين، يتكون مثلث الاحتراق الوظيفي من: الضغط (الحرارة)، والدافع (الوقود)، والدعم (الأكسجين). عندما تتوفر هذه العناصر بشكل غير متوازن، يحدث الاحتراق الوظيفي، مما يؤثر على صحة الموظف."],"key":"يتكون مثلث الاحتراق الوظيفي من: الضغط (الحرارة)، والدافع (الوقود)، والدعم (الأكسجين). عندما تتوفر هذه العناصر بشكل غير متوازن، يحدث الاحتراق الوظيفي","items":[{"h":"الحرارة (التعرض للضغط)","x":"الضغوط المتزايدة والمستمرة في العمل تؤدي إلى انخفاض الروح المعنوية وزيادة المشاعر السلبية، مما يزيد من احتمالية الوقوع في الأخطاء والإصابة بالاحتراق الوظيفي.","grp":"مثلث الاحتراق"},{"h":"الوقود (فقد الدافع)","grp":"مثلث الاحتراق"},{"h":"الأكسجين (غياب الدعم)","x":"الموظف المُنهك يفقد الدافع ولا يستطيع إنجاز مهامه بنفس الكفاءة السابقة. غياب الدعم من الزملاء والإدارة يزيد من شعوره بالعزلة، مما يُغَذِّي مشاعره السلبية ويؤدي إلى احتراقه الوظيفي.","grp":"مثلث الاحتراق"},{"h":"لمن يحدث الاحتراق الوظيفي؟ الحرارة/ التعرض للضغط","x":"الاحتراق الوظيفي يصيب الموظفين الذين يبذلون جهدًا كبيرًا في أداء مهامهم، ولديهم تطلّعات مهنية عالية، مليئين بالنشاط والحيوية ويشعرون بالسعادة في عملهم ويواجهون التحديات من أجل تحقيق أهدافهم المهنية، ويعملون بشغف مفرط، مما يؤدي إلى ضغط مستمر يؤثر على جوانب حياتهم الأخرى ويستنزف طاقاتهم. فجأة! يشعرون بضغط غير معتاد، وينخفض مستوى الدافع لديهم، ويشعرون بالإنهاك العاطفي واستنزاف الطاقة وتدني مستوى الإنجاز، وقد يفقدون العنصر الإنساني في التعامل. من ناحية أخرى، هناك أشخاص لا يحبون العمل على الإطلاق، ويميلون بطبيعتهم للراحة والاستمتاع، أو يميلون للسلبية والتشاؤم، قد تظهر لدى هؤلاء أعراض مشابهة لأعراض الاحتراق عند تعرّضهم لأي ضغط حتى وإن كان بسيطًا، ولكن هذا لا يعدُّ احتراقًا وظيفيًا حقيقيًا. الاحتراق الوظيفي مرتبط بالعمل، يأتي بعد فترة من مسيرة مهنية حافلة بالإنجاز والتميّز. ولتمييز الأعراض، فإنه علينا فهم طبيعة الشخص وظروفه. يجب على الموظف معرفة متى يصل إلى مرحلة لا يستطيع فيها تقديم شيء للعمل أو لحياته الشخصية، بعد أن كان قادرًا على العطاء بتميز، وهنا يجب أن يجد علاجًا فعليًا.","grp":"لمن ومتى وكيف"},{"h":"متى يحدث الاحتراق الوظيفي؟ الوقود/ فقد الدافع","x":"الاحتراق الوظيفي يحدث عندما يفقد الموظف دافعه الشخصي، سواء كان إيجابيًا مثل الشغف والأهداف، أو سلبيًا مثل الشعور بالإجبار أو الخوف من العواقب، وهذا يؤدي إلى تراجع في الأداء والشعور بالإرهاق. حيث يصل الشخص إلى مرحلة يفقد فيها الحيوية والنشاط الذي كان يتمتع به سابقًا بسبب الضغط المستمر وعدم إعطاء النفس فرصة للاسترخاء والتجديد. يمكن تشبيه ذلك بشخص يقود سيارة دون أن يتوقف لتعبئة الوقود، في النهاية، لن يتمكن من الوصول إلى وجهته لأن السيارة ستتوقف بسبب نفاد الوقود.","grp":"لمن ومتى وكيف"},{"h":"كيف يحدث الاحتراق الوظيفي؟ الأكسجين/ غياب الدعم","x":"يحدث الاحتراق الوظيفي عندما يتعرّض الموظف لضغوط عمل مستمرة دون فترات راحة كافية، مما يؤدي إلى مستويات عالية من التوتر والإثارة. هذا التوتر المستمر يسبب فقدان الحافز الشخصي والشعور بالإحباط. ومع غياب الدعم وافتقار بيئة العمل إلى التغذية الراجعة والمكافآت، يشعر الموظف بأن جهوده غير مجدية وغير مقدّرة، مما يؤدي به إلى الإنهاك العاطفي. وفي محاولة للتعامل مع هذه الحالة، قد يفقد الموظف العنصر الإنساني في التعامل مع الآخرين، مما يزيد من شعوره بتدني الإنجاز الشخصي.","grp":"لمن ومتى وكيف"}]},{"t":"العوامل والأسباب المؤدية للاحتراق الوظيفي","src":"guide","pg":20,"p":["يحدث الاحتراق الوظيفي عندما لا تتوافق طبيعة العمل مع طبيعة الشخص الذي يؤديه، فكلما زاد التباين بينهما زادت احتمالية زيادة الاحتراق الوظيفي. ينجم هذا الاحتراق عن أسباب مرتبطة بثلاثة أبعاد رئيسية: الفردي، والمهني، والاجتماعي. لفهم هذه الظاهرة، يجب التمييز بين العوامل التي تهيئ البيئة للاحتراق الوظيفي والأسباب المباشرة التي تؤدي إليه. العوامل هي الظروف أو المتغيرات التي تهيئ البيئة لحدوث الاحتراق النفسي، مثل العوامل الفردية، أو بيئة العمل، أو العلاقات الاجتماعية. هذه العوامل لا تسبب الاحتراق بشكل مباشر، لكنها تهيئ الظروف التي يمكن أن تؤدي إليه. أما الأسباب فهي الأحداث أو الظروف المحددة التي تؤدي مباشرة إلى الاحتراق الوظيفي، نتيجة لتفاعل العوامل المختلفة.","البعد الفردي: اتفقت معظم الدراسات على أن الإنسان الأكثر انتماءً والتزاماً بعمله وإخلاصاً له هو الأكثر تعرّضاً للاحتراق الوظيفي مقارنة بغيره من العاملين. يُفسر ذلك بأن هذا الإنسان يقع تحت تأثير ضغط العمل الذي يعمل فيه. يمكن تلخيص الأسباب التي تجعل الموظف عرضة للاحتراق الوظيفي كما يلي:","البعد الاجتماعي: تجد العديد من المنظمات نفسها مضطرة لتحمّل عبء العمل الناتج عن أفراد المجتمع الذين يلقون بأعبائهم عليها، مما يزيد من الضغط الوظيفي على العاملين. هؤلاء العاملون، الذين يسعون لتحقيق التوازن بين مصلحة العمل وأهدافه ورسالة المنظمة، ومصلحة المواطنين، يجدون أنفسهم غير قادرين على تقديم خدمات متميزة. هذا يؤدي إلى شعورهم بالإحباط والتراجع أمام متطلّبات مجتمعهم، مما يسبب لهم حالة من عدم التوازن الشخصي ويجعلهم عرضة للاحتراق الوظيفي. يمكن تلخيص الأسباب التي تجعل الموظف عرضة للاحتراق الوظيفي كما يلي:","البعد المهني: عندما تكون المهنة ومتطلّباتها هي المحدد الرئيسي لانتماء العاملين لعملهم والتزامهم بأهدافهم، فإن ظروف العمل وبنيته تلعبان دورًا كبيرًا في زيادة أو تقليل ضغط العمل عليهم. وبالتالي، فإن شعور الموظف بالفشل في تحقيق أهداف العمل أو في تلبية احتياجاته الأساسية من خلال العمل يمكن أن يؤدي إلى انخفاض معنوياته وعدم رضاه عن العمل، مما يقوده إلى الاحتراق الوظيفي. يمكن تلخيص الأسباب التي تجعل الموظف عرضة للاحتراق الوظيفي كما يلي:","الآن بعد أن تعرّفت على هذه العوامل والأسباب، إذا وجدت أنك تعاني من أي منها، فلا تتخذ قرارًا متسرّعًا. حاول تقييم الوضع بعناية وفكّر في الخطوات التي يمكن اتخاذها لتحسين بيئة العمل وتقليل الضغط والإجهاد قبل الوصول إلى مرحلة الاحتراق الوظيفي."],"key":"اتفقت معظم الدراسات على أن الإنسان الأكثر انتماءً والتزاماً بعمله وإخلاصاً له هو الأكثر تعرّضاً للاحتراق الوظيفي مقارنة بغيره من العاملين.","items":[{"h":"الإنهاك العاطفي","x":"عندما يتعرّض الموظف بشكل متكرر لمتطلّبات مهنية هامة، قد يلجأ إلى فقدان العنصر الإنساني أو الشخصي في التعامل مع المستفيدين كوسيلة للتكيّف مع هذه الضغوط، مما يؤدي إلى شعور بانخفاض الإنجاز الشخصي.","grp":"البعد الفردي"},{"h":"مثيرات التوتر للموظف","x":"يمكن أن تكون متنوعة وتشمل عوامل داخل بيئة العمل وخارجها، تجعل الموظف يشعر بعدم القدرة على تحقيق توازن بين العمل والحياة الشخصية، مما يؤدي إلى الإرهاق والإجهاد المستمر.","grp":"البعد الفردي"},{"h":"مثيرات التوتر داخل بيئة العمل","x":"داخل بيئة العمل، قد يواجه الموظف عبء الدور وصراعه، عقود العمل المؤقتة، وتدني مستوى الأجور، مما يزيد من التزامات ومسؤوليات الموظف الشخصية ويؤدي إلى مستويات عالية من التوتر. بالإضافة إلى ذلك، قد تكون هناك مشاكل في الإدارة والقيادة، وأزمات مالية سواء في العمل أو على الصعيد الشخصي.","grp":"البعد الفردي"},{"h":"مثيرات التوتر خارج بيئة العمل","x":"خارج بيئة العمل، يمكن أن تشمل مثيرات التوتر المتطلّبات المرتفعة في العمل أو الدراسة، والمشكلات الاجتماعية، وتراكم المسؤوليات، وفقدان الدعم من الآخرين.","grp":"البعد الفردي"},{"h":"التوقعات العالية من النفس","x":"التوقعات العالية من النفس يمكن أن تزيد من الضغط والإجهاد، خاصة إذا لم يتم تحقيق هذه التوقعات، مما يؤدي إلى شعور بالإحباط والفشل، ويؤثر سلبًا على الصحة النفسية والجسدية وجودة الحياة.","grp":"البعد الفردي"},{"h":"الخصائص الشخصية","x":"ضعف الاستعداد للتعامل مع ضغوط العمل، والشعور بالرتابة والملل، وعدم الرغبة في العمل، والشعور بالمكانة الأقل، والخبرات السلبية، فقدان الشغف والدافعية.","grp":"البعد الفردي: الخصائص الشخصية"},{"h":"تدني مستوى التعليم والثقافة، وضعف مهارات التكيّف، يؤدي إلى صعوبة التعامل مع العوامل التنظيمية والخارجية.","grp":"البعد الفردي: الخصائص الشخصية"},{"h":"القيم والخبرات السلبية والسمات الفردية تؤثر في تقييم المواقف والتحكم في ردود الأفعال ومدى الإشباع الفردي من العمل.","grp":"البعد الفردي: الخصائص الشخصية"},{"h":"الأفراد الذين يعتبرون العمل كل حياتهم وليس لديهم حياة خارجية تشبع حاجاتهم الأساسية وتوفّر لهم الدعم، ويربطون رضاهم عن أنفسهم بالإنجازات المادية، ويعتبرون الترفيه رفاهية زائدة. وسيلتهم الوحيدة للترفيه هي مواقع التواصل الاجتماعي، والتي قد تقود أيضًا إلى مشاعر سلبية.","grp":"البعد الفردي: الخصائص الشخصية"},{"h":"الشخصية التي تتسم بعدم التعاون، والقلق، والكمالية، تجعل الأفراد طموحين بشكل غير معتاد ويميلون إلى المثالية، ويهدفون إلى مناصب معيّنة خلال فترات محددة.","grp":"البعد الفردي: الخصائص الشخصية"},{"h":"الكتمان وعدم القدرة على قول \"لا\" يزيد من الضغوط.","grp":"البعد الفردي: الخصائص الشخصية"},{"h":"الأفراد الذين يسيطر عليهم القلق المستمر بشأن المستقبل، خاصة مع تدني مستوى تقدير الذات والثقة بالنفس، مما قد يؤدي إلى تدهور الصحة الجسدية.","grp":"البعد الفردي: الخصائص الشخصية"},{"h":"عدم وجود نظام اتصال فعّال لخدمات العملاء، وذلك يؤدي إلى صعوبة في التواصل مع العملاء وحل مشكلاتهم بسرعة، مما يزيد من الضغط على الموظفين ويؤثر على جودة الخدمة المقدمة.","grp":"البعد الاجتماعي"},{"h":"التعامل مع عملاء ومراجعين عصبيين مما يجعل الموظف يقضي وقته في حل المشاكل وتهدئتهم.","grp":"البعد الاجتماعي"},{"h":"بيئة العمل السلبية والدعم الاجتماعي الضعيف يؤديان إلى شعور الموظفين بالعزلة وعدم الانتماء، مما يقلل من رضاهم الوظيفي ويزيد من احتمالية تعرضهم للاحتراق الوظيفي.","grp":"البعد الاجتماعي"},{"h":"عدم وجود وقت كافٍ لتحقيق متطلّبات الحياة الاجتماعية يجعل الموظفين يشعرون بالإرهاق والتوتر نتيجة عدم قدرتهم على التوازن بين العمل والحياة الشخصية، مما يؤثر سلباً على صحتهم النفسية والجسدية.","grp":"البعد الاجتماعي"},{"h":"التمييز وعدم الحيادية يسبّبان توترات وصراعات داخل الفريق، مما يؤثر على التعاون والإنتاجية ويزيد من الضغط النفسي على الموظفين.","grp":"البعد الاجتماعي"},{"h":"الصراع الأسري والمشكلات المادية تزيد من التوتر والقلق لدى الموظفين، مما يؤثر على أدائهم في العمل ويزيد من احتمالية تعرّضهم للاحتراق الوظيفي.","grp":"البعد الاجتماعي"},{"h":"العلاقات الشخصية المتوترة تؤدي إلى بيئة عمل غير مريحة، حيث يشعر الموظفون بعدم الأمان وعدم القدرة على التعبير عن آرائهم بحرية، مما يؤثر على روح الفريق والإنتاجية.","grp":"البعد الاجتماعي"},{"h":"كثرة الزيارات الميدانية ضمن توزيع جغرافي واسع قد تعيق متابعة العمل بشكل فعّال، خاصة مع ضرورة السفر المستمر.","grp":"البعد المهني: مهام العمل المجهدة"},{"h":"أداء مهام إضافية دون توجيه أو تدريب.","grp":"البعد المهني: مهام العمل المجهدة"},{"h":"الأعمال الروتينية التي تؤدي إلى انخفاض جودة الأعمال وغياب الإبداع والابتكار.","grp":"البعد المهني: مهام العمل المجهدة"},{"h":"المهام العاجلة وغير الواضحة التي تُطلب في آخر لحظة دون تعليمات واضحة أو تحديد أولويات.","grp":"البعد المهني: مهام العمل المجهدة"},{"h":"تكليف الموظفين بمهام تتطلّب ساعات عمل إضافية طويلة دون تعويض.","grp":"البعد المهني: مهام العمل المجهدة"},{"h":"عبء ساعات العمل الطويلة وغير المنتظمة.","grp":"البعد المهني: مهام العمل المجهدة"},{"h":"مطالبة الموظفين بإنجاز مهام أثناء الإجازات الرسمية في ظروف بيئية غير مناسبة.","grp":"البعد المهني: مهام العمل المجهدة"},{"h":"إحساس الموظفين بضغط كبير عند محاولة إنجاز مهام عديدة في وقت قصير وبإمكانات محدودة، خاصة مع تقليص عدد الموظفين وزيادة الأعباء على الباقين.","grp":"البعد المهني: مهام العمل المجهدة"},{"h":"عدم تطبيق المعايير التي تحفظ حقوق الموظفين وكرامتهم وسلامتهم.","grp":"البعد المهني: البيئة التنظيمية"},{"h":"تزايد البيروقراطية مع عدم وجود تراتبية واضحة لتوكيل المهام غير الضرورية.","grp":"البعد المهني: البيئة التنظيمية"},{"h":"المشاكل التكنولوجية والنقص في الإمكانات المادية.","grp":"البعد المهني: البيئة التنظيمية"},{"h":"عدم وجود خطة عمل واضحة أو عدم الالتزام بالتوصيف الوظيفي المتفق عليه.","grp":"البعد المهني: البيئة التنظيمية"},{"h":"الضغط العام من الإدارة عند تطبيق المعايير والقوانين الخاصة بالعمل.","grp":"البعد المهني: البيئة التنظيمية"},{"h":"سوء التنظيم والتخطيط الإداري يمكن أن يتجلّى في صرامة وجمود التنظيم، التأخير في اتخاذ القرارات الهامة وعدم وضوح المسؤول المباشر عنها، بالإضافة إلى السياسات الغامضة أو التحكمية، وعجز الإدارة عن وضع خطط فعّالة.","grp":"البعد المهني: البيئة التنظيمية"},{"h":"عدم وضوح سياسات وإجراءات العمل يمكن أن يسبب ارتباكًا وضغطًا على الموظفين، مما يجعلهم يشعرون بعدم الأمان وعدم القدرة على أداء مهامهم بكفاءة.","grp":"البعد المهني: البيئة التنظيمية"},{"h":"التمييز بين الموظفين الذي يؤدي إلى خلق العداوة.","grp":"البعد المهني: الثقافة المؤسسية"},{"h":"التغاضي عن المخالفات تحت ذريعة الظروف الطارئة.","grp":"البعد المهني: الثقافة المؤسسية"},{"h":"عدم الاكتراث للملاحظات والاقتراحات.","grp":"البعد المهني: الثقافة المؤسسية"},{"h":"إعداد خطط واستراتيجيات غير واقعية دون استشارة الموظفين أو الأخذ بآرائهم.","grp":"البعد المهني: الثقافة المؤسسية"},{"h":"ثقافة العمل السلبية، مثل عدم التعاون بين الزملاء أو عدم وجود دعم من الإدارة، تؤثر بشكل كبير على الروح المعنوية للموظفين وتزيد من شعورهم بالإحباط.","grp":"البعد المهني: الثقافة المؤسسية"},{"h":"مواجهة الموظفين لمآسٍ عديدة دون القدرة على تقديم المساعدة.","grp":"البعد المهني: العلاقات المهنية"},{"h":"ضعف قدرات الإدارة في التواصل واتخاذ القرارات المناسبة في الوقت المناسب.","grp":"البعد المهني: العلاقات المهنية"},{"h":"عدم الشعور بالتقدير تجاه العاملين الذين يعملون تحت الضغط.","grp":"البعد المهني: العلاقات المهنية"},{"h":"العلاقات العكسية بين كفاءة فريق العمل وعدم تعاونه وتلكؤ البعض في أداء مهامهم.","grp":"البعد المهني: العلاقات المهنية"},{"h":"الاعتماد على الآخرين وعدم تقدير الإدارة لجهودهم.","grp":"البعد المهني: العلاقات المهنية"},{"h":"القيادة غير الفعّالة التي تؤدي إلى عدم الرضا بين الموظفين وزيادة التوتر.","grp":"البعد المهني: العلاقات المهنية"},{"h":"نقص الدعم من الإدارة الذي يجعل الموظف يشعر بالإحباط وعدم القدرة على تحقيق أهدافه، مما يزيد من احتمالية الاحتراق الوظيفي.","grp":"البعد المهني: العلاقات المهنية"},{"h":"ضعف التواصل بين الإدارة والموظفين الذي يؤدي إلى سوء الفهم.","grp":"البعد المهني: العلاقات المهنية"}]},{"t":"النظريات النفسية المفسرة للاحتراق الوظيفي","src":"guide","pg":66,"p":["هناك العديد من النظريات التي نشرت ظاهرة الاحتراق الوظيفي خاصة من الناحية النفسية ومنها:","من الضروري عدم الاقتصار على نظرية واحدة بل دمج الآراء المختلفة لتحقيق فهم شامل ومستنير.","الاحتراق الوظيفي هو مرحلة متقدمة من الضغوط النفسية الناتجة عن تفاعل سمات الفرد مع بيئة غير مناسبة، مما يجعله يشعر بعدم الراحة، مع مراعاة أن بعض الأفراد لديهم استعدادًا أكبر للإصابة بالاحتراق الوظيفي مقارنةً بغيرهم."],"key":"الاحتراق الوظيفي هو مرحلة متقدمة من الضغوط النفسية الناتجة عن تفاعل سمات الفرد مع بيئة غير مناسبة، مما يجعله يشعر بعدم الراحة","items":[{"h":"النظرية السلوكية","x":"تفسّر النظرية السلوكية الاحتراق الوظيفي في ضوء عملية التعلم أنه سلوك غير سوي يتعلمه الفرد نتيجة العوامل البيئية غير المناسبة وفي حال عدم تعلم الفرد سلوكيات تكيفية مقبولة فإنه قد يحدث الاحتراق الوظيفي وترفض النظرية السلوكية أن يعزى الاحتراق إلى تعامل الفرد مع الآخرين فحسب بل يضاف إلى ذلك العوامل البيئية أو الضغوط التي يتعرض لها الفرد."},{"h":"النظرية المعرفية","x":"ترى النظرية المعرفية أن مصدر سلوك الإنسان داخلي معرفي كالعمليات العقلية التي يدرك من خلالها الفرد الموقف ليستجيب ويحقّق الهدف المحدّد فإذا كان إدراكه للموقف إيجابيًا فسينتج عنه الرضا وارتفاع المعنويات أما إذا كان إدراكه للموقف سلبياً فقد يؤدي إلى أعراض الاحتراق الوظيفي."},{"h":"النظرية الوجودية","x":"تركز النظرية الوجودية في تفسيرها للاحتراق الوظيفي على عدم وجود المعنى في حياة الفرد فحينما يفقد الفرد المعنى والمغزى في حياته فإنه يعاني نوعاً من الفراغ الوجودي الذي يجعله يشعر بعدم أهمية حياته ويحرمه من التقدير الذي يشجعه على مواصلة حياته فلا يحقّق أهدافه ما يعرّضه للاحتراق الوظيفي لذلك فالعلاقة بين الاحتراق الوظيفي وعدم الإحساس بالمعنى علاقة تبادلية فالاحتراق الوظيفي يؤدي إلى فقدان المعنى من حياة الفرد كما أن فقدان المعنى يمكن أن يؤدي إلى الاحتراق الوظيفي."},{"h":"نظرية التحليل النفسي","x":"فسّرت نظرية التحليل النفسي الاحتراق الوظيفي على أنه ناتج عن عملية ضغط الفرد على الأنا لمدة طويلة وذلك مقابل الاهتمام بالعمل مما قد يمثّل جهداً مستمراً لقدرات الفرد مع عدم قدرته على مواجهة تلك الضغوط بطريقة سوية أو أنه ناتج عن عملية الكبت أو الكف للرغبات غير المقبولة بل المتعارضة في مكونات الشخصية ما ينشأ عنه صراع بين المكونات يؤدي إلى أقصى مراحل الاحتراق الوظيفي أو أنه ناتج عن فقدان الأنا المثل الأعلى لها وحدوث فجوة بين الأنا والآخر الذي تعلّقت به وفقدان الفرد جانب المساندة التي كان ينتظرها كما أنه يمكن استخدام بعض فنّيات مدرسة التحليل النفسي لعلاج الاحتراق الوظيفي كالتنفيس الانفعالي."}]}],"ev":[{"sid":"gaza2010","x":"وبشكل عام يمكن القول بأن المتوسط الحسابي يساوي 3.02، وأن المتوسط الحسابي النسبي لجميع فقرات المجال يساوي 60.45 ... لذلك يعتبر مجال \" الإجهاد الانفعالي \" غير دالة إحصائياً ... و هذا يدل على أن الموظفين غير قادرين على إعطاء رؤية واضحة تعكس مدى معاناتهم من الاحتراق على هذا البعد."},{"sid":"gaza2010","x":"وبشكل عام يمكن القول بأن المتوسط الحسابي يساوي 2.32، وأن المتوسط الحسابي النسبي لجميع فقرات المجال يساوي 46.36 ... مما يعكس عدم معاناة المبحوثين من احتراق على هذا البعد."},{"sid":"gaza2010","x":"وبشكل عام يمكن القول بأن المتوسط الحسابي يساوي 3.77، وأن المتوسط الحسابي النسبي لجميع فقرات المجال يساوي 75.39 ... مما يعكس عدم معاناة الموظفين من احتراق وظيفي على هذا البعد حيث إن هذا البعد معكوس بمعنى أن الموافقة تعني احتراق منخفض."},{"sid":"jeddah","x":"العاملين في الوظائف الإدارية في وزارة الشؤون البلدية والقروية، أمانة محافظة جدة يعانون بصفة عامة درجات مرتفعة من الاحتراق الوظيفي على بعدي الإجهاد الانفعالي والانجاز الشخصي، أما على البعد الثالث عدم الإنسانية فقد أظهرت النتائج انخفاض مستوى الاحتراق الوظيفي لعينة الدراسة."},{"sid":"jeddah","x":"هناك علاقة عكسية ذات دلالة إحصائية بين صلاحيات العمل ودرجة الاحتراق الوظيفي بأبعاده الثلاثة. (معامل ارتباط بيرسون 0.260 دال عند 0.05، جدول 20)"},{"sid":"jeddah","x":"توجد علاقة طردية ذات دلالة إحصائية بين انعدام العلاقات الاجتماعية ودرجة الاحتراق الوظيفي بأبعاده الثلاثة مما يعني أنه كلما زاد انعدام العلاقات الاجتماعية السائدة بين العاملين كلما زاد الاحتراق الوظيفي بأبعاده الثلاثة فالعلاقات الإيجابية حتماً تنعكس على الموظفين سواء مع المراجعين أو المدراء. (معامل ارتباط بيرسون 0.370 دال عند 0.001)"},{"sid":"syria","x":"أظهرت النتائج أن الاحتراق الوظيفي ظاهر بين العاملين في المنظمات الإنسانية، وذلك نتيجة ظروف العمل غير المواتية من حيث طول ساعات العمل والمهام المفاجئة والعاجلة."},{"sid":"syria","x":"كما ظهر أن الاحتراق الوظيفي ناتج عن عدم توفر العدالة والمساواة بين العاملين، وعدم التقدير من قبل الإدارة لجهود العاملين."},{"sid":"syria","x":"من الجدول السابق يتضح أن الموظفين مستنزفون عاطفياً ومستهلكون بنهاية يوم عملهم، كما أن عملهم بجد وجهد كبير مع أشخاص يشكل مزيداً من الضغط، وقد جاءت جميع الإجابات السابقة بدرجة الموافق (المتوسطات 3.47 و3.74 و3.52). ... مع تأكيد ظهور حالات احتراق وظيفي حسب مجموعة التركيز، إلا أنها لم تصل إلى الدرجة العالية، وهذا ما أظهرته الإجابات على الاستبيان في العبارات السابقة."}],"sort":{"t":"فردي أم اجتماعي أم مهني؟","s":"صنّف كل سبب في بعده كما في الدليل.","bins":["البعد الفردي","البعد الاجتماعي","البعد المهني"],"items":[["التوقعات العالية من النفس",0],["الكتمان وعدم القدرة على قول «لا»",0],["التعامل مع عملاء ومراجعين عصبيين",1],["الصراع الأسري والمشكلات المادية",1],["تكليف الموظفين بساعات عمل إضافية طويلة دون تعويض",2],["عدم وضوح سياسات وإجراءات العمل",2]]},"match":{"t":"مثلث الاحتراق","s":"صل كل عنصر من مثلث النار بما يقابله في الاحتراق الوظيفي.","l":"العنصر","r":"ما يقابله","pairs":[["الحرارة","التعرض للضغط"],["الوقود","فقد الدافع"],["الأكسجين","غياب الدعم"]]},"quiz":[{"q":"ما الأبعاد الثلاثة للاحتراق وفق تحليل ماسلاش وجاكسون؟","o":["الإنهاك العاطفي، وتدني الإنجاز، وفقد العنصر الإنساني","التعرض للضغط، وفقد الدافع، وغياب الدعم من الزملاء والإدارة","الإنذار، والمقاومة، والإجهاد المستمر للموظف","البعد الفردي، والبعد المهني، والبعد الاجتماعي"],"src":"guide","why":"وفقاً للتحليل المفاهيمي الذي قام به كل من ماسلاش وجاكسون يُنظر إلى الاحتراق على أنه متلازمة تتكوّن من أبعاد ثلاثة","pg":16},{"q":"في مثلث الاحتراق، ماذا يمثل «الأكسجين»؟","o":["الدعم","الضغط","الدافع","الحافز"],"src":"guide","why":"يتكون مثلث الاحتراق الوظيفي من: الضغط (الحرارة)، والدافع (الوقود)، والدعم (الأكسجين).","pg":17},{"q":"من الأكثر تعرضاً للاحتراق بحسب ما اتفقت عليه معظم الدراسات في الدليل؟","o":["الأكثر انتماءً والتزاماً بعمله وإخلاصاً له","الأقل رغبة في العمل والأميل إلى الراحة والاستمتاع","حديث التعيين الذي يصطدم بواقع العمل الجديد","الأقل خبرة ومهارة في التكيف مع الضغوط"],"src":"guide","why":"اتفقت معظم الدراسات على أن الإنسان الأكثر انتماءً والتزاماً بعمله وإخلاصاً له هو الأكثر تعرّضاً للاحتراق الوظيفي مقارنة بغيره من العاملين.","pg":20},{"q":"بأي شيء شبّه فرويدنبرجر الاحتراق الوظيفي؟","o":["بمبنى محترق يبدو هيكله الخارجي سليماً","بسيارة توقفت لنفاد وقودها في الطريق","بورقة احترقت ففقدت شكلها الخارجي فوراً","بنار تنطفئ حين يغيب أحد عناصرها"],"src":"guide","why":"مشبّهاً إياه بمبنى محترق يبدو هيكله الخارجي سليماً بينما كان داخله مدمراً.","pg":17},{"q":"أي النظريات تفسر الاحتراق بفقدان المعنى في حياة الفرد؟","o":["النظرية الوجودية","النظرية السلوكية","النظرية المعرفية","نظرية التحليل النفسي"],"src":"guide","why":"تركز النظرية الوجودية في تفسيرها للاحتراق الوظيفي على عدم وجود المعنى في حياة الفرد","pg":66},{"q":"ترى النظرية المعرفية أن الاحتراق ينتج عن:","o":["إدراك الفرد للموقف إدراكاً سلبياً","سلوك غير سوي يتعلمه من بيئة غير مناسبة","كبت الرغبات غير المقبولة في الشخصية","فقدان المعنى والمغزى في حياة الفرد"],"src":"guide","why":"أما إذا كان إدراكه للموقف سلبياً فقد يؤدي إلى أعراض الاحتراق الوظيفي.","pg":66}]},{"k":"signs","t":"كيف تعرفه؟","ic":"pulse","q":"ما المؤشرات التي تنذر به، وما أعراضه، وبأي مراحل يمر؟","sections":[{"t":"المؤشرات المنذرة باحتمالية حدوث الاحتراق الوظيفي","src":"guide","pg":26,"p":["هناك عدة علامات منذرة تحذّر من الاحتراق الوظيفي، والتي يجب الانتباه إليها لتجنّب التأثير السلبي على حياتك المهنية والشخصية:","هل تشعر أن هذا يحدث معك؟ ربما يمكننا مناقشة بعض الطرق لإيجاد توازن أفضل بين العمل والترفيه.","الوعي بهذه العلامات يمكن أن يساعدك في اتخاذ خطوات وقائية للحفاظ على توازن صحي بين العمل والحياة الشخصية."],"key":"الوعي بهذه العلامات يمكن أن يساعدك في اتخاذ خطوات وقائية للحفاظ على توازن صحي بين العمل والحياة الشخصية.","items":[{"h":"الانشغال الدائم","x":"والاستعجال في إنهاء المهام اليومية يجعلك تضحي بالحاضر، ولا يمنحك الوقت للاستجابة للعلامات التحذيرية. كأن تستمر في العمل دون راحة، فتكون حاضرًا جسديًا ولكن ذهنك مشغول بالماضي أو المستقبل، مما يؤدي إلى إنجاز المهام بشكل ميكانيكي دون تواصل عاطفي، مركزًا على السرعة والكمية بدلاً من الإتقان."},{"h":"تأجيل الأمور السارة","x":"تأجيل الأنشطة الاجتماعية والترفيهية بسبب الانشغال يمكن أن يؤدي إلى نمط حياة رتيب حيث يصبح الترفيه رفاهية نادرة بالنسبة لك. ومع مرور الوقت، قد يصبح التأجيل هو القاعدة، مما يجعل من الصعب عليك الاستمتاع باللحظات البسيطة والأنشطة الممتعة."},{"h":"العيش وفق قاعدة يجب وينبغي","x":"الشعور بأنك مجبر على اتباع قواعد صارمة يمكن أن يكون مرهقًا للغاية. يصبح الشخص حسّاسًا جدًا لآراء الآخرين، وقد يجد صعوبة في إرضاء نفسه وحتى في محاولاته لإرضاء الآخرين، مما يؤدي إلى شعور بالإحباط."},{"h":"إدمان العمل","x":"الانغماس في العمل بشكل مفرط، مما قد يجعلك محبوبًا لدى أصحاب العمل، لكنه يضر بصحتك النفسية والجسدية."},{"h":"الكمالية","x":"النَزعة الكمالية تجعلك تفقد الرؤية أو المنظور، فترى كل شيء مهماً وعاجلاً، مما يؤدي إلى إنهاكك في العمل وفقدانك لروح المرح. نتيجة لذلك، تجد نفسك مترددًا في اتخاذ القرارات"}],"stats":[{"n":"20% ، 15% ، 25% ، 30% ، 10%","x":"التأثير النسبي المرسوم للمؤشرات: الانشغال الدائم، تأجيل الأمور السارة، العيش وفق قاعدة يجب وينبغي، إدمان العمل، الكمالية","src":"رسم بياني في الدليل بلا مصدر مذكور"}]},{"t":"مظاهر حدوث الاحتراق الوظيفي","src":"guide","pg":28,"p":["يمكن الاستدلال على احتمالية حدوث الاحتراق الوظيفي من خلال العلامات التي تظهر على سلوك الموظف وأدائه المهني، والتي يمكن للآخرين ملاحظتها. قد تكون هذه المظاهر أولية كإنذار، أو متقدّمة بمثابة تحذير. وعند تجاهلها، يصل الموظف إلى مرحلة الاحتراق الوظيفي وتظهر عليه الأعراض الداخلية الجسدية والنفسية التي لا يعيها الآخرون إلا إذا تحدث عنها، لكنها تؤثر على سلوكه الظاهري.","إذا لم يدرك المحيطون أن هذه الأعراض ناتجة عن الاحتراق الوظيفي، فقد لا يقدّمون الدعم اللازم، وقد يأخذون سلوكه بشكل شخصي، مما يؤدي إلى خلافات تزيد من وطأة الاحتراق عليه. لذلك، من المهم فهم الأعراض التي قد نشعر بها وكيفية التعامل معها، وكذلك ملاحظة العلامات التي تظهر على الآخرين لتقديم الدعم اللازم، خاصة إذا طرأت تغييرات غير معتادة على سلوكهم."],"key":"قد تكون هذه المظاهر أولية كإنذار، أو متقدّمة بمثابة تحذير.","items":[{"h":"علامات أولية","x":"يحرص الموظف على الاستفادة من الإجازات والعطل الأسبوعية، ويغادر إلى المنزل فور انتهاء الدوام اليومي، كما يتحدث كثيرًا عن رغبته في التقاعد، معتبرًا إياه وسيلة للهروب من ضغوط العمل."},{"h":"علامات متقدمة","x":"تبدأ أعراض القلق النفسي والجسدي بالظهور، مما يؤثر سلبًا على الصحة الجسمية. كما يعاني الموظف من الإرهاق العقلي، مما ينعكس سلبًا على سلوكه المهني ويقلّل من حماسه واندفاعه في أداء مهامه. تظهر أيضًا بوادر حدّة الطبع وتغيّر السلوك، ويصبح الموظف غير راغب في التعامل مع الآخرين، محاولاً بجدية إنهاء علاقاته، خاصة علاقات العمل، ويفضل عدم الظهور أمام الناس. يلاحظ على الموظف التذمّر المستمر من العمل، وفقدان الرغبة في الأداء والإنجاز، والانطواء على الذات، وعدم الرغبة في التعامل مع المراجعين أو مدخلات العمل الأخرى، والعزلة عن الآخرين في مختلف مجالات الحياة."}]},{"t":"أعراض الاحتراق الوظيفي","src":"guide","pg":30,"p":["الاحتراق الوظيفي هو حالة يمكن التعامل معها والتخلّص من أعراضها إذا تمّ التدخل في الوقت المناسب. على الرغم من أنه ليس اضطرابًا نفسيًا بحد ذاته، إلا أن الأعراض قد تتطور وتتحول إلى اضطرابات نفسية أو أمراض عضوية خطيرة أو مزمنة إذا لم يتم التعامل معها بشكل مناسب. لذا، يرسل الجسم إشارات وإنذارات من الضروري الاستجابة لها مبكرًا لتجنّب الوصول إلى مرحلة أكثر خطورة. البيئة المحيطة تلعب دورًا كبيرًا في الدعم أو زيادة الاحتراق. إذا لم يتم التعامل مع هذه الأعراض بشكل مناسب، فإنها ستزداد سوءًا حتى تصل إلى مرحلة الاحتراق الكامل."],"key":"على الرغم من أنه ليس اضطرابًا نفسيًا بحد ذاته، إلا أن الأعراض قد تتطور وتتحول إلى اضطرابات نفسية أو أمراض عضوية خطيرة أو مزمنة إذا لم يتم التعامل معها بشكل مناسب.","items":[{"h":"أعراض جسدية","x":"قلّة النوم المصحوبة بإرهاق مستمر، بالإضافة إلى مشاكل في الظهر والرقبة، كما يمكن أن يعاني الشخص من فقدان الشهية والشعور المستمر بالإنهاك والتعب، وأيضًا قد تظهر أعراض جسدية أخرى مثل آلام المفاصل، مشاكل في الجهاز الهضمي، الشد العضلي، وشد الأسنان. إذا لم يتم التعامل مع هذه الأعراض بشكل مناسب، يمكن أن تتطور لتشمل آلام الصدر، والقولون العصبي، وآلام المعدة، والأكتاف، والأرجل، وطنين الأذن، وتغيرات في الشهية، وارتفاع ضغط الدم، وحتى النوبات القلبية، بالإضافة إلى ذلك، قد يشعر الشخص بالتعب أغلب الوقت، والصداع المتكرر، وفقدان الشهية، وتغيرات في الوزن سواء فقدان أو زيادة، وضعف الجهاز المناعي مما يزيد من التعرّض للأمراض والعدوى.","grp":"جسدية"},{"h":"أعراض نفسية","x":"الشعور بالإنهاك النفسي الشديد وفقدان الطاقة، وانخفاض مستوى تقدير الذات وفقدان الثقة بالآخرين. يمكن أن يصل الضغط النفسي إلى حد عدم الاكتراث بالعمل، مما يؤدي إلى الإرهاق العاطفي وتبلّد الشخصية والشعور الدائم بالضغط. بالإضافة إلى الشعور باليأس والعجز والفشل والتشاؤم والسلبية تجاه العمل والحياة، والشعور بالغربة في مكان العمل، مما يفقد الشخص الدافعية والشغف. تشمل هذه الأعراض أيضًا مشاعر سلبية مثل الإحباط والشعور بالفشل وعدم الكفاءة، والإحساس باللوم والذنب وتأنيب الضمير. يمكن أن يؤدي الاحتراق الوظيفي إلى الإجهاد الانفعالي وفقدان الابتكار والروح الإبداعية، بالإضافة إلى تقلّبات مزاجية مثل الغضب والحزن، وزيادة مستوى القلق والاكتئاب. كما يجد الشخص صعوبة في الإدراك، وضعف التركيز، وصعوبة في التذكر.","grp":"نفسية"},{"h":"أعراض سلوكية","x":"قلة الإنتاجية، حيث يشهد الفرد انخفاضًا واضحًا في مستوى الأداء في العمل. قد يميل الشخص إلى تأجيل المسؤوليات أو تأخير الأعمال الهامة، ويدخل في مشاجرات أو نزاعات غير ضرورية في مكان العمل أو المنزل. بالإضافة إلى ذلك، يظهر الفرد تغييرات في عادات النوم مثل السهر لوقت متأخر أو النوم لساعات غير كافية. قد يميل إلى إهمال النظافة الشخصية أو ارتداء ملابس غير مرتبة. يلاحظ أيضًا زيادة الاعتماد على المواد الضارة مثل الكافيين أو التدخين، أو حتى تناول الكحول. يصبح أكثر عرضة للسلوك العدواني والانفعالات السريعة حتى في المواقف البسيطة. يشمل الاحتراق الوظيفي الانسحاب من المسؤوليات والاجتماعيات، والعزلة عن الآخرين بشكل ملحوظ، مع تزايد الغيابات المتكررة من العمل أو التأخر المستمر في الحضور. يمكن أن يظهر الاهتمام المبالغ بالتفاصيل الصغيرة، مما يعوق قدرة الفرد على رؤية الصورة الكبيرة وأداء المهام بشكل فعال. وأخيرًا، قد يفقد الاهتمام بالأنشطة والهوايات التي كانت تمنحه المتعة في السابق.","grp":"سلوكية"}]},{"t":"ضغط العمل أم احتراق؟","src":"guide","pg":31,"p":["يتسبب الاحتراق الوظيفي بالإرهاق الشديد واستنزاف الموارد الجسدية والعقلية والعاطفية. يحدث ذلك على مستوى فردي، حيث يفقد الموظف الشغف والرغبة في العمل، مما يؤثر سلبًا على نفسيته ومشاعره ودوافعه، وبالتالي تنخفض إنتاجيته. كما يؤدي الخوف من عدم أداء العمل بفعالية إلى الإحباط والشعور بالعجز، سواء من حيث مدة العمل أو نوعية الوقت الذي يقضيه فيه. نتيجة للضغوط المستمرة وغير المدارة، يمكن التفريق بين الإرهاق الناتج عن ضغط العمل والإرهاق الناتج عن الاحتراق الوظيفي من خلال فهم الفروقات الرئيسية في الأعراض والعلامات.","إدارة الضغوط بشكل صحيح تساهم في تجنّب الوقوع في الاحتراق الوظيفي. يمر الموظف بثلاث مراحل من الضغط تختلف حسب طبيعة العمل، وقد تكون بسيطة أو متقدمة أو موسمية، مثل قبل انتهاء مشروع أو عند التحضير له. إذا استمرت الضغوط، يشعر الموظف بالغربة في مكان العمل وتصبح اللامبالاة حتمية، مما يؤدي في النهاية إلى الاحتراق الوظيفي. كما أن الضغط المنعدم أو المنخفض يجعل الموظف يحافظ على مستويات أدائه الحالية عامة، مما يؤدي إلى انعدام النشاط أو الدافعية لأداء أفضل."],"key":"أعراض الإرهاق الناتجة عن ضغط العمل تكون مؤقتة.","items":[{"h":"أعراض الإرهاق الناتجة عن ضغط العمل","x":"أعراض الإرهاق الناتجة عن ضغط العمل تكون مؤقتة. عندما تخف الضغوط، يبدأ التعب في التلاشي تدريجيًا بمجرد انتهاء الأعمال المسببة للضغط. الأشخاص الذين يعانون من ضغط العمل يشعرون بتحسّن إذا تمكّنوا من السيطرة على مسببات الضغوط، مما يدل على اهتمامهم الكبير بالعمل الذي يقومون به. يمكن التعامل مع ضغط العمل من خلال الراحة والاسترخاء، حيث تكون الأعراض أقل شدة ولا تؤدي إلى تأثيرات طويلة الأمد على الصحة النفسية والجسدية، بالإضافة إلى ذلك، يكون الشخص واعيًا ومدركًا أنه تحت ضغط.","grp":"ضغط العمل مقابل الاحتراق"},{"h":"أعراض الإرهاق الناتجة عن الاحتراق الوظيفي","x":"أعراض الإرهاق الناتجة عن الاحتراق الوظيفي تشمل الإرهاق العاطفي المستمر والشعور بالتشاؤم والاكتئاب. يبقى الشخص في حالة من الفراغ ويفقد الدافعية والأمل في التغيير الإيجابي، كما يعاني من التباعد الشخصي وانخفاض الإنجاز الشخصي، ويشعر بالفراغ وعدم الرغبة في بذل أي مجهود، لا يرى أملاً في تحسن الوضع ولا يكترث لعمله. هذه الأعراض تكون مزمنة وتؤثر بشكل كبير على الأداء الوظيفي والحياة الشخصية، وغالبًا ما يكون الشخص غير واعٍ لحقيقة ما يمر به، مما يجعله في حالة إنكار.","grp":"ضغط العمل مقابل الاحتراق"},{"h":"مرحلة الإنذار","x":"تظهر أعراض بسيطة تشير إلى أن الموظف يعاني من ضغوط غير صحية، رغم أن قدراته تفوق هذه الضغوط. في هذه المرحلة، يبدأ الجسم في التكيّف مع الضغوط من خلال إفراز هرمون الأدرينالين، مما يزيد من يقظة الجسم. تشمل الأعراض زيادة معدل ضربات القلب، وسرعة التنفس، وشد العضلات.","grp":"مراحل الضغط الثلاث"},{"h":"مرحلة المقاومة","x":"يتعامل الموظف مع الضغوط بمستوى قدراته، حيث يتغلّب على الضغوط أحياناً وتغلبه أحياناً أخرى. العامل الحاسم هنا هو مدة الفترة التي يمكن للفرد أن يعمل فيها تحت هذه الظروف الضاغطة. إذا استمرت مواجهة الجسم للضغوط، تختفي التغيرات الجسمية التي ظهرت في المرحلة الأولى ويعود الشخص إلى حالته الطبيعية. لكن مع استمرار الضغوط، يبدأ الشخص بالشعور بالتعب والتوتر وعدم القدرة على تحمل الضغوط.","grp":"مراحل الضغط الثلاث"},{"h":"مرحلة الإجهاد","x":"تكون الضغوط أعلى من قدرات الشخص، مما يتطلّب مقاومة شديدة. نتيجة لارتفاع مستويات الضغط، يمكن أن ينخفض الأداء بشكل ملحوظ، حيث يكرّس الشخص جهده لتخفيف الضغط بدلاً من التركيز على الأداء. إذا استمرت الضغوط لفترة طويلة، فإن طاقة التكيّف تستنزف، مما يؤدي إلى عودة التغيرات الجسمية التي ظهرت في المرحلة الأولى بشكل أشد. قد يؤدي ذلك إلى أمراض نفسية أو جسدية، ويزيد من صعوبة اتخاذ القرارات والتفاعل مع الآخرين.","grp":"مراحل الضغط الثلاث"},{"h":"تنبيه","x":"إذا استمر الضغط لأمد طويل على مستوى عالٍ، على الموظف ضرورة إجراء تغيير ما قبل أن يصيبه الانهيار. قد تظهر في هذه المرحلة أنماط سلوكية مثل الانسحاب والغضب والتخريب وإدمان المسكرات وأنماط سلوكية أخرى بداية الاحتراق الوظيفي.","grp":"مراحل الضغط الثلاث"}],"table":{"head":["","الإرهاق الناتج عن ضغط العمل","الإرهاق الناتج عن الاحتراق الوظيفي"],"rows":[["المدة","تكون مؤقتة","تكون مزمنة"],["عند زوال الضغط","يبدأ التعب في التلاشي تدريجيًا","لا يرى أملاً في تحسن الوضع"],["الوعي","يكون الشخص واعيًا ومدركًا أنه تحت ضغط","غالبًا ما يكون الشخص غير واعٍ لحقيقة ما يمر به، مما يجعله في حالة إنكار"],["العلاقة بالعمل","مما يدل على اهتمامهم الكبير بالعمل الذي يقومون به","لا يكترث لعمله"]]}},{"t":"مراحل تطور الاحتراق الوظيفي","src":"guide","pg":34,"p":["يمكن التعرّف على الاحتراق الوظيفي من خلال ثلاث سمات رئيسية: الإرهاق، والتشاؤم، والشك في القدرة على الإنجاز. هذه السمات تتطور تدريجيًا وتظهر على خمس مراحل، في البداية، يبدي الموظف حماسًا ونشاطًا، لكن مع زيادة الضغوط يبدأ الشغف بالتراجع، ثم يبدأ الشخص بنسيان أمور مهمة في حياته الشخصية، ويهمل واجباته الاجتماعية. مع مرور الوقت، يصبح التوتر مزمنًا، وتظهر أعراض جسدية ونفسية، وإذا لم يتم التعامل مع هذه الأعراض مبكرًا، يصل الشخص إلى مرحلة التبلّد، حيث يصبح الإرهاق جزءًا من شخصيته ويفقد القدرة على إدارة حياته بشكل مناسب، وكلما تم اكتشاف الاحتراق الوظيفي مبكرًا، كان التعامل معه أسهل وأيسر.","دراسة موقف: يونس كان طبيبًا شابًا مليئًا بالحماس والطموح، دخل مهنة الطب برغبة قوية في شفاء المرضى وتحقيق إنجازات كبيرة، كان يعمل بجد ويشعر بالرضا عن كل حالة ينجح في علاجها، كما أنه يعتقد أن مهنته ستشبع جميع احتياجاته الأساسية وستكون مصدرًا دائمًا للسعادة والرضا.","لكن مع مرور الوقت، بدأت الأمور تتغير، وبدأ يونس يلاحظ أن الواقع مختلف تمامًا عن توقعاته، إذ لم يكن يحصل على التقدير الذي يستحقه، وكانت المهام الإضافية تتراكم عليه بشكل مستمر، وبدأ بالشعور بأن جهوده لا تُقدر وأنه مجرّد أداة في نظام صحي ضاغط، فتراجع حماسه تدريجيًا ودخل في مرحلة الجمود، حيث لم يعد يشعر بنفس الشغف الذي كان يشعر به في البداية.","مع مرور الأيام، بدأت طاقة يونس تنخفض تدريجيًا، وأصبح يجد صعوبة في تذكر مواعيده الطبية وبدأ يهمل واجباته الاجتماعية والأسرية، كان يشعر بالتوتر المستمر وأصبح عصبيًا وسريع الغضب حتى لأسباب تافهة، وبدأ ينسحب من بعض العلاقات الاجتماعية لصالح عمله وضغوطه، وشعر بالاستياء من كل شيء حوله.","استمر التوتر في السيطرة على حياته، وبدأت تظهر على يونس أعراض جسدية ونفسية، حيث كان يعاني من صداع مستمر ومشاكل هضمية، وشعر بالاكتئاب وانعدام الثقة بالنفس، وكان يشك في قدراته ولم يعد يشعر بالرضا عن عمله، حاول معالجة التوتر بالإفراط في شرب القهوة والتدخين، لكن ذلك لم يكن كافيًا.","وصل يونس إلى مرحلة من التبلّد، حيث أصبح الإرهاق جزءًا من شخصيته، ولم يعد قادرًا على إدارة حياته بشكل مناسب، وكان تركيزه ضعيفًا وعلاقاته الاجتماعية هشة، كما كان يشعر بأن طاقته منتهية وأنه عاجز عن تحقيق أي إنجاز، فبدأ ينسحب تدريجيًا من مهنته ويشعر بالإحباط الشديد.","تدهور وضع الدكتور يونس بشكل كبير، وازدادت الأعراض البدنية والنفسية عليه، حيث كان يعاني من ارتفاع ضغط الدم وطنين في الأذن وصعوبة في التركيز. أصبح ينسحب ويسبب مشاكل مع من حوله، وضعف أداؤه بشكل ملحوظ، وتجاهل المرضى وبدأ يتسبب في مشاكل مع زملائه. كان يستهلك مشروبات كافيين عالية ويدخن بكثرة كوسيلة للتفريغ، مما قاده إلى الاكتئاب.","بدأ الدكتور يونس مسيرته المهنية بحماس كبير، لكنه واجه عدة مراحل من الاحتراق الوظيفي. هل يمكنك تحديد هذه المراحل ومعرفة ما إذا كنت تمر بأي منها؟ وما هي الأسباب التي تعتقد أنها قد تكون وراء ذلك؟"],"key":"وكلما تم اكتشاف الاحتراق الوظيفي مبكرًا، كان التعامل معه أسهل وأيسر.","items":[{"h":"مرحلة الحماس","x":"تظهر أعراض بسيطة تشير إلى أن الموظف يعاني من ضغوط غير صحية، رغم أن قدراته تفوق هذه الضغوط. في هذه المرحلة، يبدأ الجسم في التكيّف مع الضغوط من خلال إفراز هرمون الأدرينالين، مما يزيد من يقظة الجسم. تشمل الأعراض زيادة معدل ضربات القلب، وسرعة التنفس، وشد العضلات.","grp":"المرحلة 1"},{"h":"مرحلة الركود","x":"يشعر الموظف بأن احتياجاته المهنية والشخصية لم تُشبع، ويلاحظ أن النظام لا يعمل كما كان يعتقد، في هذه المرحلة، تبدأ الحوافز الداخلية بالتلاشي تدريجيًا، ومع عدم وجود حياة خارج العمل لتعزيز الإيجابية، يستجيب للسلبية بالإجهاد والتوتر. يصبح سريع الغضب وغير راضٍ عن وظيفته، مما يؤدي إلى انخفاض إنتاجيته ومعاناته من بعض الأعراض الجسدية التي تشير إلى المرحلة الثانية من الاحتراق الوظيفي. قد لا يدرك الموظف هذه الأعراض ويمر بها دون معرفة كيفية التعامل معها، مما يؤدي إلى التعب والإرهاق الدائم، وتحول التحفيز إلى توتر، وتأجيل المهام في العمل والحياة الشخصية، ويتأخر في الذهاب إلى العمل، ويصبح سلوكه عدوانيًا ومنعزلاً ومتشائمًا، ويشرب الكثير من القهوة، ويشعر بالخوف وعدم الراحة.","grp":"المرحلة 2"},{"h":"مرحلة الإحباط","x":"يبدأ الموظف بالتساؤل عن أهميته وفعاليته ودوره، وتظهر عليه أعراض التوتر والقلق والشعور المستمر بالإجهاد الجسدي. بعد ذلك، يدخل في المرحلة الثالثة من الاحتراق الوظيفي، حيث يعاني من الإرهاق المستمر، ويشعر بالإحباط وفقدان الأمل، وقد تتطور الأعراض إلى مشاكل صحية جسدية ونفسية، ويصبح من الصعب عليه أداء مهامه اليومية، ويزداد شعوره بالعزلة والتشاؤم. إذا استمر الفرد في هذا الوضع دون معالجة، فسوف يصل إلى المرحلة الرابعة، حيث تتفاقم الأعراض وتصبح أكثر حدّة.","grp":"المرحلة 3"},{"h":"مرحلة البلادة","x":"في هذه المرحلة، يتم استنفاد كل الموارد الانفعالية لدى الموظف، حيث لم يعد قادرًا على مواجهة المتطلّبات الانفعالية لعمله، ويستجيب لحالة نضب الموارد هذه باللامبالاة التامة، وتتدنى أهدافه ورؤيته المثالية بشكل كبير، ويبدأ في تبني مواقف سلبية تجاه المنظومة بأكملها، بما في ذلك المستفيدين من الخدمة التي يقدّمها، ويحوّلهم إلى أشياء غير إنسانية، مما يجعل التعامل معهم أسهل بكثير ويبرّر له عدم احترامه أو إهماله. يشعر الموظف بالإنهاك الانفعالي التام، ويصبح الذهاب للعمل صعبًا ولا يستطيع الاستمرار فيه، ويحتاج إلى مساعدة لأنه يرى أن وظيفته سيئة وحياته أسوأ، ويرغب بالهروب من كل شيء، لكنه لا يعرف إلى أين يذهب، يشعر بفراغ كبير ويفكر في مشاكله باستمرار، ويتمنى أن يختفي عن العالم، كما قد يعاني من مشاكل في المعدة والجهاز الهضمي، وعندها يكون قد وصل إلى المرحلة الأخيرة من الاحتراق الوظيفي، وبعدها قد يصل إلى مرحلة الانهيار التام.","grp":"المرحلة 4"},{"h":"مرحلة الانهيار التام","x":"في هذه المرحلة، يؤثر الاحتراق المزمن سلبًا على جميع جوانب حياة الفرد، حيث تسيطر عليه المشاعر السلبية تجاه نفسه وعمله والآخرين، ويصبح سريع الاستثارة والغضب، مما يؤدي إلى استجابات سلوكية عدوانية وتدهور علاقاته المهنية والأسرية والاجتماعية، ويشعر بالتعب والإرهاق بشكل دائم، ويعاني من مشاكل صحية ونفسية، ويفقد ارتباطه بذاته. كل هذه الأعراض تجعله يشعر بالضياع والضيق من الحياة والناس، مما يزيد من صعوبة التعامل مع الوضع.","grp":"المرحلة 5"}]}],"ev":[{"sid":"gaza2010","x":"هذا و تشير باربرا براهام بأن هناك أربعة مؤشرات أولية ينبغي أن تؤخذ بعين الاعتبار كنوع من التحذير بأن الفرد في طريقه إلى الاحتراق الوظيفي: 1، 2، 3، 4","th":1},{"sid":"syria","x":"كذلك أشارت دراسة (Arvidsso et al., 2019) إلى أن هناك أربعة مؤشرات أولية ينبغي أن تؤخذ بعين الاعتبار كنوع من التحذير بأن الفرد في طريقه إلى الاحتراق وهي: الانشغال الدائم، تأجيل الأمور السارة، قاعدة يجب وينبغي، فقدان الرؤية","th":1},{"sid":"jeddah","x":"يمر الاحتراق الوظيفي كما صنفه العديد من الباحثون والدارسون النفسيون بأربعة مراحل: التنبيه، المقاومة، المواجهة، الإنهاك","th":1}],"sort":{"t":"ضغط العمل أم احتراق؟","s":"صنّف كل عبارة كما يقابل الدليل بين الحالتين.","bins":["الإرهاق الناتج عن ضغط العمل","الإرهاق الناتج عن الاحتراق الوظيفي"],"items":[["تكون مؤقتة",0],["تكون مزمنة",1],["يبدأ التعب في التلاشي تدريجياً عند زوال الضغط",0],["لا يرى أملاً في تحسن الوضع",1],["يكون الشخص واعياً ومدركاً أنه تحت ضغط",0],["غالباً لا يعي حقيقة ما يمر به، فيكون في حالة إنكار",1]]},"match":{"t":"مراحل الضغط الثلاث","s":"صل كل مرحلة بوصفها كما في الدليل.","l":"المرحلة","r":"وصفها","pairs":[["مرحلة الإنذار","أعراض بسيطة رغم أن قدرات الموظف تفوق الضغوط"],["مرحلة المقاومة","يتعامل الموظف مع الضغوط بمستوى قدراته"],["مرحلة الإجهاد","الضغوط أعلى من قدرات الشخص"]]},"quiz":[{"q":"أي مما يلي من المؤشرات المنذرة بالاحتراق في الدليل؟","o":["تأجيل الأمور السارة بسبب الانشغال","التركيز على الإتقان بدل السرعة والكمية","أخذ استراحات قصيرة منتظمة خلال اليوم","مناقشة الصعوبات مع الزملاء في العمل"],"src":"guide","why":"تأجيل الأنشطة الاجتماعية والترفيهية بسبب الانشغال يمكن أن يؤدي إلى نمط حياة رتيب","pg":26},{"q":"كيف تجعل «الكمالية» الشخص أقرب إلى الاحتراق؟","o":["تُفقده المنظور فيرى كل شيء مهماً وعاجلاً","تجعله حساساً لآراء الآخرين فيصعب إرضاؤه","تجعله يؤجل الأنشطة الاجتماعية والترفيهية دائماً","تدفعه للعمل بسرعة وكمية على حساب الإتقان"],"src":"guide","why":"النَزعة الكمالية تجعلك تفقد الرؤية أو المنظور، فترى كل شيء مهماً وعاجلاً","pg":26},{"q":"ما الذي يميز الإرهاق الناتج عن الاحتراق عن الإرهاق الناتج عن ضغط العمل؟","o":["أنه مزمن، ولا يرى صاحبه أملاً في التحسن","أنه مؤقت ويتلاشى بزوال مسببات الضغط","أن صاحبه يكون واعياً ومدركاً أنه تحت ضغط","أنه يدل على اهتمام صاحبه الكبير بعمله"],"src":"guide","why":"لا يرى أملاً في تحسن الوضع ولا يكترث لعمله. هذه الأعراض تكون مزمنة","pg":31},{"q":"ما المرحلة الأخيرة من مراحل تطور الاحتراق الخمس في الدليل؟","o":["مرحلة الانهيار التام","مرحلة الإحباط المزمن","مرحلة الركود وتراجع الحماس","مرحلة الإجهاد الشديد"],"src":"guide","why":"وعندها يكون قد وصل إلى المرحلة الأخيرة من الاحتراق الوظيفي، وبعدها قد يصل إلى مرحلة الانهيار التام.","pg":34},{"q":"لماذا يؤكد الدليل على الاكتشاف المبكر للاحتراق؟","o":["لأن اكتشافه مبكراً يجعل التعامل معه أيسر","لأن أعراضه لا تظهر إلا في مراحله الأولى","لأنه بعد مرحلة الركود لا يمكن التعافي منه","لأن الموظف بعدها لا يكون مسؤولاً عن تعافيه"],"src":"guide","why":"وكلما تم اكتشاف الاحتراق الوظيفي مبكرًا، كان التعامل معه أسهل وأيسر.","pg":34},{"q":"أي مما يلي من الأعراض السلوكية للاحتراق في الدليل؟","o":["تأجيل المسؤوليات أو تأخير الأعمال الهامة","ضعف التركيز وصعوبة التذكر وبطء الإدراك","طنين الأذن والصداع المتكرر وآلام المفاصل","انخفاض تقدير الذات وفقدان الثقة بالآخرين والتشاؤم"],"src":"guide","why":"قد يميل الشخص إلى تأجيل المسؤوليات أو تأخير الأعمال الهامة","pg":30}]},{"k":"who","t":"من الأكثر عرضة؟ وما آثاره؟","ic":"users","q":"هل يصيب الجميع؟ وماذا يفعل بالفرد والمنظمة؟","sections":[{"t":"الفئات الأكثر عرضة للاحتراق الوظيفي","src":"guide","pg":40,"p":["تُعدُّ مشكلة الاحتراق الوظيفي شائعة في مختلف المجالات المهنية، وتتطلّب تعاملاً فعّالاً للحد من تأثيراتها السلبية. جميع العاملين معرّضون للاحتراق الوظيفي بنسب متفاوتة بناءً على شخصية الفرد وظروف العمل. لا يشترط أن تكون طبيعة الوظيفة شاقة بدنيًا أو مرهقة ذهنيًا؛ فالأمهات، على سبيل المثال، قد يشعرن بالاحتراق أثناء تربية أطفالهن، وكذلك الطلبة أثناء دراستهم وغيرهم. هناك تفاوت كبير حتى في الجنس؛ فالضغوطات التي تواجهها السيدات تختلف عن تلك التي يواجهها الرجال، ولا يعني ذلك أن الرجال أقوى أو النساء أضعف، بل طبيعة الضغط تختلف بين الجنسين في نفس المكان. أيضًا، يلعب العمر دورًا؛ فالشخص في مقتبل حياته المهنية يواجه ضغوطات تختلف عن الشخص في نهاية مسيرته المهنية أو على وشك التقاعد.","ومن الفئات الأكثر عرضة للاحتراق الوظيفي:"],"key":"جميع العاملين معرّضون للاحتراق الوظيفي بنسب متفاوتة بناءً على شخصية الفرد وظروف العمل.","items":[{"h":"الأشخاص في المهن التي تتطلّب مجهودًا فكريًا وعقليًا كبيرًا، مثل الطلاب والموظفين والأطباء، يتعرضون للإجهاد بسبب التفكير المستمر وحل المشكلات المعقدة."},{"h":"الأطباء والمدراء والقادة يواجهون تحديات وضغوطًا مستمرة تجعل السيطرة على المسؤوليات وضبط الروتين الحياتي أكثر صعوبة."},{"h":"العاملون في مهن عالية الخطورة، مثل المسعفين والجنود، يواجهون مخاطر وضغوط نفسية تزيد من احتمالية الاحتراق الوظيفي."},{"h":"العاملون في مهن الرعاية والدعم، مثل الإغاثة والتمريض، يواجهون إرهاقًا نفسيًا وجسديًا بسبب طبيعة العمل المستمرة والمكثفة."},{"h":"العاملون لساعات طويلة، مثل الأطباء والممرضين ورجال الإطفاء، يواجهون ضغطًا نفسيًا وعصبيًا كبيرًا بسبب قلة النوم."},{"h":"مدمنو العمل الذين يسعون للكمال يضعون معايير عالية لأنفسهم، مما يدفعهم للعمل لساعات طويلة ويفتقرون إلى التوازن بين العمل والحياة الشخصية."},{"h":"الأشخاص الذين يحتاجون إلى الرعاية والدعم المالي، مثل كبار السن وذوي الإعاقة والأسر ذات الدخل المنخفض، يواجهون تحديات إضافية."},{"h":"العاملون الذين يتبنون سلوكيات مرهقة، مثل تحمّل مسؤوليات ليست من مهامهم لتخفيف الضغط عن الآخرين، يصلون إلى مرحلة الإجهاد."},{"h":"المشاهير والفنانون والسياسيون قد يشعرون بالتجرّد من الشخصية بسبب ضغط الشهرة."},{"h":"الأشخاص الذين يعانون من تراكم الإجهاد والإحباط بسبب القهر واللوم المستمر يزداد لديهم الشعور بالإحباط والضغط النفسي."},{"h":"العاملون في القطاعات الخدمية، مثل المعلمين، يواجهون ضغوطًا نفسية كبيرة نتيجة لتفاعلهم المستمر مع الجمهور ومتطلبات العمل العالية."},{"h":"العاملون الذين يواجهون صعوبات يومية في الوصول إلى مكان العمل بسبب الازدحام المروري يواجهون ضغوطًا إضافية تؤثر على راحتهم النفسية والجسدية."},{"h":"العاملون في بيئات عمل ملوثة، مثل التعرّض المستمر للإشعاعات كالأشعة السينية والأشعة فوق البنفسجية، والتلوث البيئي والتعرّض للملوثات الكيميائية، يعانون من الإجهاد التأكسدي الذي يمكن أن يسبب تلفًا للخلايا والأنسجة، مما يشكّل ضغطًا نفسيًا وجسديًا عليهم."}]},{"t":"آثار الاحتراق الوظيفي","src":"guide","pg":41,"p":["الضغوط في بيئة العمل قد تكون دافعًا للإنجاز، ولكن استمرارها بشدة وعدم إدارتها بفعالية يمكن أن يؤدي إلى آثار سلبية عميقة على الموظفين والمنظمات، حيث تؤثر هذه الضغوط على الموظف من الناحية السلوكية، والنفسية، والجسدية، مما يؤدي إلى تدهور الأداء الوظيفي والإنتاجية، وأيضًا تؤثر سلبًا على العلاقات الاجتماعية والصحة العامة. في البداية، قد يتمكّن الموظفون من الحفاظ على مستويات أدائهم، وربما يشهدون تحسّنًا مؤقتًا مع زيادة الضغط. ولكن، إذا استمر الضغط ووصل إلى مرحلة الاحتراق الوظيفي، فإن الأداء ينخفض بشكل ملحوظ حيث يركّز الأفراد على تخفيف الضغط بدلاً من العمل بفعالية. هذه التأثيرات السلبية تظهر بوضوح على كل من الفرد والمنظمة، مما يجعل من الضروري تبني استراتيجيات فعّالة لإدارة الضغوط المهنية في بيئة العمل لتجنّب الاحتراق الوظيفي والتغلّب عليه."],"key":"إذا استمر الضغط ووصل إلى مرحلة الاحتراق الوظيفي، فإن الأداء ينخفض بشكل ملحوظ حيث يركّز الأفراد على تخفيف الضغط بدلاً من العمل بفعالية.","items":[{"h":"سلوكياً","x":"العدوانية، واللامبالاة، والسلوك المنفر، والانسحاب، والغضب، والتخريب، والهروب من العمل، والمماطلة، والإهمال.","grp":"تأثير الاحتراق الوظيفي على الفرد"},{"h":"نفسياً","x":"القلق، والاكتئاب، والإرهاق، والتوتر العصبي، والإحباط، واضطرابات الصحة النفسية مثل القلق والاكتئاب، وانخفاض تقدير الذات، والسلبية تجاه الذات، وتدني تقدير الذات، والشعور بعدم القدرة على العمل، وفقدان الدافع واللامبالاة، والشعور بالانزعاج والإرهاق.","grp":"تأثير الاحتراق الوظيفي على الفرد"},{"h":"جسدياً","x":"العرق، وجفاف الفم، ورعشات البرد، والحمى، وارتفاع نسبة الجلوكوز في الدم، وسرعة ضربات القلب، وارتفاع ضغط الدم، وأمراض شرايين القلب، ومشاكل صحية مثل الأرق والصداع المستمر، وأعراض جسمية سلبية، والتعب الشديد والإرهاق الجسدي والعاطفي، والمرض العقلي والجسدي.","grp":"تأثير الاحتراق الوظيفي على الفرد"},{"h":"أسرياً","x":"تأثيرات على العلاقات الأسرية والاجتماعية، والصراع الأسري، وتوترات عاطفية مع شريك الحياة، وعدم وجود توازن بين العمل والحياة الشخصية.","grp":"تأثير الاحتراق الوظيفي على الفرد"},{"h":"اجتماعياً","x":"تشمل التأثيرات الاجتماعية تدهور العلاقات الشخصية والاجتماعية، وتكوين اتجاهات سلبية تجاه الآخرين، والتجاهل، والغضب والحساسية، وتدهور الإدراكات الإيجابية المتعلقة بالعمل.","grp":"تأثير الاحتراق الوظيفي على الفرد"},{"h":"على الارتباط الوظيفي","x":"تشمل التأثيرات على الارتباط الوظيفي انخفاض الروح المعنوية، ونقص الولاء والارتباط الوظيفي، وعدم الشعور بالرضا الوظيفي، وزيادة معدل دوران الموظفين.","grp":"تأثير الاحتراق الوظيفي على المنظمة"},{"h":"على الأداء الوظيفي","x":"تشمل التأثيرات على الأداء الوظيفي الأخطاء في اتخاذ القرارات المهنية سواء كانت مقصودة أو غير مقصودة، وتدني مستوى جودة الأداء الوظيفي كماً ونوعاً، وتدهور أداء الموظفين المتبقين.","grp":"تأثير الاحتراق الوظيفي على المنظمة"},{"h":"على إنتاجية الموظف","x":"تشمل التأثيرات على الإنتاجية انخفاض الإنتاجية، وزيادة في معدل الغياب، وزيادة في طلبات الإجازات المرضية.","grp":"تأثير الاحتراق الوظيفي على المنظمة"},{"h":"على العلاقات المهنية","x":"تشمل التأثيرات على العلاقات المهنية ضعف الاتصال والعلاقات الإنسانية، وتدني الثقة وعدم الاحترام والتقدير، والعداوة والحقد، وزيادة الشكاوى على الموظف من زملائه والمراجعين.","grp":"تأثير الاحتراق الوظيفي على المنظمة"}]}],"ev":[{"sid":"gaza2010","x":"جنس الموظف (ذكر / أنثى) لا يؤثر على مستوى الاحتراق الوظيفي بأبعاده الثلاثة و ذلك يرجع لمساواة الموظفين من الجنسين في العبء الوظيفي و تكافؤ فرص الجنسين في الحصول على الوظائف بالإضافة لمشاركة المرأة في تحمل الأعباء الحياتية شانها شأن الرجل."},{"sid":"gaza2010","x":"هناك فروق ذات دلالة إحصائية في مستوى الاحتراق بأبعاده الثلاثة تعزى لمتغير الحالة الاجتماعية حيث أظهرت النتائج أن فئة المتزوجين كانت الأقل معاناة من الاحتراق على أبعاده الثلاثة من الفئات الأخرى و ذلك يعود لكون هذه الفئة أكثر استقرارا من الناحية النفسية و العاطفية من غيرهم فالحالة الاجتماعية تضيف عبئا على الموظف و تزيد من شعوره بالإحباط و عدم الاستقرار."},{"sid":"gaza2010","x":"هناك فروق ذات دلالة إحصائية في مستوى الاحتراق على بعد الانجاز الشخصي تعزى لمتغير العمر، حيث وجدت الدراسة أن من هم أكبر من 50 سنة أقل معاناة من غيرهم من الفئات العمرية الأخرى على بعد الانجاز الشخصي و يرجع ذلك لكون هذه الفئة أكثر فهما لأعمالهم بحكم خبرتهم فهم أكثر تمرسا لأعمالهم من غيرهم فيكون تقديرهم لأدائهم ايجابي بعكس الجدد الذين يكون مستوى طموحاتهم عال في بداية عملهم و يصطدموا بواقع العمل الذي لا يشبع طموحاتهم مما يؤثر على نفسياتهم."},{"sid":"jeddah","x":"عدم وجود فروق ذات دلالة إحصائية بين متوسطات درجات أفراد العينة على مقياس الاحتراق الوظيفي تبعاً للأداء الوظيفي، حيث بلغت قيمة ف 0.692 وهذه القيمة غير دالة عند مستوى دلالة = 0.05."},{"sid":"jeddah","x":"وجود علاقة دالة احصائيا بين الإجهاد الانفعالي والأداء الوظيفي، حيث بلغ معامل ارتباط بيرسون (0.251)، وهي قيمة دالة إحصائياً عند مستوي دلالة (0.001). وجود علاقة دالة احصائيا بين عدم الإنسانية والأداء الوظيفي، حيث بلغ معامل ارتباط بيرسون (0.353)، وهي قيمة دالة إحصائياً عند مستوي دلالة (0.001)."},{"sid":"jeddah","x":"الانحدار الخطي بين: الإجهاد الانفعالي والأداء الوظيفي، حيث أن معاملات الانحدار لديهم ليست ذات دلالة معنوية عند مستوى دلالة 0.05؛ عدم الإنسانية والأداء الوظيفي، حيث أن معاملات الانحدار لديهم ذات دلالة معنوية؛ الإنجاز الشخصي والأداء الوظيفي، حيث أن معاملات الانحدار ذات دلالة معنوية عند مستوى دلالة 0.001. (الميل β1: 0.059 بدلالة 0.614؛ 0.266 بدلالة 0.043؛ 0.905 بدلالة 0.000، جدول 19)"},{"sid":"syria","x":"على الرغم من أن النتائج حول أداء العاملين أظهر أنهم على درجة عالية من الأداء، ولكن هذا كسمات شخصية في أنهم يجتهدون في إنجاز الأعمال في الأوقات المحددة، إلا أن مجموع التركيز ومقابلات الإدارات أظهرت أن الضغوط أثرت على سوية أداء العاملين لتجعلها أقل جودة وكفاءة."},{"sid":"syria","x":"كما أظهرت النتائج على مستوى معدل دوران العمل، شعور العاملين في المنظمات الإنسانية، بأن عملهم مؤقت ولا بد في النهاية من الاستقرار، كما أظهرت النتائج أنهم على نية في ترك العمل، كما أن المقابلات أظهرت أن الضغوط وعدم المساواة وعدم التقدير تؤدي بالنهاية إلى ترك العمل، وهذا ما كان لهم من خبرة سابقة."},{"sid":"syria","x":"من الجدول السابق نلاحظ أن قيمة معامل الارتباط بين الاحتراق الوظيفي وأداء العاملين هو R=0.296 وهو ارتباط ضعيف، علماً أن حجم الأثر حسب R Square يظهر أن الاحتراق الوظيفي يؤثر بنسبة 9% على أداء العاملين. ... علماً أن هذا الأثر عكسي لكون إشارة B سالبة، مما يعني أنه كلما زاد الاحتراق الوظيفي قلّ معه أداء العاملين. (R Square = 0.088، B = 0.224 بإشارة سالبة، Beta = 0.296 بإشارة سالبة، t = 4.826 بإشارة سالبة، Sig. = 0.000)"}],"sort":{"t":"على الفرد أم على المنظمة؟","s":"صنّف كل أثر بحسب من يقع عليه، كما في الدليل.","bins":["تأثيره على الفرد","تأثيره على المنظمة"],"items":[["سلوكياً: العدوانية واللامبالاة والانسحاب",0],["نفسياً: القلق والإرهاق والتوتر العصبي",0],["أسرياً: الصراع في العلاقات الأسرية",0],["على الارتباط الوظيفي",1],["على الأداء الوظيفي",1],["على إنتاجية الموظف",1]]},"quiz":[{"q":"ما الحكم العام للدليل في من يتعرض للاحتراق الوظيفي؟","o":["جميع العاملين معرّضون له بنسب متفاوتة","أصحاب المهن الشاقة بدنياً أو ذهنياً فقط","النساء أكثر من الرجال لأنهن أضعف تحملاً","العاملون بأجر فقط دون الطلبة والأمهات"],"src":"guide","why":"جميع العاملين معرّضون للاحتراق الوظيفي بنسب متفاوتة بناءً على شخصية الفرد وظروف العمل.","pg":40},{"q":"لماذا عدّ الدليل المعلمين من الفئات الأكثر عرضة؟","o":["لتفاعلهم الدائم مع الجمهور ومتطلبات العمل العالية","لعملهم ساعات طويلة متواصلة تسبب لهم قلة النوم","لتحملهم مسؤوليات ليست من مهامهم الأصلية","لضغط الشهرة والظهور الذي يشعرهم بالتجرد من الشخصية"],"src":"guide","why":"العاملون في القطاعات الخدمية، مثل المعلمين، يواجهون ضغوطًا نفسية كبيرة نتيجة لتفاعلهم المستمر مع الجمهور ومتطلبات العمل العالية.","pg":40},{"q":"ماذا يحدث للأداء إذا وصل الضغط إلى مرحلة الاحتراق، بحسب الدليل؟","o":["ينخفض بشكل ملحوظ","يتحسن تحسناً مؤقتاً","يحافظ على مستواه","يرتفع ثم يستقر سريعاً"],"src":"guide","why":"إذا استمر الضغط ووصل إلى مرحلة الاحتراق الوظيفي، فإن الأداء ينخفض بشكل ملحوظ","pg":41},{"q":"في دراسة سورية، ما حجم أثر الاحتراق على دوران العمل؟","o":["قوي، يفسر قرابة 58% منه","ضعيف، يفسر قرابة 9% منه","متوسط، يفسر قرابة 30% منه","قوي، يفسر قرابة 76% منه"],"src":"guide","why":"حجم الأثر حسب R Square يظهر أن الاحتراق الوظيفي يؤثر بنسبة 58% على دوران العمل"},{"q":"في دراسة غزة، أي الفئات كانت الأقل معاناة من الاحتراق بحسب الحالة الاجتماعية؟","o":["فئة المتزوجين","فئة العزاب","فئة المطلقين","فئة الأرامل"],"src":"guide","why":"أظهرت النتائج أن فئة المتزوجين كانت الأقل معاناة من الاحتراق على أبعاده الثلاثة من الفئات الأخرى"}]},{"k":"prevent","t":"الوقاية","ic":"shield","q":"كيف تحمي نفسك قبل أن تشتعل؟","sections":[{"t":"كيف نتغلّب على الاحتراق الوظيفي؟","src":"guide","pg":44,"p":["يسعى كل موظف إلى إثبات نفسه في بيئة العمل وتحقيق النجاح المهني، مما يتطلّب جهدًا بدنيًا وذهنيًا كبيرًا، وقد يؤدي ذلك إلى التوتر النفسي، وإذا لم يتم التعامل مع هذا التوتر بشكل صحيح، فقد يتسبب في الاحتراق الوظيفي، وهي حالة خطيرة تؤثر على الصحة النفسية والجسدية. لذلك، من المهم تبني استراتيجيات وقائية لمواجهة هذه التحديات، والتدخل الفوري عند ظهور علامات الاحتراق الوظيفي لضمان التعافي واستعادة الطاقة والحيوية. يعتمد التعامل الفعّال مع هذه التحديات على مسؤوليات الفرد تجاه صحته، بالإضافة إلى التدخلات التي يجب أن تقوم بها المنظمات لدعم موظفيها.","الاحتراق الوظيفي غالبًا ما يكون نتيجة للإنهاك الشديد، حيث يستنزف القدرات العقلية والجسدية ويؤدي إلى الشعور بالعزلة وعدم الفاعلية. من المهم التصرّف على سجيّتك ومعرفة ما يعيد حماسك. إذا كنت شخصًا اجتماعيًا، فقد تحتاج إلى قضاء وقت مع الأصدقاء أو العائلة، أما إذا كنت تفضّل العزلة، فقد تحتاج إلى وقت بمفردك لإعادة شحذ طاقتك. فهم السبب وراء الاحتراق ومحاولة تخفيفه أمر ضروري للحفاظ على سعادتك وراحتك في العمل. يُنصح أيضًا بأن تكون لديك حياة اجتماعية نشطة بعيدًا عن العمل لتحقيق توازن صحي بين الحياة المهنية والشخصية، وللوصول إلى هذا التوازن بشكل فعّال، يمكن اتباع بعض الخطوات العملية:"],"key":"يعتمد التعامل الفعّال مع هذه التحديات على مسؤوليات الفرد تجاه صحته، بالإضافة إلى التدخلات التي يجب أن تقوم بها المنظمات لدعم موظفيها."},{"t":"فهم الذات","src":"guide","pg":45,"key":"فهم الذات هو الخطوة الأولى في تطوير الوعي الذاتي.","items":[{"h":"بعض الشخصيات، مثل الشخصية القلقة، تكون أكثر عرضة للاحتراق الوظيفي بسبب إدمانها على العمل. فهم سماتك الشخصية يساعدك على تحديد ما إذا كان العمل يدفعك للعطاء المتوازن أو يتجاوز طاقتك، مما يجعلك عرضة للاحتراق إذا لم تستعد طاقتك بالراحة والاستمتاع."},{"h":"العمل في مجال تستمتع به وترى فيه قيمة معنوية وروحية يمكن أن يقلل من احتمالية الاحتراق الوظيفي، لأن الشغف والإحساس بالهدف يمكن أن يكونا عوامل حماية."},{"h":"الشغف والإحساس بالهدف يمكن أن يساعدا في الوقاية من الاحتراق الوظيفي. فهم أهدافك يساعدك على توجيه طاقتك بشكل متوازن واستعادة نشاطك من خلال الراحة والاستمتاع."},{"h":"فهم الذات هو الخطوة الأولى في تطوير الوعي الذاتي. الأشخاص الذين يمتلكون ذهنية النمو يتعلمون ويتطورون بشكل طبيعي، ويكونون أكثر قدرة على التعامل مع الضغوط وأقل عرضة للإصابة بالاضطرابات النفسية. الوعي الذاتي يساعد أيضًا في النمو بعد الصدمة، مما يمكّن الشخص من فهم أسباب تعثّره واكتساب الخبرة اللازمة للتطور."},{"h":"فهم الذات يساعدك على وضع أهداف واقعية وقابلة للتحقيق في العمل، مما يقلّل من الشعور بالإحباط والضغط. كما يعزّز تطوير مهارات حياتية مهمة مثل المرونة النفسية، وتوكيد الذات، والذكاء العاطفي، واليقظة الذهنية، وإدارة الضغوط، وإدارة الوقت، وحل المشكلات. هذه المهارات تمكّنك من معرفة حدودك الشخصية وتمنحك القدرة على التكيّف مع التحديات وتحقيق التوازن في الحياة."}]},{"t":"فهم الآخرين","src":"guide","pg":46,"p":["معرفة سمات الشخصيات المحيطة بك يمكن أن يساعدك في تحسين التعامل معهم بشكل أفضل.","فهم طبيعة العمل الذي تقوم به، وهل هو محفّز لك ويساعدك على العطاء أم لا. هناك من يعمل لأكثر من 8 ساعات يوميًا دون الوصول إلى مرحلة الاحتراق بسبب طبيعة العمل المحفّزة. معرفة تحديات الوظيفة وفرصها والمجالات المرتبطة بها يساهم في:"],"key":"معرفة تحديات الوظيفة وفرصها والمجالات المرتبطة بها يساهم في:","items":[{"h":"تحسين التعامل مع المدراء، بما في ذلك التحدث حول تخفيف الأعباء عند الحاجة والاستفسار عن المهام غير الواضحة ومناقشة التوقّعات."},{"h":"التركيز على الجوانب الإيجابية في العمل ومناقشة الصعوبات مع الزملاء."},{"h":"تقليل التوقعات الخاصة بالعمل والإدارة لمواجهة التحديات الضاغطة، مع ضرورة الاستراحة وضبط النفس."},{"h":"تغيير بيئة العمل إذا لزم الأمر، سواء بالانتقال إلى قسم آخر أو البحث عن وظيفة جديدة."},{"h":"فهم طبيعة الزملاء وطلب الدعم منهم في تنظيم وإعداد المهام."},{"h":"التركيز على الجزء الإيجابي من العمل ومناقشة الصعوبات مع زملاء العمل."}],"stats":[{"n":"8 ساعات","x":"هناك من يعمل لأكثر من 8 ساعات يوميًا دون الوصول إلى مرحلة الاحتراق بسبب طبيعة العمل المحفّزة.","src":"لم يذكر الدليل مصدرًا"}]},{"t":"ربط الإنجاز بقيم عليا","src":"guide","pg":46,"p":["من الطبيعي أن يسعى الإنسان للعمل من أجل المال، لكن من الضروري أن يكون للعمل قيمة إضافية. الرضا عن الذات والراحة النفسية مهمان، ولكن يجب أن نجد في عملنا قيمة تعزّز من دوافعنا للإنجاز. يمكن أن يكون للعمل دور كبير في مساعدة المجتمع، وتسهيل حياة الناس، أو تقديم فوائد مثل التعليم، أو العلاج، أو حفظ الأمن."],"key":"ربط الإنجاز بقيم متعددة يساعد الموظف على تعويض ضعف إحدى القيم بقيمة أخرى، مما يقلّل من خطر الاحتراق النفسي ويعزّز الشعور بالرضا والاستمرارية في العمل.","items":[{"h":"ربط الإنجاز بقيم متعددة يساعد الموظف على تعويض ضعف إحدى القيم بقيمة أخرى، مما يقلّل من خطر الاحتراق النفسي ويعزّز الشعور بالرضا والاستمرارية في العمل."},{"h":"التعامل مع الرغبة في الإنجاز بلغة هادئة ومطمئنة يساعد في تقليل التوتر، وغالبًا ما يتمتع الأشخاص الذين يربطون إنجازهم بقيم عليا بهذا الهدوء، مما يعزّز قدرتهم على تحقيق أهدافهم بفعالية."},{"h":"ربط الإنجاز برضا الله سبحانه وتعالى يعزّز الدافع الداخلي، مما يساعد على تحقيق الأهداف بروح إيجابية ومستدامة."}]},{"t":"إدارة الوقت","src":"guide","pg":47,"key":"كما قال الباحث جيم كولينز: إذا كان لديك أكثر من ثلاث أولويات، فليس لديك أولويات.","items":[{"h":"تنظيم وتخطيط الوقت","x":"عملية تنظيم وتخطيط كيفية تقسيم وقتك بين الأنشطة المختلفة تهدف لتحقيق أقصى قدر من الكفاءة والإنتاجية."},{"h":"وضع حدود واضحة","x":"حدد أوقاتًا محددة للعمل وأخرى للراحة والأنشطة الشخصية، والتزم بها. اعمل بحدود طاقتك وتجنّب الساعات المفتوحة. وزّع العمل واطلب المساعدة لتجنّب الإرهاق. بعد انتهاء ساعات العمل، اترك المهام المتبقية لليوم التالي واسترح."},{"h":"ترتيب الأولويات","x":"حدد أهدافًا واضحة وقابلة للقياس، واستخدم قوائم المهام لتقليل الضغط النفسي. صنّف المهام حسب الأهمية والإلحاح باستخدام مصفوفة آيزنهاور. كما قال الباحث جيم كولينز: إذا كان لديك أكثر من ثلاث أولويات، فليس لديك أولويات. إنجاز العديد من المهام في وقت واحد يؤدي إلى الإجهاد وقلّة الإنتاجية. من المهم مناقشة هذه الأولويات مع المسؤول لضمان التركيز على المهام الأكثر أهمية وتحقيق أفضل النتائج."},{"h":"تخصيص الوقت","x":"استخدم جداول زمنية أو تطبيقات إدارة الوقت. دوّن أنشطتك اليومية ومدة كل منها لتكتشف مدى توازنك في توزيع وقتك. حدّد أوقاتًا محددة للتحقق من البريد الإلكتروني ووسائل التواصل الاجتماعي لتجنّب التشتت."},{"h":"الاستفادة من التكنولوجيا","x":"استخدم أدوات مثل التقويمات الرقمية لتخطيط مواعيدك، وتطبيقات المهام لتتبع تقدمك وإنجازاتك. برامج إدارة المشاريع تساعد في تنسيق العمل مع فريقك، بينما تطبيقات تحديد الأولويات تضمن أنك تبقى على المسار الصحيح."},{"h":"أخذ استراحات قصيرة","x":"من المهم أخذ استراحات قصيرة والقيام بتمارين الاسترخاء. يُنصح بالحصول على فترات راحة منتظمة خلال اليوم أو إجازات أطول للاستجمام."},{"h":"تقنية بومودورو","x":"قسّم العمل إلى فترات قصيرة (25 دقيقة) تتبعها فترات راحة قصيرة (5 دقائق). بعد أربع فترات عمل، خذ استراحة أطول (15-30 دقيقة) لزيادة التركيز والإنتاجية وتقليل التوتر."}],"stats":[{"n":"3 أولويات","x":"إذا كان لديك أكثر من ثلاث أولويات، فليس لديك أولويات.","src":"الباحث جيم كولينز، كما نقله الدليل دون سنة"}]},{"t":"تحقيق التوازن بين العمل والحياة الشخصية","src":"guide","pg":49,"p":["في دراسة أجرتها الرابطة الأمريكية لعلم النفس بجامعة شيكاغو، أظهرت النتائج أن 31% من الأشخاص يجدون صعوبة في إدارة مسؤوليات العمل والأسرة معًا، بينما أكد 53% أن العمل يسبب لهم حالة كبيرة من الإنهاك والتعب.","لتحقيق توازن أفضل، يمكنك طرح الأسئلة التالية على نفسك والإجابة عليها لتقييم أسلوب حياتك الحالي:","الإجابة على هذه الأسئلة يمكن أن تساعدك في اكتساب فهم أعمق لأسلوب حياتك الحالي. في عالمنا المعاصر، تتزايد الضغوط اليومية والتحديات التي تؤثر على توازنك. لذا، فإنه من الضروري اتباع نمط حياة صحي يحقّق لك التوازن بين العمل والحياة الشخصية، مما يلبي احتياجاتك الأساسية، فتستعيد نشاطك باستمرار وتتجنّب الاحتراق النفسي والوظيفي، مما يحسّن جودة حياتك بشكل عام.","التوازن هو مفتاح السعادة والنجاح في الحياة. ولتحقيقه، يجب النظر في جميع جوانب حياتك والتركيز على أربعة جوانب رئيسية، حيث يحتوي كل جانب على ثلاثة عناصر يمكن تقسيمها إلى فئتين أساسيتين: داخلية وخارجية. تشمل العناصر الداخلية الجوانب التي تخصك كشخص، مثل الصحة الجسدية والنفسية، والنمو الشخصي والتطوير الذاتي، والاسترخاء والراحة. أما العناصر الخارجية فتشمل المحيطين بك من أشخاص وأماكن، مثل العلاقات الاجتماعية والعائلية، والبيئة المهنية والعمل، والأنشطة الترفيهية والمجتمعية. بالتركيز على هذه الجوانب والعناصر، يمكنك تحقيق توازن أمثل بين العمل والحياة الشخصية، مما يؤدي إلى السعادة والنجاح في جميع جوانب حياتك. فلو كنت تمتلك ثروة طائلة أو تتمتع بصحة ممتازة، لن تشعر بالسعادة إذا كان هناك جانب آخر تعاني فيه من نقص، مما يعني عدم تلبية احتياجاتك الأساسية بشكل كامل."],"key":"التوازن هو مفتاح السعادة والنجاح في الحياة.","items":[{"h":"كيف يمكنني تخصيص وقت لنفسي وللنشاطات التي أرغب بالقيام بها بمفردي؟"},{"h":"كيف أتحدّى نفسي فكرياً وأخلق فرصاً لعقلي للراحة؟"},{"h":"هل أهتم بصحتي بشكل كافٍ مثل: أخذ فترات راحة، ممارسة الرياضة، الاسترخاء؟"},{"h":"كيف أؤدي واجباتي ومسؤولياتي تجاه عائلتي الممتدة مع الحفاظ على حدود صحية مناسبة؟"},{"h":"هل أحرص على تحفيز نفسي لتحقيق النجاح في عملي مع الاستمتاع برحلتي نحو هذا الهدف؟"},{"h":"كيف أخصّص وقتاً للأنشطة التي أستمتع بها حقاً دون الإفراط فيها؟"}],"stats":[{"n":"31%","x":"من الأشخاص يجدون صعوبة في إدارة مسؤوليات العمل والأسرة معًا","src":"دراسة أجرتها الرابطة الأمريكية لعلم النفس بجامعة شيكاغو، كما ورد في الدليل دون سنة"},{"n":"53%","x":"أكدوا أن العمل يسبب لهم حالة كبيرة من الإنهاك والتعب","src":"الدراسة نفسها: الرابطة الأمريكية لعلم النفس بجامعة شيكاغو، دون سنة"}]},{"t":"العناصر الـ12 لتحقيق توازن صحي بين العمل والحياة الشخصية","src":"guide","pg":51,"p":["العقل يمثّل المعرفة، والتوازن في جانب العقل يعني القراءة. أما في جانب الجسم، فهو يشمل الصحة واللياقة البدنية، مثل ممارسة الرياضة والتغذية السليمة. المعرفة في المال تتعلق بالأمور المالية وإدارة المال، مثل التخطيط المالي والاستثمار. المعرفة في القلب تتعلّق بالعلاقات الاجتماعية والنفسية، مثل فهم الذات وتطوير العلاقات مع الآخرين. هذه التصنيفات تهدف إلى تعزيز التفكير والتأمل والمعرفة، مما يساعد على تحسين الصحة العقلية والنفسية. وبالتالي، يمكن للشخص أن يضع خطته الشخصية على أساس متين وثابت ومستقر من المعرفة."],"key":"تنمية الهوايات ليست رفاهية، بل هي جزء مهم من الاستقرار النفسي والصحي، وتساعدك على الاسترخاء والتجديد.","items":[{"h":"01 النوم الجيد","x":"النوم الجيد مهم جدًا للصحة العامة، الشخص البالغ قد يحتاج إلى النوم من 6 إلى 8 ساعات يوميًا، مع إمكانية إضافة ساعة قيلولة، والأهم هو أن تستيقظ وأنت تشعر بالراحة والنشاط، كما يجب أن يكون النوم في ساعات منتظمة لتجنّب اضطرابات النوم التي تؤثر على الصحة العامة والإنتاجية. اضطرابات النوم تؤثر بشكل كبير على الصحة النفسية والجسدية، والحفاظ على جودة النوم يعزز الأداء والإنتاجية، ويحسن الذاكرة والتركيز، ويقلّل من الإجهاد. العلاج المعرفي السلوكي للأرق (CBT-I) يستخدم تقنيات لتحسين نوعية النوم من خلال تعديل الأفكار والسلوكيات، يشمل ذلك إعادة هيكلة الأفكار السلبية، وتقييد وقت النوم، والتحكّم بالمحفزات، كما يمكن تحسين النوم من خلال ممارسة تمارين الاسترخاء مثل التنفس العميق، وإنشاء روتين ثابت للنوم يتضمن أنشطة مريحة قبل النوم، وإذا استمرت مشكلات النوم، يُفضّل استشارة مختص في العلاج المعرفي السلوكي.","grp":"الجسد: الصحة البدنية"},{"h":"02 التغذية السليمة","x":"تلعب التغذية الصحية دورًا كبيرًا في تحسين الصحة العامة وتقليل الإجهاد. تناول الأطعمة الغنية بالفيتامينات والمعادن مثل الأوميغا-3 الموجودة في الأسماك والمكسرات، والفواكه والخضروات، يساعد في تحسين المزاج وتقليل التوتر. البروتينات، والألياف، والدهون الصحية تزيد من الطاقة والإنتاجية. شرب الماء بانتظام يحسن التركيز ويخفف التعب، مما يقلّل من احتمالية الاحتراق الوظيفي. تناول الأطعمة الغنية بمضادات الأكسدة مثل الفواكه والخضروات يحمي خلايا الجسم من التلف الناتج عن الإجهاد التأكسدي. الأطعمة المخمّرة مثل الزبادي تعزّز صحة الأمعاء وتحسّن الصحة النفسية. لتقليل التوتر، يُنصح بتناول الأطعمة الغنية بالأوميغا-3، والكربوهيدرات المعقّدة، والمغنيسيوم، والأطعمة المخمرة، وتجنّب الأطعمة المعالجة والمشروبات المحلّاة بالسكر، بالإضافة إلى تجنّب التدخين والكحول. يجب أيضًا ملاحظة ما هو الأكل المناسب لجسمنا للحفاظ على الوزن المثالي. نقضي ساعتين يوميًا في إعداد الطعام أو تناوله، لذا حاول تكريس هاتين الساعتين في غذاء صحي. لا تأكل وتنام مباشرة، بل نم واستيقظ ثم تناول الطعام. تناول وجبات غذائية متوازنة تحتوي على جميع العناصر الغذائية الضرورية، وتجنّب الأطعمة السريعة والمشروبات الغازية.","grp":"الجسد: الصحة البدنية"},{"h":"03 الأنشطة الرياضية","x":"الحفاظ على نشاط بدني منتظم مهم جدًا. توصي منظمات صحية عالمية مثل منظمة الصحة العالمية (WHO) ومراكز مكافحة الأمراض والوقاية منها (CDC) بممارسة 150 دقيقة من النشاط البدني أسبوعيًا، موزعة على 3-4 مرات في الأسبوع، كل مرة لمدة 30-40 دقيقة. يجب أن يكون النشاط مكثّفًا بما يكفي لزيادة معدل ضربات القلب، مثل تمارين الكارديو، وأبسطها المشي، بينما يُعتبر الذهاب إلى النادي الرياضي أفضل. الأنشطة الرياضية تنقسم إلى نوعين: الأنشطة الفردية مثل الذهاب إلى النادي الرياضي ورفع الأثقال، والأنشطة الجماعية التي تتضمن روح المنافسة والتعاون. يُنصح بممارسة الأنشطة الفردية مرتين في الأسبوع والأنشطة الجماعية مرة واحدة على الأقل. للرياضة تأثير كبير على الصحة النفسية، حيث تساهم في تحسين المزاج وزيادة الطاقة وتقليل الإجهاد، وتشير الدراسات إلى أن الرياضة يمكن أن تساعد في علاج الاكتئاب الخفيف وزيادة الشعور بالسعادة، مما يساهم في الوقاية من الاضطرابات النفسية.","grp":"الجسد: الصحة البدنية"},{"h":"04 المهنة","x":"اختر مهنة تحبها وتحقّق لك دخلاً جيدًا، فإذا كنت تعمل في وظيفة لا تحبها، ابحث عن أخرى تلبي احتياجاتك المالية والشخصية، وتذكر أن حوالي 16 ساعة من يومك تذهب في العمل والنوم. ليس كل هواية يمكن تحويلها إلى مهنة، لذا استمر في العمل حتى تجد ما تحب ويحقق لك دخلاً جيدًا.","grp":"المال: الجانب المالي"},{"h":"05 المشتريات","x":"عند الشراء، من المهم التمييز بين الحاجات الأساسية والرغبات. الحاجات هي الأشياء الضرورية مثل الأكل والشرب والمسكن، بينما الرغبات هي الأشياء التي يمكن تأجيلها حتى تكون لديك القدرة المالية، لذا، ركز على شراء الضروريات وتأجيل الكماليات حتى تتمكّن من تحمّل تكاليفها.","grp":"المال: الجانب المالي"},{"h":"06 الموازنة الشخصية","x":"لإدارة أموالك بفعالية، ابدأ بإعداد ميزانية شهرية تشمل الإيرادات والمصروفات، فإذا كانت المصروفات تتجاوز الإيرادات، حاول تقليلها أو زيادة دخلك، وفي حال كانت الإيرادات أكبر، استثمر الفائض لتحقيق عائد مستقبلي أو استخدمه لشراء حاجات إضافية. تعلم كيفية إدارة أموالك بفعالية من خلال الالتزام بالميزانية الشهرية. ادخر جزءًا من دخلك بانتظام وفكر في استثمار أموالك لتنميتها على المدى الطويل. وأخيرًا، ضع خططًا مالية طويلة الأجل مثل: التخطيط للتقاعد أو شراء منزل لضمان مستقبل مالي مستقر.","grp":"المال: الجانب المالي"},{"h":"07 الدين","x":"الالتزام بالحد الأدنى من الطاعات والعبادات يمكن أن يمنحك الرضا الروحي ويساعد في بناء ذهنية النمو، مما يسهم في التعامل مع الضغوط وتقليل احتمالية الإصابة بالاضطرابات النفسية. ليس من الضروري أن تكون متدينًا بشكل كامل وتقوم بكل شيء؛ من الطبيعي أن نقصّر أحيانًا، والإيمان يتفاوت. لذا، نسأل أنفسنا: ما هو الحد الأدنى من الأمور التي إذا قمنا بها نكون ملتزمين بديننا؟ وكم من الوقت تأخذ منا يوميًا وأسبوعيًا وشهريًا؟ نحاول تخصيص وقت منتظم للطاعات التي نقصّر فيها ونقوم بها بشكل أكثر انتظامًا.","grp":"القلب: العلاقات والعواطف"},{"h":"08 الحب","x":"يشمل جميع العلاقات الإنسانية. خصص وقتًا للعلاقات مع الأهل والأصدقاء، واهتم بحياة اجتماعية نشطة لتحقيق توازن صحي بين العمل والحياة الشخصية. تواصل جيدًا مع العائلة والأصدقاء لتعزيز الروابط، واهتم بشريك حياتك لقضاء لحظات مميزة معًا.","grp":"القلب: العلاقات والعواطف"},{"h":"09 الهوايات","x":"إذا لم تستطع العمل في شيء تحبه باعتباره هواية، اعمل فيما يجلب لك دخلاً حتى تتمكّن من العمل فيما تحب. نمِّ اهتماماتك الخارجية وخصص وقتًا لممارسة هواياتك، سواء كانت الرسم، الكتابة، أو أي نشاط آخر تستمتع به. املأ وقت فراغك بأنشطة تحبها أو طور هواية جديدة. تنمية الهوايات ليست رفاهية، بل هي جزء مهم من الاستقرار النفسي والصحي، وتساعدك على الاسترخاء والتجديد. تأكد أن الهواية لا تأخذ من وقتك المخصّص للنوم أو العمل أو الطاعات. حاول التوازن بين هواياتك والعناصر الأخرى، كما أن المشاركة في الأنشطة الخيرية والتطوعية تعزّز الشعور بالانتماء والتواصل الاجتماعي، مما يحسّن الحالة العاطفية والنفسية ويزيد من الشعور بالرضا والسعادة.","grp":"القلب: العلاقات والعواطف"},{"h":"10 التعلم المستمر","x":"هو عملية تطوير المهارات والمعرفة بشكل دائم من خلال القراءة، الدورات التدريبية، المشاركة في الندوات والمؤتمرات، التعلم من التجارب الشخصية والمهنية، والاستفادة من المنصات التعليمية عبر الإنترنت. هذا النوع من التعلم يعزّز الثقة بالنفس والقدرة على التكيّف مع التغيرات المستمرة في الحياة والمهنة.","grp":"العقل: التعلم والتطوير الذاتي"},{"h":"11 الوعي الذاتي","x":"يلعب دورًا مهمًا في النمو بعد الصدمة، حيث يساعد الشخص على فهم أسباب تعثّره واكتساب الخبرة اللازمة للتطور. استمر في تطوير مهاراتك ومعرفتك من خلال التعلم المستمر.","grp":"العقل: التعلم والتطوير الذاتي"},{"h":"12 التأمّل والاسترخاء","x":"ممارسة التأمّل أو اليوغا لتحسين التركيز وتهدئة العقل. ممارسة الهوايات التي تثير اهتمامك وتساعدك على الاسترخاء. للاسترخاء، من المهم احترام حدودك الشخصية وتخصيص وقت للراحة. يمكنك شحن طاقتك بالجلوس مع أحبائك وممارسة هواياتك، والحصول على إجازة للاستجمام والسفر. أخذ استراحات قصيرة أثناء العمل وممارسة تمارين الاسترخاء مع الاستماع إلى موسيقى هادئة يمكن أن يساعد في تقليل مستويات التوتر. تعلم تقنيات التحكم في الضغط مثل التأمل والتنفس العميق واليوغا يمكن أن يكون مفيدًا أيضًا.","grp":"العقل: التعلم والتطوير الذاتي"}],"stats":[{"n":"6 إلى 8 ساعات","x":"الشخص البالغ قد يحتاج إلى النوم من 6 إلى 8 ساعات يوميًا، مع إمكانية إضافة ساعة قيلولة","src":"لم يذكر الدليل مصدرًا"},{"n":"150 دقيقة","x":"من النشاط البدني أسبوعيًا، موزعة على 3-4 مرات في الأسبوع، كل مرة لمدة 30-40 دقيقة","src":"توصية منظمة الصحة العالمية (WHO) ومراكز مكافحة الأمراض والوقاية منها (CDC) كما نسبها الدليل، دون سنة"},{"n":"ساعتان","x":"نقضي ساعتين يوميًا في إعداد الطعام أو تناوله","src":"لم يذكر الدليل مصدرًا"},{"n":"16 ساعة","x":"حوالي 16 ساعة من يومك تذهب في العمل والنوم","src":"لم يذكر الدليل مصدرًا"}]},{"t":"كيف يمكنك تحقيق التوازن بين العمل والحياة الشخصية؟","src":"guide","pg":55,"p":["لتحقيق هذا التوازن، عليك أولاً تحديد مقدار الوقت والجهد الذي تستثمره في كل جانب من جوانب حياتك، وما الذي تتلقّاه بالمقابل؟","أخيراً، ثق بأنك ستصل إلى التوازن المطلوب ما دمت تجاهد لتحقيقه، قد تواجه بعض الإخفاقات، لكن لا تقلق، فالهزيمة للشجعان لأن الجبناء لا يخوضون المعارك أصلاً."],"key":"التوازن الحقيقي بين العمل والحياة الشخصية يعني تحقيق التوازن في طاقتك أيضاً.","items":[{"h":"ضع جدولاً زمنياً والتزم به","x":"تنظيم ساعات يومك قد يبدو مرهقاً في البداية، لكنه يمنحك المزيد من الحرية، حيث يمكنك القيام بكل ما تريد في الوقت الذي تريده."},{"h":"لا تسمح لجانب من حياتك أن يتداخل مع الجوانب الأخرى","x":"تجنّب قراءة البريد الإلكتروني المهني خلال العشاء في المنزل أو الاتصال بعميل أثناء إجازتك، لأن ذلك قد يؤدي إلى طغيان حياتك المهنية على حياتك الشخصية."},{"h":"جدولك الزمني وحده ليس كافياً","x":"تنظيم يومك حسب جدولك ليس سوى نصف المعركة. تأكد من معرفة جداول المحيطين بك حتى لا يحدث تعارض."},{"h":"حلّل وقتك","x":"إحدى الطرق الفعّالة لمكافحة تضييع الوقت هي تحليله. استفد من وقتك بأقصى قدر ممكن من خلال قضاءه في الأنشطة التي تعود عليك بالفائدة."},{"h":"فكّر أبعد من مجرّد الوقت","x":"أن تكون في مكان ما جسدياً يختلف عن أن تكون متواجداً حقاً. تجنّب الانشغال بالعمل أثناء الاجتماعات العائلية، والعكس صحيح."},{"h":"جدّد طاقتك","x":"التوازن الحقيقي بين العمل والحياة الشخصية يعني تحقيق التوازن في طاقتك أيضاً. إذا كنت متعباً أو مرهقاً، لن تتمكّن من أداء عملك بكفاءة. احرص على مراقبة مستوى طاقتك ونشاطك، ولا تتردّد في أخذ قسط من الراحة عند الحاجة."}]},{"t":"دراسة موقف: رحلة أحمد نحو التوازن","src":"guide","pg":57,"p":["بعد تخرّجه بامتياز مع مرتبة الشرف الأولى من جامعة الملك فهد للبترول والمعادن، تخصّص في شبكات الحاسب الآلي، بدأ أحمد مسيرته المهنية في شركة كبيرة، وبفضل مهاراته الفائقة، نال ثقة الإدارة بسرعة وكُلِّف بالعديد من المهام التي أنجزها بكفاءة عالية، وكان أحمد يعمل لساعات طويلة، مما جعله منعزلاً عن زملائه الذين كانوا يغارون منه لقربه من المدير ويتهمونه بالغرور.","هذا الضغط المستمر أثر على حياته الشخصية بشكل كبير. فعند عودته إلى المنزل، يكون مرهقًا جدًا ولا يستطيع التفاعل مع عائلته، وغالبًا ما كان ينام فور وصوله دون تناول العشاء، وتولّت زوجته إدارة شؤون المنزل والأولاد بالكامل، وفي أحد الأيام، نسي موعدًا مهمًا مع والده بسبب انشغاله بعمله، مما أغضب والده بشدة، فأدرك أحمد أنه بحاجة لإعادة التوازن في حياته، وقرّر أحمد الخروج في نهاية ساعات العمل الرسمية لتخصيص وقت لعائلته، مما أغضب مديره لأنه أصبح يؤجّل إنجاز بعض المهام لليوم التالي. ومع تدخل أحد الموظفين الناقمين على أحمد، تدهورت علاقته بالمدير وتفاقم الخلاف بينهما. فالمدير يرى أن خروج أحمد مع نهاية ساعات العمل الرسمية تراجع في أدائه المهني، بينما يرى أحمد أن ذلك حق ضائع استرده. وأصبحت ردود أفعال أحمد انفعالية على غير عادته. لم يتقبل المدير تصرفات أحمد، فوجّه إليه لفت نظر وأعطاه تقييم أداء منخفضًا، وكأنه لم يقم بأي عمل طوال العام، ومنعه من حضور البرنامج التدريبي الذي كان ينتظره بشغف، مما أثّر على ترقية أحمد التي كان يترقّبها، وأدى ذلك إلى شعوره بالإحباط والقهر وخيبة الأمل.","وبدأ أحمد يعاني من صداع مزمن وشعور مستمر بضيق التنفس، مما دفعه للحصول على إجازة لمدة شهر. خلال هذه الإجازة، لم يكن سعيدًا حيث ظل ملازمًا المنزل يفكر في قلة التقدير وعدم الإنصاف التي تعرض لها. زادت تعاسته لأنه كان يتمنى السفر للاسترخاء من الضغط النفسي، ولكنه لم يتمكن نظرًا لعدم توفر المال الكافي. وعلى الرغم من راتبه المرتفع، إلا أن النفقات المتزايدة لتوفير احتياجات أبنائه والمصاريف المبالغ فيها لتعويضهم عن غيابه المستمر كانت تستهلك أغلب دخله. عندما عاد إلى العمل، كان شاحبًا ونحيفًا، مع هالات سوداء تحت عينيه، ويعاني من صعوبة في المشي نتيجة آلام في العظام والمفاصل التي أهملها لفترة طويلة. لاحظ أحد زملائه المقربين، الذي حضر دورة عن الاحتراق الوظيفي، علامات الاحتراق على أحمد، فنصحه بمراجعة مختص نفسي.","أوضح المختص لأحمد أن ما يعاني منه هو احتراق وظيفي، وساعده في وضع برنامج يعينه على التعافي واستعادة توازن حياته بجوانبها المختلفة. بدأ أحمد يذهب للصلاة في المسجد كما اعتاد منذ طفولته، مما وطّد علاقاته بسكان الحي مجددًا، وأصبح أكثر قربًا من أسرته وعائلته حيث خصّص وقتًا للزيارة العائلية والنزهة الأسبوعية مع زوجته وأبنائه، وبدأ يمارس هوايته بلعب الورق وانتظم في مواعيد جلسات العلاج الطبيعي، كما أصبح يمارس المشي يوميًا برفقة زميله الذي أصبح صديقًا مقرّبًا منه. بفضل تغيير نمط حياته وبدعم صديقه، تعافى أحمد من الاحتراق الوظيفي، لكنه أصبح غير قادر على الاستمرار في العمل في نفس الشركة، وبفضل سمعته الجيدة بين الشركات، حصل أحمد على فرصة عمل جديدة بعرض وظيفي أفضل. قبل أن يبدأ العمل الجديد، قرر ألا يعيد نفس الأخطاء السابقة وأن يستمر على نمط حياته الحالي ويعيد النظر في توازنه كلما عصفت به الضغوط، فقرر أحمد أن يعيد موازنة لمصروفاته ويضع خطة ادخار ليتمكن من شراء أرض يبني عليها منزل أحلامه في غضون سنتين على الأكثر."],"key":"بفضل تغيير نمط حياته وبدعم صديقه، تعافى أحمد من الاحتراق الوظيفي","items":[{"h":"ما الأخطاء التي ... ارتكبها أحمد في حياته المهنية والشخصية وأدت إلى وصوله إلى مرحلة الاحتراق الوظيفي؟"},{"h":"هل تحقّق ... التوازن بين عملك وحياتك الشخصية أم أن هناك خللاً ما؟"},{"h":"كيف يمكنك ... تجنّب الوقوع في نفس الأخطاء وتحقيق التوازن بين العمل والحياة الشخصية؟"}]}],"strat":["self_know","know_others","higher_values","clear_limits","priorities","time_alloc","tech_tools","short_breaks","pomodoro","sleep","nutrition","exercise","career","purchases","budget","religion","love","hobbies","lifelong","self_aware","relax","balance_steps"],"ev":[{"sid":"gaza2010","x":"حالة الاحتراق الوظيفي ليست بالدائمة وبالإمكان تفاديها والوقاية منها. ويعتبر قيام الفرد العامل بدوره المتمثل في حياة متوازنة من حيث التغذية والنشاط الحركي والاسترخاء الذهني من الأمور الحيوية والمكملة للجهود المؤسسية في تفادي الاحتراق الوظيفي، حيث لا توجد وسيلة أو وصفة سحرية قادرة على التصدي للاحتراق الوظيفي إلا أن الدراسات العديدة التي تناولت الموضوع قدمت حلولا و استراتيجيات يمكن توظيفها للتخفيض من حدته و بالتالي مواجهته.","th":1},{"sid":"syria","x":"العاملون: الاهتمام بالصحة البدنية والنفسية. التقليل من التوقعات الخاصة بالعمل والإدارة، وبحل المشاكل. حل المشاكل من جذورها، وإذا اضطر الأمر استشارة طبيب نفسي. السعي للحصول على عمل آخر مناسب. أخذ الأمور بروية، وممارسة الحياة بشكل طبيعي. تذكير المدير بالأسئلة والاستفسارات الممكنة، وتحديد جدول زمني للمهام، وأولياتها. النقاشات المستمرة لإيصال الحقوق.، المدراء: من خلال الإجازات والسفر. التنظيم. دعم الأهل والأصدقاء. الانتقال إلى قسم آخر. التركيز على الجزء الإيجابي من العمل، ومناقشة الصعوبات مع زملاء العمل.، اقتراحات المدراء لتحسين بيئة العمل: تأمين علاوات ومكافآت. خلق سياسة فرص التنقل بين الأقسام. توضيح المهام للعاملين. مساعدة الموظفون الجدد على الترحيب بهم ضمن فريق العمل. المساواة بين جميع العاملين. الاستقرار في العمل، والثقة المتبادلة يُحسن من بيئة العمل.","th":1}],"sort":{"t":"العناصر الـ12 للتوازن","s":"صنّف كل عنصر في جانبه من جوانب الحياة كما في الدليل.","bins":["الجسد","المال","القلب","العقل"],"items":[["النوم الجيد",0],["الأنشطة الرياضية",0],["المهنة",1],["الموازنة الشخصية",1],["الدين",2],["الهوايات",2],["التعلم المستمر",3],["التأمّل والاسترخاء",3]]},"quiz":[{"q":"ما الخطوة الأولى في تطوير الوعي الذاتي بحسب الدليل؟","o":["فهم الذات","فهم الآخرين","إدارة الوقت","تقدير الذات"],"src":"guide","why":"فهم الذات هو الخطوة الأولى في تطوير الوعي الذاتي.","pg":45},{"q":"كيف تعمل تقنية بومودورو كما في الدليل؟","o":["عمل 25 دقيقة تتبعه راحة قصيرة 5 دقائق","عمل 25 دقيقة تتبعه راحة طويلة 30 دقيقة","عمل 50 دقيقة تتبعه راحة قصيرة 10 دقائق","عمل 4 فترات متصلة ثم راحة 15 دقيقة"],"src":"guide","why":"قسّم العمل إلى فترات قصيرة (25 دقيقة) تتبعها فترات راحة قصيرة (5 دقائق).","pg":47},{"q":"لماذا يدعو الدليل إلى ربط الإنجاز بقيم متعددة؟","o":["ليعوّض ضعف إحدى القيم بقيمة أخرى","ليجعل المال الدافع الوحيد للإنجاز","ليرفع توقعاته من نفسه ومن عمله","ليربط رضاه عن نفسه بالإنجازات المادية"],"src":"guide","why":"ربط الإنجاز بقيم متعددة يساعد الموظف على تعويض ضعف إحدى القيم بقيمة أخرى","pg":46},{"q":"«إذا كان لديك أكثر من ثلاث أولويات، فليس لديك أولويات». لمن هذه العبارة في الدليل؟","o":["الباحث جيم كولينز","كريستينا ماسلاش","الطبيب جورج بيرد","الباحثة سوزان جاكسون"],"src":"guide","why":"كما قال الباحث جيم كولينز: إذا كان لديك أكثر من ثلاث أولويات، فليس لديك أولويات.","pg":47},{"q":"ما المقصود بقول الدليل: «التوازن الحقيقي يعني تحقيق التوازن في طاقتك أيضاً»؟","o":["ألا يكفي الحضور الجسدي، فلا بد من تجديد الطاقة","أن تقسم ساعات يومك بالتساوي بين العمل والأسرة","أن تعمل أكثر في أوقات نشاطك وتقلل العمل في غيرها","أن تنظم جدولك الزمني فهو وحده يكفي للتوازن"],"src":"guide","why":"إذا كنت متعباً أو مرهقاً، لن تتمكّن من أداء عملك بكفاءة.","pg":55},{"q":"إلى أي جانب من جوانب الحياة ينتمي «الدين» في العناصر الـ12؟","o":["القلب: العلاقات والعواطف","الجسد: الصحة البدنية واللياقة","المال: المهنة والموازنة","العقل: التعلم والتطوير"],"src":"guide","pg":51}]},{"k":"recover","t":"التعافي","ic":"sun","q":"إذا وقع الاحتراق، فكيف تعود إلى الإشراق؟","sections":[{"t":"مواجهة الاحتراق الوظيفي","src":"guide","pg":59,"p":["عند ملاحظة أي من علامات الاحتراق الوظيفي المبكرة، من المهم أولاً الاعتراف بوجود المشكلة والتحدث إلى رئيسك في العمل أو أي مسؤول آخر يمكنه المساعدة. جرّب بعض الحلول لتقليل التوتر واستعادة طاقتك، مثل أخذ إجازة قصيرة لتجديد طاقتك الذهنية والبدنية. هذا سيساعدك على تقييم وضعك المهني ومستوى التوتر والضغوط التي تواجهها، كما أن معرفة حقوقك وواجباتك وإعادة صياغة أهدافك لتكون واقعية وقابلة للتحقيق يمكن أن يساعد في تجنّب الإحباط.","تذكّر أن التعافي من الاحتراق الوظيفي هو مسؤولية شخصية، حيث يحدد الموظف نفسه أعراضه وليس الطبيب أو المدير، فالاحتراق الوظيفي يحدث عندما لا يستطيع الموظف نفسيًا وبدنيًا الاستمرار في عمله، وليس بسبب كره العمل أو التأثر بأشخاص سلبيين، بل نتيجة لتغيير في نمط العمل، الحياة الشخصية، أو الفكر والإدراك.","من المهم أن نذكر أن الاحتراق الوظيفي هو حالة يمرُّ بها الموظف وليس اضطرابًا نفسيًا، بل هو ضغط شديد مرتبط بالعمل، وأن استمراره قد يؤدي إلى اضطرابات نفسية، لكنه يظهر بشكل تدريجي وليس فجأة، وتعود هذه الحالة إلى ثلاث تغيرات رئيسية هي: البيئة المحيطة، نمط الحياة الشخصية، وأسلوب التفكير."],"key":"تذكّر أن التعافي من الاحتراق الوظيفي هو مسؤولية شخصية، حيث يحدد الموظف نفسه أعراضه وليس الطبيب أو المدير","items":[{"h":"تغير في بيئة العمل: البحث عن السبب الجذري","x":"أي لتغيير في بيئة العمل يمكن أن يؤثر على الأداء، ويجعلك تعاني من الاحتراق الوظيفي وتشعر بالقهر وعدم القدرة على العمل بسبب التغيرات في بيئة العمل، وعدم قدرتك على تحمل توجيهات مديرك أو التعامل مع زملائك، أو تفضيلك الجلوس وحدك، أو عدم رؤيتك لهدف من عملك، فهذه علامات على الاحتراق الوظيفي، ومن المهم كذلك أن تفهم السبب الأساسي وراء هذه المشاعر، قد يكون السبب شخصًا معينًا أو أسلوبًا معينًا في التعامل، وتراكم هذه الأمور قد يجعلك تكره بيئة العمل بأكملها، فعلى سبيل المثال، لو كنت تحت ضغط تسليم مشروع، مما يجعلك عنيفًا في التعامل وتضطر للعمل لساعات طويلة، فهذا ليس الوضع الطبيعي، بل حالة طارئة وستمر. معرفة السبب الجذري للمشكلة يجنّبك كراهية العمل بأكمله، ويساعدك في التعامل مع الجزء المحدّد من المشكلة."},{"h":"تغير في الحياة الشخصية: إعادة التوازن في الحياة","x":"التغيرات في الحياة الشخصية قد تجعل الشخص غير قادر على الأداء أو العمل. لتحقيق التوازن بين العمل والحياة الشخصية، هناك 12 عنصرًا يجب مراعاتها، وأهمها النوم، الذي غالبًا ما نضحي به عند الشعور بالضغط، لكنه في الواقع ميزان الحياة. تم توضيح هذه العناصر الـ 12 بالتفصيل عند الحديث عن إعادة التوازن بين العمل والحياة الشخصية في صفحة 49."},{"h":"تغير في طريقة إدراك الأمور: تجنب السعي وراء الكمال","x":"قد تكون بيئة العمل والحياة الشخصية كما هي، ولكن التغير في إدراك الأمور الذي يمكن أن يؤثر بشكل كبير على الأداء. السعي للكمال في كل شيء والنظر للأمور من منظور مثالي يمكن أن يكون مرهقًا ومهلكًا. من المهم أن نتذكر أن الكمال ليس مطلوبًا، وأن الاعتناء بالنفس يأتي أولاً."}]},{"t":"التعافي من الاحتراق الوظيفي","src":"guide","pg":60,"p":["إذا ظهرت عليك أعراض شديدة تؤثّر على قدرتك على أداء مهامك اليومية في المنزل أو العمل، مثل مشاكل الجهاز الهضمي كالقولون العصبي، فمن المهم البحث عن مساعدة مختص. الضغط النفسي المستمر يمكن أن يسبب مشاكل صحية، بما في ذلك مشاكل في العضلات والعظام والمفاصل.","الاحتراق الوظيفي ليس مرضًا يحتاج إلى تشخيص طبي، لكنه يمكن أن يتطور إلى اضطرابات نفسية مثل اضطراب عدم التكيف، القلق، أو الاكتئاب إذا لم يتم التعامل معه بشكل صحيح، إليك مجموعة من طرق التدخلات العلاجية:"],"key":"الاحتراق الوظيفي ليس مرضًا يحتاج إلى تشخيص طبي، لكنه يمكن أن يتطور إلى اضطرابات نفسية مثل اضطراب عدم التكيف، القلق، أو الاكتئاب إذا لم يتم التعامل معه بشكل صحيح","stats":[{"n":"أكثر من 10000 شخص سنويًا","x":"في اليابان يموت أكثر من عشرة آلاف شخص سنويًا بسبب الإرهاق من العمل","src":"لم يذكر الدليل مصدرًا ولا سنة"}]},{"t":"المرحلة الأولية من الاحتراق الوظيفي","src":"guide","pg":61,"key":"إذا كان أسلوب حياتك يحتاج إلى تغيير، بادر الآن بإرادتك لتجنّب التغيير تحت الضغط لاحقًا.","items":[{"h":"الرعاية الذاتية","x":"ممارسة الرياضة بانتظام، تناول وجبات متوازنة، الحصول على قسط كافٍ من النوم."},{"h":"الاستجمام","x":"أخذ فترات راحة منتظمة والقيام بأنشطة ترفيهية لتجديد الطاقة وتحسين المزاج."},{"h":"دعم الأهل والأصدقاء","x":"التحدث مع الأصدقاء والعائلة للحصول على الدعم العاطفي وتفهم الظروف التي تمر بها."},{"h":"الحد من التوتر القائم على اليقظة","x":"تقنيات مثل التأمل والتنفس العميق تساعد في تهدئة الدماغ وتقليل التوتر."},{"h":"الابتعاد عن مصادر الاحتراق الوظيفي","x":"الوعي بالعوامل التي تسبب التوتر ومراقبة أسلوب الحياة. إذا كان أسلوب حياتك يحتاج إلى تغيير، بادر الآن بإرادتك لتجنّب التغيير تحت الضغط لاحقًا."}]},{"t":"المرحلة المتوسطة من الاحتراق الوظيفي","src":"guide","pg":61,"key":"كتابة ملاحظات حول حالتك: متابعة تقدمك وتحديد النجاحات الصغيرة والاحتفال بها لتعزيز شعورك بالإنجاز والتحفيز.","items":[{"h":"إحداث التغييرات في بيئة العمل","x":"تحسين ظروف العمل مثل تقليل عبء العمل أو تحسين العلاقات مع الزملاء والمديرين، والتفاوض على مهام العمل وطلب المساعدة عند الحاجة."},{"h":"استشارة مدرب مهني بانتظام","x":"تطوير استراتيجيات للتعامل مع الاحتراق الوظيفي وتحسين توازن العمل والحياة."},{"h":"الاستفادة من كتب وقنوات المساعدة الذاتية","x":"الحصول على نصائح وأدوات مفيدة للتعامل مع التوتر والاحتراق الوظيفي."},{"h":"الدعم الاجتماعي","x":"الانضمام إلى مجموعات دعم يوفر بيئة آمنة لمشاركة التجارب والحصول على الدعم العاطفي والنصائح المفيدة."},{"h":"كتابة ملاحظات حول حالتك","x":"متابعة تقدمك وتحديد النجاحات الصغيرة والاحتفال بها لتعزيز شعورك بالإنجاز والتحفيز."}]},{"t":"المرحلة المتقدمة من الاحتراق الوظيفي","src":"guide","pg":62,"key":"استشارة طبيب نفسي: الحصول على العلاج المناسب إذا تطور الموضوع إلى اضطراب نفسي مصاحب.","items":[{"h":"استشارة مختص نفسي","x":"العلاج النفسي لتحسين صحتك النفسية عند ظهور علامات الاحتراق الأولية أو المتقدمة."},{"h":"العلاج المعرفي السلوكي (CBT)","x":"تغيير أنماط التفكير السلبية وتحسين التعامل مع الضغوط."},{"h":"العلاج الجماعي","x":"مشاركة التجارب والتعلم من الآخرين في بيئة داعمة."},{"h":"العلاج الإنساني","x":"التركيز على النمو الشخصي وتحقيق الذات."},{"h":"استشارة طبيب نفسي","x":"الحصول على العلاج المناسب إذا تطور الموضوع إلى اضطراب نفسي مصاحب."}]},{"t":"لتجنّب العودة إلى الاحتراق الوظيفي","src":"guide","pg":63,"key":"من المهم التمييز بين الاحتراق الوظيفي وعدم الرضا الوظيفي أو عدم الرضا عن أسلوب الحياة.","items":[{"h":"إذا كنت قد تعافيت أو في طريقك للتعافي، فقد يكون العمل الحالي غير مناسب لك. من المهم التمييز بين الاحتراق الوظيفي وعدم الرضا الوظيفي أو عدم الرضا عن أسلوب الحياة."},{"h":"تغيير الفريق أو موقع العمل يمكن أن يكون خطوة مفيدة إذا لزم الأمر. من الجيد مراجعة قوانين وأنظمة الشركة قبل قبول أي وظيفة جديدة، والبحث عن السياسات التي تعزّز صحتك النفسية واستقرارك العملي. تأكد من أن الشركة توفر بيئة عمل صحية وداعمة."},{"h":"كن نموذجًا يحتذى به في العمل من خلال مساعدة الآخرين الذين يعانون من المشكلة نفسها، ومشاركة طرقك في التعافي. هذا لا يساعد زملاءك فقط، بل يعزّز أيضًا من شعورك بالإنجاز والسعادة."},{"h":"لضمان عدم العودة إلى الاحتراق الوظيفي، يمكن استخدام مقاييس علمية لقياس علامات الاحتراق الوظيفي، مثل مقياس ماسلاك ومقياس دنبرا. هذه المقاييس تستخدمها الشركات والمنظمات لتحديد مدى انتشار هذه الظاهرة بين موظفيها، مما يساعد في اتخاذ الإجراءات الوقائية المناسبة."}]},{"t":"دور الأصدقاء والعائلة في الدعم الاجتماعي للمتأثر بالاحتراق الوظيفي","src":"guide","pg":63,"p":["يلعب الدعم الاجتماعي من الأصدقاء والعائلة دورًا حاسمًا في التخفيف من أعراض الاحتراق الوظيفي وتحسين الصحة النفسية بشكل عام."],"key":"الدعم الاجتماعي من الأصدقاء والعائلة ليس فقط مهمًا للصحة النفسية، بل هو أيضًا عنصر أساسي في الوقاية من الاحتراق الوظيفي.","items":[{"h":"الدعم العاطفي","x":"الاستماع والتعاطف من الأصدقاء والعائلة يساعد في تقليل الشعور بالوحدة والقلق، ويعزّز الشعور بالانتماء والتقدير، مما يحسّن الصحة النفسية ويزيد من الرضا الوظيفي."},{"h":"تقديم النصائح والإرشاد","x":"تقديم المشورة حول كيفية التعامل مع الضغوط والتحديات يساعد في تحسين القدرة على اتخاذ القرارات والتعامل مع المشكلات بشكل أكثر فعالية، مما يعزّز الأداء الوظيفي."},{"h":"المشاركة في الأنشطة الاجتماعية","x":"مثل الخروج مع الأصدقاء أو قضاء وقت مع العائلة يساعد في تحسين المزاج وتقليل مستويات التوتر من خلال التفاعل الاجتماعي الإيجابي، مما يقوي الروابط بين الأفراد ويعزّز الشعور بالانتماء."},{"h":"تقديم الدعم العملي","x":"مثل المساعدة في الأعمال المنزلية أو تقديم الدعم المالي عند الحاجة يقلّل من الأعباء اليومية ويساعد في التركيز على الصحة النفسية والجسدية، مما يعزّز الأداء الوظيفي."},{"h":"تعزيز الشعور بالانتماء","x":"العلاقات القوية والداعمة تعزّز الثقة بالنفس والشعور بالأمان، مما يقلّل من احتمالية الاحتراق الوظيفي ويزيد من الولاء المؤسسي."}]},{"t":"دور المعالج النفسي في مساعدة المتأثر بالاحتراق الوظيفي","src":"guide","pg":65,"key":"التقييم والتشخيص: يقوم المعالج النفسي بتقييم الحالة النفسية للمصاب وتحديد مدى تأثير الاحتراق النفسي عليه، مما يساعد في وضع خطة علاجية مناسبة.","items":[{"h":"التقييم والتشخيص","x":"يقوم المعالج النفسي بتقييم الحالة النفسية للمصاب وتحديد مدى تأثير الاحتراق النفسي عليه، مما يساعد في وضع خطة علاجية مناسبة."},{"h":"العلاج النفسي","x":"يشمل العلاج النفسي جلسات فردية أو جماعية لمناقشة المشاعر والأفكار السلبية والعمل على تغييرها. تقنيات مثل العلاج السلوكي المعرفي (CBT) تكون فعالة في هذا السياق."},{"h":"تطوير استراتيجيات التأقلم","x":"يساعد المعالج النفسي المصاب في تطوير استراتيجيات للتعامل مع الضغوط النفسية وتحسين مهارات إدارة الوقت والتنظيم."},{"h":"التوجيه والدعم","x":"يقدّم المعالج النفسي الدعم العاطفي والتوجيه للمصاب، مما يساعده على استعادة الثقة بالنفس والشعور بالتحسّن تدريجياً."},{"h":"التوعية والتعليم","x":"يقوم المعالج بتوعية المصاب حول الاحتراق النفسي وأسبابه وكيفية الوقاية منه في المستقبل، مما يساعد في تجنّب الانتكاسات."},{"h":"التواصل مع بيئة العمل","x":"في بعض الحالات، قد يتواصل المعالج النفسي مع بيئة العمل لتقديم توصيات حول تحسين ظروف العمل وتقليل الضغوط على الموظف."}]}],"strat":["face_burnout","root_cause","rebalance","no_perfection","stage_initial","stage_middle","stage_advanced","no_relapse","social_support","therapist"],"ev":[{"sid":"gaza2010","x":"وبصورة عامة، يوصى بإتباع الخطوات التالية: 1، 2، 3، 4، 5","th":1},{"sid":"gaza2010","x":"إن الكثير من الدراسات الأجنبية أظهرت أن التأمل و رياضات \"اليوجا\" تساعدان كثيرا في التغلب على الاحتراق الوظيفي، و على الرغم من أن المجتمعات الإسلامية لم تجر أبحاثا في هذا الجانب ولكني أعتقد أن التقرب إلى الله والمحافظة على الجوانب الدينية و الروحية له تأثير إيجابي في نفسية الأشخاص بشكل عام لأن الموظف المؤمن يكون دائم الحرص على أداء عمله بما يرضي ربه و ضميره لأنه يرى في عمله عبادة قبل أن يكون وسيلة لكسب الرزق أو تحقيق مكانة اجتماعية.","th":1}],"sort":{"t":"أي مرحلة؟","s":"صنّف كل تدخل في مرحلته من مراحل الاحتراق كما في الدليل.","bins":["المرحلة الأولية","المرحلة المتوسطة","المرحلة المتقدمة"],"items":[["الرعاية الذاتية",0],["الاستجمام",0],["استشارة مدرب مهني بانتظام",1],["كتابة ملاحظات حول حالتك",1],["العلاج المعرفي السلوكي",2],["العلاج الجماعي",2]]},"quiz":[{"q":"ما أول ما ينصح به الدليل عند ملاحظة علامات الاحتراق المبكرة؟","o":["الاعتراف بالمشكلة والتحدث إلى المسؤول","أخذ إجازة طويلة قبل مصارحة أي أحد","تغيير جهة العمل والبحث عن وظيفة جديدة","استشارة طبيب نفسي لتشخيص الحالة أولاً"],"src":"guide","why":"من المهم أولاً الاعتراف بوجود المشكلة والتحدث إلى رئيسك في العمل أو أي مسؤول آخر يمكنه المساعدة.","pg":59},{"q":"إلى أي ثلاث تغيرات يرجع الدليل حالة الاحتراق؟","o":["بيئة العمل، ونمط الحياة الشخصية، وأسلوب التفكير","الضغط، والدافع، والدعم من الزملاء والإدارة","البعد الفردي، والبعد المهني، والبعد الاجتماعي للموظف","النوم، والتغذية، والنشاط البدني المنتظم"],"src":"guide","why":"وتعود هذه الحالة إلى ثلاث تغيرات رئيسية هي: البيئة المحيطة، نمط الحياة الشخصية، وأسلوب التفكير.","pg":59},{"q":"هل الاحتراق الوظيفي مرض يحتاج إلى تشخيص طبي بحسب الدليل؟","o":["لا، لكنه قد يتطور إلى اضطرابات نفسية إن أُهمل","نعم، فهو اضطراب نفسي مصنف في الدليل التشخيصي للأطباء","لا، ولا يتطور إلى غيره مهما طال أمده أو اشتد","نعم، ويشخصه الطبيب أو المدير لا الموظف نفسه"],"src":"guide","why":"الاحتراق الوظيفي ليس مرضًا يحتاج إلى تشخيص طبي، لكنه يمكن أن يتطور إلى اضطرابات نفسية","pg":60},{"q":"أي مما يلي من دور الأصدقاء والعائلة في الدعم الاجتماعي؟","o":["الاستماع والتعاطف لتقليل الشعور بالوحدة","اتخاذ القرارات المهنية نيابة عن المتأثر دائماً","إخفاء المشكلة عنه حتى لا يزداد قلقه","حثّه على زيادة العمل لينسى ما يمر به"],"src":"guide","why":"الاستماع والتعاطف من الأصدقاء والعائلة يساعد في تقليل الشعور بالوحدة والقلق","pg":63},{"q":"ما الذي ينبغي التمييز بينه وبين الاحتراق لتجنب العودة إليه؟","o":["عدم الرضا الوظيفي أو عن أسلوب الحياة","الرغبة في التعلم أو تطوير المهارات","الحاجة إلى الإجازة أو الراحة الأسبوعية","العمل مع فريق جديد أو في موقع آخر"],"src":"guide","why":"من المهم التمييز بين الاحتراق الوظيفي وعدم الرضا الوظيفي أو عدم الرضا عن أسلوب الحياة.","pg":63}]},{"k":"org","t":"المنظمة والنجاح المهني","ic":"globe","q":"ما دور جهة العمل؟ وكيف تبقى مشتعلاً دون أن تحترق؟","sections":[{"t":"دور المنظمات في الحد من الاحتراق الوظيفي","src":"guide","pg":67,"p":["تلعب البرامج المؤسسية دورًا أساسيًا في دعم الموظفين لمواجهة الاحتراق الوظيفي، مما يحقّق فوائد كبيرة للمنظمات والعاملين. يبدأ هذا الدور بفهم سلوك الموظف المحترَق نفسيًا دون إصدار أحكام، مع التركيز على تقديم حلول عملية ومساعدات متنوعة. هذا النهج يساهم في خلق بيئة عمل إيجابية وداعمة، مما يساعد الموظفين على تجاوز مرحلة الاحتراق الوظيفي والعودة إلى أداء مهامهم بكفاءة وراحة نفسية. من خلال مجموعة متنوعة من البرامج والخدمات، يتم تعزيز رفاهية الموظفين وتحسين الأداء الوظيفي.","بهذه الطريقة يمكن للمنظمات أن تلعب دورًا فعالاً في الحد من الاحتراق الوظيفي وتحسين رفاهية الموظفين"],"key":"يبدأ هذا الدور بفهم سلوك الموظف المحترَق نفسيًا دون إصدار أحكام، مع التركيز على تقديم حلول عملية ومساعدات متنوعة.","items":[{"h":"برامج مساعدة الموظفين تقدّم استشارات سرية ودعمًا نفسيًا، مما يقلّل من مستويات التوتر ويحسّن الصحة النفسية، وينعكس إيجابيًا على الأداء الوظيفي."},{"h":"ورش العمل والتدريب تزوّد الموظفين بالأدوات والمهارات اللازمة لإدارة الضغوط والتوازن بين العمل والحياة، مما يقلّل من احتمالية الاحتراق الوظيفي."},{"h":"تعديل جداول العمل بتقديم خيارات مرنة مثل العمل عن بُعد أو ساعات العمل المرنة يساعد في تحقيق توازن أفضل بين الحياة الشخصية والمهنية، مما يقلّل من مستويات الإجهاد."},{"h":"تعزيز ثقافة الدعم والتعاون يخلق بيئة عمل إيجابية ويعزّز الشعور بالانتماء والدعم الاجتماعي، مما يحسّن العلاقات بين الموظفين."},{"h":"تقديم موارد الصحة النفسية مثل جلسات التأمّل واليوغا والاستشارات النفسية يحسّن الصحة النفسية ويقلّل من مستويات التوتر."},{"h":"التقدير والمكافآت يعزّز الشعور بالتقدير والانتماء، مما يقلّل من احتمالية الاحتراق الوظيفي ويزيد من الولاء المؤسسي."},{"h":"توفير بيئة عمل صحية من خلال مساحات عمل مريحة وإضاءة جيدة وتهوية مناسبة يقلّل من الإجهاد الجسدي والنفسي، مما يساهم في تحسين الأداء الوظيفي."},{"h":"التواصل المفتوح يعزّز الثقة والشفافية ويساعد في حل المشكلات بشكل أسرع وأكثر فعالية."},{"h":"التطوير المهني يوفّر فرصًا لاكتساب مهارات جديدة ويعزّز شعور الموظفين بالإنجاز والتقدّم."},{"h":"برامج العافية مثل الفحوصات الطبية الدورية والنصائح الغذائية وبرامج اللياقة البدنية تعزّز الصحة العامة للموظفين، مما يقلّل من معدلات الغياب ويحسّن الأداء العام."},{"h":"الاستشارات المالية تساعد الموظفين في إدارة أمورهم المالية بشكل أفضل، مما يقلّل من القلق المالي الذي يمكن أن يؤثر على الأداء الوظيفي والصحة النفسية."},{"h":"الأنشطة الاجتماعية تعزّز الروابط بين الموظفين وتحسّن العلاقات بينهم، مما يعزّز الشعور بالانتماء للمؤسسة."},{"h":"برامج الوقاية من الإجهاد من خلال التوعية والتدريب على تقنيات إدارة الضغوط تقلّل من احتمالية حدوث الاحتراق الوظيفي."},{"h":"تحسين بيئة العمل له تأثير إيجابي كبير على الإنتاجية، حيث تشير الدراسات إلى أن كل دولار تنفقه المنظمة لتحسين بيئة العمل يمكن أن يعود بأربعة أضعاف من حيث الإنتاجية، سواء من خلال زيادة الكفاءة أو تقليل استقالات الموظفين."},{"h":"في سوق عمل تنافسي، تعتبر بيئة العمل الجيدة ميزة أساسية لجذب المواهب، حيث يفضّل العديد من المبدعين والكفاءات العمل في شركات توفّر بيئة عمل ممتازة حتى لو كان الراتب أقل قليلاً مقارنة بشركات أخرى."},{"h":"تغيير جهة العمل ليس خطأً، بل هو أمر طبيعي في سوق العمل، حيث توجد أنظمة وقوانين تنظّم هذا الأمر، وقد تكون هناك فرص أفضل للموظف أو للمنظمة."},{"h":"الشغف في العمل مهم، لكنه قد يكون سلاحًا ذا حدين، حيث يكتشف الإنسان شغفه مع مرور الوقت في سوق العمل، ومن المهم أن يحب الإنسان عمله وأن تكون لديه ذهنية النمو والتعلّم من الأخطاء مع الحفاظ على صحة نفسية وبدنية جيدة."},{"h":"تعزيز ثقافة المنظمة يتطلّب زيادة الوعي واتخاذ التدابير الوقائية، بالإضافة إلى تدريب المسؤولين على إدارة الضغوطات وتعزيز صحة الموظفين."},{"h":"توفير بيئة آمنة نفسيًا يشجّع الموظفين على مشاركة أفكارهم دون خوف، ويساعد على تجنّب بيئات العمل التي تثير القلق من التسريح."},{"h":"تدخلات فعّالة على مستوى المنظمة يمكن أن تؤثر على عدد كبير من الموظفين، حيث يلعب القادة دورًا حيويًا في الحفاظ على رفاهية الموظفين."},{"h":"تقليل الضغوطات في بيئة العمل يتم من خلال تقليل التمايز والتنمّر، وتعزيز الروابط الاجتماعية بين الزملاء."},{"h":"احترام الوقت الشخصي للموظف يشمل تطبيق قاعدة 20/80 للمرونة في التعامل مع الأمور الملحّة خارج ساعات العمل، مع احترام الحياة الشخصية. قاعدة باريتو تُعبّر عن مبدأ أن 80% من النتائج تأتي من 20% من الأسباب أو المدخلات، بمعنى أن جزءًا صغيرًا من الجهد يمُكِن أن يُحدِث تأثيرًا كبيرًا على النتائج."},{"h":"الموازنة بين العمل والحياة الشخصية تتطلّب إيجاد توازن بين متطلّبات العمل وحقوق الموظف، مع مراعاة القوانين التي تمنع الاتصال بالموظف خارج ساعات العمل."},{"h":"استخدام التكنولوجيا لتحسين الصحة النفسية يمكن أن يشمل تطبيقات الذكاء الاصطناعي لتقييم مستوى الإرهاق وتحليل بيانات الموظفين بشكل استباقي."},{"h":"تعزيز الصحة النفسية الجماعية يتم من خلال مبادرات مثل جلسات توجيهية وورش عمل لرفع الوعي حول الاحتراق الوظيفي."},{"h":"تقديم الدعم النفسي والاستشارات يدفع للوصول إلى التوازن بين العمل والحياة من خلال سياسات العمل المرن والإجازات المدفوعة."},{"h":"تدريب المديرين على كيفية دعم فرقهم والتعرّف على علامات الاحتراق الوظيفي، والاعتراف بجهود الموظفين وتقديرها يعد أمرًا ضروريًا"},{"h":"وضع سياسات مرنة للمديرين تساعدهم على التكيّف مع الضغوط الشديدة، وضمان مكافآت للعاملين على جهودهم."},{"h":"التدوير بين الأقسام يخفّف الضغط، مع التأكيد على المساواة والعدالة."},{"h":"توفير أوقات وأماكن استراحة كافية، وإعادة ترتيب أولويات العمل بالتشاور مع العاملين، يعزّز من بيئة العمل الصحية."},{"h":"تعزيز قدرات العاملين يتم من خلال تمكين مشاركاتهم وتعزيز فرص الترقّي، وتوفير إجازات وعلاوات عادلة."},{"h":"إتاحة فرص التنقّل بين الأقسام تساعد على تخفيف حدة الضغط، وتوفير فرص النمو والترقيات"},{"h":"التكيّف مع المستجدات في نظم وأساليب العمل، ومساعدة الموظفين الجدد على الاندماج، يعزّز من استقرار بيئة العمل."},{"h":"المساواة بين العاملين والاستقرار في العمل يتطلب قياس وإدارة دورات العمل المرتفع."},{"h":"فهم الأنماط السلوكية للمحترقين، مثل العزلة لاستعادة الطاقة، والتمسّك بالمبادئ، وأخذ فترات من الاستراحة، وضبط النفس، يساعد في توفير بيئة داعمة، هذه البيئة تمكنهم من استعادة طاقتهم وتحليل المشاكل بشكل عقلاني، مما يعزّز قدرتهم على التعامل مع الضغوطات بشكل أفضل."},{"h":"التعامل مع ضعف الإنجاز يتطلّب الاهتمام بالصحة البدنية والنفسية، والتقليل من التوقعات."},{"h":"حل المشاكل من جذورها قد يتطلّب استشارة طبيب نفسي إذا لزم الأمر، وتحديد جدول زمني للمهام، والنقاشات المستمرة لإيصال الحقوق."}],"stats":[{"n":"4 أضعاف","x":"كل دولار تنفقه المنظمة لتحسين بيئة العمل يمكن أن يعود بأربعة أضعاف من حيث الإنتاجية","src":"تشير الدراسات، دون تسمية مصدر أو سنة في الدليل"},{"n":"80/20","x":"قاعدة باريتو: 80% من النتائج تأتي من 20% من الأسباب أو المدخلات","src":"قاعدة باريتو، كما وردت في الدليل دون مرجع"}]},{"t":"المبادرات الدولية في مواجهة الاحتراق الوظيفي","src":"guide","pg":72,"p":["تقدم الدول اليوم نفسها كنماذج حية للتغيير والتحول، من خلال تبني مجموعة من المبادرات الرائدة التي تهدف إلى تحسين بيئة العمل وتعزيز رفاهية الموظفين. هذه المبادرات ليست مجرد حلول مؤقتة، بل هي استراتيجيات مستدامة تسعى لضمان الشعور بالرضا والسعادة في بيئة العمل، وتحقق نتائج ملموسة في مواجهة الاحتراق الوظيفي. إليك أبرز هذه المبادرات:","هذه المبادرات تعكس التزام الدول بتحقيق بيئة عمل صحية ومستدامة، مما يقلّل من مستويات الاحتراق الوظيفي بين الموظفين ويعزّز من إنتاجيتهم ورفاهيتهم."],"key":"هذه المبادرات ليست مجرد حلول مؤقتة، بل هي استراتيجيات مستدامة تسعى لضمان الشعور بالرضا والسعادة في بيئة العمل","items":[{"h":"برامج الدعم النفسي","x":"توفّر الدول خدمات دعم نفسي واستشارات مجانية للموظفين لمساعدتهم في التعامل مع الضغوط النفسية والاحتراق الوظيفي.","grp":"تعزيز الصحة النفسية"},{"h":"زيادة الوعي","x":"تنظيم برامج تدريبية وورش عمل لزيادة الوعي بأهمية الصحة النفسية في مكان العمل.","grp":"تعزيز الصحة النفسية"},{"h":"المرونة في العمل","x":"تبني سياسات العمل المرن مثل العمل عن بُعد وساعات العمل المرنة، مما يساعد الموظفين على تحقيق توازن أفضل بين العمل والحياة الشخصية.","grp":"تحسين بيئة العمل"},{"h":"تصميم بيئة عمل صحية","x":"تحسين تصميم أماكن العمل لتكون أكثر راحة وصحية، بما في ذلك توفير مساحات للاسترخاء والراحة داخل مكان العمل.","grp":"تحسين بيئة العمل"},{"h":"التطبيقات الذكية","x":"تطوير تطبيقات تساعد الموظفين على إدارة وقتهم وضغوطهم بشكل أفضل، مثل تطبيقات التأمّل وإدارة الوقت.","grp":"استخدام التكنولوجيا"},{"h":"الذكاء الاصطناعي","x":"استخدام الذكاء الاصطناعي لتحليل بيانات الموظفين وتحديد علامات الاحتراق الوظيفي مبكرًا، مما يسمح باتخاذ إجراءات وقائية في الوقت المناسب.","grp":"استخدام التكنولوجيا"},{"h":"الواقع الافتراضي","x":"استخدام تقنيات الواقع الافتراضي لتقديم جلسات استرخاء وتأمّل للموظفين.","grp":"استخدام التكنولوجيا"},{"h":"القوانين والتشريعات","x":"وضع قوانين وتشريعات تحمي الموظفين من الضغوط المفرطة وتضمن حقوقهم في بيئة عمل صحية وآمنة.","grp":"السياسات التنظيمية"},{"h":"المسؤولية الاجتماعية","x":"تشجيع الشركات على تبنّي ممارسات المسؤولية الاجتماعية التي تركّز على رفاهية الموظفين وتقديم الدعم اللازم لهم.","grp":"السياسات التنظيمية"},{"h":"البحوث المستمرة","x":"زيادة الاستثمارات في الأبحاث والدراسات لفهم أفضل لأسباب الاحتراق الوظيفي وطرق الوقاية منه، مما يساعد في تطوير سياسات فعّالة لمكافحة هذه الظاهرة.","grp":"الأبحاث والدراسات"}]},{"t":"المبادرات المحلية لمواجهة الاحتراق الوظيفي","src":"guide","pg":75,"p":["هذه المبادرات تعكس التزام الشركات والمؤسسات المحلية بتحقيق بيئة عمل صحية ومستدامة، مما يقلّل من مستويات الاحتراق الوظيفي بين الموظفين ويعزّز من إنتاجيتهم ورفاهيتهم."],"key":"برنامج سفراء الصحة النفسية في بيئة العمل أطلقه المركز الوطني لتعزيز الصحة النفسية في المملكة العربية السعودية في عام 2021.","items":[{"h":"برنامج سفراء الصحة النفسية في بيئة العمل","x":"أطلقه المركز الوطني لتعزيز الصحة النفسية في المملكة العربية السعودية في عام 2021. يهدف البرنامج إلى نشر الوعي بالصحة النفسية في أماكن العمل وتقديم الدعم اللازم للموظفين.","grp":"برامج ومبادرات تعزيز الصحة النفسية"},{"h":"الخط الساخن للاستشارات النفسية","x":"على الرقم (920019393) تابع للهيئة السعودية للتخصصات الصحية، وهو مخصّص لدعم موظفي القطاع الصحي خلال أزمة كورونا، ولا يزال مستمراً في تقديم خدماته.","grp":"برامج ومبادرات تعزيز الصحة النفسية"},{"h":"برنامج المساعدة النفسية الأولية","x":"يقدّمه المركز الوطني لتعزيز الصحة النفسية، ويهدف إلى تقديم خدمات الدعم النفسي لجميع الأفراد في المجتمع وفي بيئات العمل أيضًا.","grp":"برامج ومبادرات تعزيز الصحة النفسية"},{"h":"جلسات استشارية مجانية","x":"تقدّم بعض الشركات الكبرى جلسات استشارية مجانية ودورات تدريبية على إدارة التوتر وضغوط العمل.","grp":"برامج ومبادرات تعزيز الصحة النفسية"},{"h":"العمل عن بُعد وساعات العمل المرنة","x":"تبنت العديد من الشركات هذه السياسات بعد جائحة كوفيد-19، مما ساعد في تقليل مستويات الاحتراق الوظيفي بين الموظفين.","grp":"سياسات العمل المرن"},{"h":"الاعتراف والتقدير","x":"تعزيز ثقافة الاعتراف بجهود الموظفين وتقديرها بشكل منتظم.","grp":"تعزيز ثقافة العمل الإيجابية"},{"h":"التوازن بين العمل والحياة","x":"تشجيع الموظفين على تحقيق توازن صحي بين العمل والحياة الشخصية من خلال سياسات داعمة.","grp":"تعزيز ثقافة العمل الإيجابية"}],"stats":[{"n":"2021","x":"إطلاق برنامج سفراء الصحة النفسية في بيئة العمل","src":"المركز الوطني لتعزيز الصحة النفسية، السعودية"}]},{"t":"بروتوكولات النجاح المهني","src":"guide","pg":78,"p":["تلعب بروتوكولات النجاح المهني دورًا حيويًا في مساعدتك على تحقيق النجاح وتجنّب الاحتراق الوظيفي، حيث تساهم في تعزيز الأداء المهني، تحسين جودة الحياة العملية، وتقليل الصدامات والتحديات، مع مراعاة الحقوق والواجبات وآداب التعامل."],"key":"زملاء العمل هم زملاء فقط، وليسوا أصدقاء.","items":[{"h":"نظّم وقتك ومواردك بشكل صحيح، واعرف حدودك واهتم باحتياجاتك الأساسية، وقم بمهمة واحدة في كل مرة وحدّد الأولويات."},{"h":"حافظ على علاقات طيبة ومحترمة في العمل، لا تجعل من كل زميل أو مدير عدوًا، وليس من الضروري أن يكونوا جميعًا أصدقاء مقربين، الأهم هو خلق بيئة عمل إيجابية ومثمرة."},{"h":"كن على طبيعتك في العمل، بغض النظر عن وضعك المالي أو الاجتماعي، وكن صادقًا مع نفسك ومع الآخرين."},{"h":"اعتنِ بنفسك كأولوية، افحص جسمك بانتظام وراقب مناطقك الضعيفة، وقم بمراجعة دورية لإنجازاتك وإخفاقاتك وحدد مشاكلك والتغييرات التي تحتاجها، وخذ استراحة أسبوعية كل ستة أسابيع لمنع الإرهاق، وافصل بين مهام العمل والحياة الشخصية، وجدّد روتينك اليومي، واحترم حدودك وقدراتك واعرف كيف تقول لا بإيجابية."},{"h":"اعمل بساعات مرنة أو بنظام العمل المختلط، وفوّض المهام التي يمكن للآخرين القيام بها، واستكشف فرصًا جديدة تناسبك في هذه المرحلة من حياتك المهنية."},{"h":"حياتك الشخصية تخصّك وحدك فلا تتحدّث عنها في العمل، وإذا كنت تعمل مع صديق يعرف عن حياتك الشخصية، فلتبقَ الصداقة خارج نطاق العمل."},{"h":"زملاء العمل هم زملاء فقط، وليسوا أصدقاء."},{"h":"أثبت نفسك وقدراتك في العمل ولا تقم بمهام ليست من مسؤولياتك. اعمل ما عليك بنسبة 100%، ولا تزيد أو تنقص. قل لا لأي مهام إضافية ليست من ضمن مسؤولياتك."},{"h":"ضع حدوداً للمزاح والكلام في العمل لتجنب المشاكل والحفاظ على التوازن."},{"h":"كن حازماً لا تكن دائمًا لطيفًا ومسالماً، حتى لا يتم استغلالك."}]},{"t":"نصائح لتحقيق النجاح المهني","src":"guide","pg":79,"p":["إليك بعض النصائح العملية لتحسين أدائك المهني والشخصي وتعزيز رفاهيتك في العمل. هذه النصائح ستساعدك على زيادة إنتاجيتك وتحقيق الرضا الوظيفي، بالإضافة إلى كسب رضا الآخرين عنك وعن أدائك."],"key":"فمستقبلك هو نتيجة استثمارك في نفسك، وليس صدفة أو حظًا.","items":[{"h":"ضع أهدافًا واقعية للسيطرة على حياتك ولا تنسَ مكافأة نفسك بعد الإنجاز."},{"h":"اهتم برفاهيتك الوظيفية من خلال تناول مشروبات منعشة، والاستماع إلى الموسيقى، ووضع أشياء جميلة على مكتبك، واحرص على تناول وجبات صحية وممارسة الرياضة بانتظام لتحسين حالتك النفسية والجسدية. استرخِ واسترح أثناء العمل، وشارك في أنشطة ترفيهية خلال الإجازات لتجديد طاقتك."},{"h":"استحضر دائمًا ما يجعلك سعيدًا مثل عائلتك، أصدقائك، حيوانك الأليف، أو أي موقف شعرت فيه بالسعادة، هذا يساعدك على التغلب على التفكير السلبي والاحتراق الوظيفي."},{"h":"خذ استراحة أسبوعية كل ستة أسابيع لمنع الإرهاق، وافصل بين مهام العمل والحياة الشخصية، وجدد روتينك اليومي."},{"h":"اكتشف ما تريده وأخبر الناس بما تحتاجه."},{"h":"النجاح يأتي بالمثابرة والإصرار وتوفيق من الله، اجتهد لتحصل على نصيبك من النجاح، فمستقبلك هو نتيجة استثمارك في نفسك، وليس صدفة أو حظًا."},{"h":"تجنّب مرافقة الأشخاص السلبيين والنمّامين والمتسلّقين فهم يستنزفون طاقتك."},{"h":"لا تضيّع وقتك في جدالات عقيمة لإثبات وجهة نظرك."},{"h":"لا تصرّ على الخطأ بل اعترف به وتعلم منه."},{"h":"لا تقارن نفسك بالآخرين فلكل شخص رحلته الخاصة."},{"h":"لا تتعالَ على غيرك، ولا تغترّ بنفسك، ولا تحتقر الآخرين."},{"h":"لا تسأل أحدًا عن رأيه فيما تنجز، فلكل شخص أجندته الخاصة."},{"h":"حافظ على حدود واضحة واحترم خصوصية الآخرين."},{"h":"احرص على قوة أدائك، ودفء تعاملك، وحضور شخصيتك في العمل."},{"h":"احرص على ضبط نفسك في الكلام والتصرّفات والرغبات."}]},{"t":"المهارات الأساسية للنجاح المهني","src":"guide","pg":81,"p":["النجاح المهني ليس مجرّد حظ، بل هو نتيجة لتطوير مجموعة من المهارات التي يمكن اكتسابها والتدرّب عليها باستخدام استراتيجيات وفنيات محددة. هذا يتيح لك فرصة لتحديد نقاط الضعف والعمل على تقويتها. كل مهارة يمكن اكتسابها وتطويرها مع الوقت والممارسة، ولتعلّم مهارات جديدة يجب أولاً تصفية الذهن. إليك بعض المهارات الوقائية والعلاجية المهمة في بيئة العمل للتقدّم المهني، ويمكنك الاستزادة حولها من مصادر التعلم المختلفة."],"key":"النجاح المهني ليس مجرّد حظ، بل هو نتيجة لتطوير مجموعة من المهارات التي يمكن اكتسابها والتدرّب عليها باستخدام استراتيجيات وفنيات محددة.","items":[{"h":"التواصل الفعّال","x":"يمكّنك التواصل الفعّال من بناء علاقات مهنية قوية وتجنب سوء الفهم، إذ يشمل القدرة على الاستماع الجيد، التعبير الواضح، واستخدام لغة الجسد بشكل مناسب. إتقان هذه المهارة يعزز التعاون في العمل ويزيد من الإنتاجية، مما يساهم في خلق بيئة عمل إيجابية.","grp":"المهارات الشخصية"},{"h":"الذكاء العاطفي","x":"يمكنك الذكاء العاطفي من فهم مشاعرك ومشاعر الآخرين وإدارتها بطريقة إيجابية، إذ يتضمن التعاطف وضبط النفس والوعي الذاتي. تعزز هذه المهارة التفاعلات مع الزملاء والعملاء، مما يخلق مناخ عمل إيجابي ويزيد من الرضا الوظيفي، وبالتالي يساعدك في التحكم بالتوتر وإدارة الصراعات بفعالية.","grp":"المهارات الشخصية"},{"h":"توكيد الذات","x":"يمكنك توكيد الذات من التعبير عن أفكارك ومشاعرك بثقة واحترام، دون التوجه نحو العدوانية أو الخضوع، وذلك من خلال تطوير مهارات التفاوض والتواصل الصريح. تساعدك هذه المهارة على الحفاظ على حقوقك وبناء احترام متبادل مع الآخرين، مما يعزز الثقة بالنفس ويزيد من الرضا الوظيفي ويحميك من استنزاف الطاقة والشعور بالاستغلال.","grp":"المهارات الشخصية"},{"h":"اليقظة الذهنية","x":"تمكّنك اليقظة الذهنية من التركيز الكامل على اللحظة الحالية، مما يحسن الأداء ويقلل التشتت، من خلال استخدام تقنيات مثل التأمل والتنفس العميق والانتباه الواعي. تساعدك هذه المهارة في زيادة التركيز والإنتاجية وتقليل التوتر والقلق، مما يساهم في تحقيق شعور الرضا والهدوء النفسي.","grp":"المهارات الشخصية"},{"h":"إدارة الوقت","x":"تمكّنك إدارة الوقت من تنظيم المهام وتحديد الأولويات بشكل يساهم في تجنب الإرهاق وتحقيق التوازن بين العمل والحياة الشخصية. تشمل هذه المهارة تحديد الأهداف، وضع جداول زمنية، واستخدام أدوات إدارة الوقت بفعالية. من خلال إدارة الوقت بشكل جيد، يمكنك تحقيق أهدافك بكفاءة وتقليل التوتر الناتج عن ضغط العمل.","grp":"المهارات الحياتية"},{"h":"حل المشكلات","x":"تمكّنك مهارة حل المشكلات من تحليل المشكلات بفعالية والتفكير النقدي لإيجاد حلول مبتكرة. تشمل هذه المهارة القدرة على التعرف على المشكلات، تحليل الأسباب، ووضع استراتيجيات لحلها. تساعدك هذه المهارة في التعامل مع التحديات بشكل إيجابي واتخاذ قرارات مبنية على تحليل منطقي، مما يعزز من قدرتك على النجاح في بيئة العمل.","grp":"المهارات الحياتية"},{"h":"التكيّف","x":"تمكّنك مهارة التكيف من التعامل مع التغييرات والضغوط بشكل إيجابي، مما يساعدك على البقاء مرناً ومنضبطاً. تشمل هذه المهارة القدرة على التكيف مع ظروف العمل المتغيرة، الاستجابة بسرعة للمستجدات، والحفاظ على الهدوء تحت الضغوط. من خلال التكيف، يمكنك مواجهة التحديات بثقة والاستمرار في تحقيق أهدافك بكفاءة.","grp":"المهارات الحياتية"},{"h":"التخصّص الفني","x":"يمكنك التخصص الفني من التعمق في المعرفة والمهارات الفنية المطلوبة لأداء مهام معينة بكفاءة. يتضمن ذلك الإلمام بالأدوات والتقنيات الخاصة بالمجال والتدرب على استخدامها بفعالية. ومن خلال التخصص الفني، يمكنك تحسين أدائك وزيادة إنتاجيتك، مما يساهم في تحقيق النجاح والتطور في مجالك.","grp":"المهارات المهنية"},{"h":"التفكير النقدي","x":"يمكنك التفكير النقدي من تحليل وتقييم المعلومات بفعالية لاتخاذ قرارات مستنيرة. يشمل هذا القدرة على التفكير بموضوعية واستخدام الأدلة والشواهد لتدعيم آرائك. وبفضل التفكير النقدي، يمكنك اتخاذ قرارات أكثر دقة وفعالية، مما يعزز قدرتك على التعامل مع التحديات وحل المشكلات بشكل مبتكر.","grp":"المهارات المهنية"},{"h":"التعلم المستمر","x":"يمكنك التعلم المستمر من السعي الدائم لاكتساب مهارات ومعارف جديدة لمواكبة التطورات في مجال العمل. يتضمن ذلك الالتزام بالتعلم الذاتي وحضور ورش العمل والدورات التدريبية. ومن خلال التعلم المستمر، يمكنك تحسين كفاءتك المهنية والبقاء على اطلاع بأحدث التطورات، مما يزيد من فرصك في النجاح والتقدم الوظيفي.","grp":"المهارات المهنية"},{"h":"اتخاذ القرارات","x":"تمكنك من القدرة على اتخاذ قرارات فعالة بناءً على تحليل دقيق للمعلومات المتاحة. يشمل هذا تقييم الخيارات المختلفة، واختيار الحلول الأفضل بناءً على الأدلة والبيانات المتوفرة. ومن خلال اتخاذ القرارات الحكيمة، يمكنك تحسين الأداء العام وتحقيق النتائج المرجوة بكفاءة.","grp":"المهارات القيادية"},{"h":"التحفيز","x":"يمكنك التحفيز من القدرة على تحفيز الآخرين لتحقيق الأهداف المشتركة. يشمل هذا استخدام أساليب التشجيع والتوجيه، وتقديم الدعم اللازم للزملاء. من خلال التحفيز الفعال، يمكنك تعزيز الروح المعنوية وزيادة الإنتاجية، مما يسهم في تحقيق الأهداف الجماعية بكفاءة.","grp":"المهارات القيادية"},{"h":"إدارة النزاعات","x":"تمكنك من التعامل مع النزاعات بشكل بناء لتجنب التصعيد وتعزيز التعاون. يشمل هذا فهم أسباب النزاعات، واستخدام أساليب التواصل الفعّال والتفاوض لحل المشكلات. ومن خلال إدارة النزاعات بشكل جيد، يمكنك خلق بيئة عمل إيجابية تعزز من التعاون وتحقيق الأهداف المشتركة.","grp":"المهارات القيادية"},{"h":"التفويض","x":"يمكنك التفويض من توزيع المهام والمسؤوليات بفعالية لضمان تحقيق الأهداف بكفاءة. يشمل هذا تحديد المهام المناسبة لكل فرد وتقديم الإرشادات اللازمة لتنفيذها. ومن خلال التفويض الفعّال، يمكنك تحسين توزيع العمل وزيادة الإنتاجية، مما يساهم في تحقيق الأهداف بكفاءة.","grp":"المهارات القيادية"},{"h":"استخدام التكنولوجيا","x":"يمكنك استخدام التكنولوجيا من القدرة على استخدام الأدوات والتقنيات الحديثة بكفاءة. يشمل هذا تعلم كيفية استخدام البرمجيات والأجهزة المتقدمة لتنفيذ المهام بشكل أسرع وأكثر دقة. ومن خلال إتقان التكنولوجيا، يمكنك تحسين أدائك وزيادة إنتاجيتك، مما يساهم في تحقيق النجاح في بيئة العمل العصرية.","grp":"المهارات الرقمية"},{"h":"تحليل البيانات","x":"يمكنك تحليل البيانات من القدرة على تحليل وتفسير البيانات لاتخاذ قرارات مستنيرة. يشمل هذا القدرة على جمع البيانات، وتنظيمها، وتحليلها لاستخلاص النتائج. ومن خلال تحليل البيانات بفعالية، يمكنك اتخاذ قرارات أكثر دقة وفعالية، مما يعزز من قدرتك على تحقيق الأهداف الاستراتيجية.","grp":"المهارات الرقمية"},{"h":"الأمان السيبراني","x":"يمكنك الأمن السيبراني من حماية المعلومات والأنظمة من التهديدات الرقمية. يتضمن هذا التعرف على المخاطر الأمنية واتخاذ التدابير اللازمة لحماية البيانات والشبكات. ومن خلال الأمان السيبراني، يمكنك ضمان سلامة المعلومات والحفاظ على استمرارية العمل دون التعرض للاختراقات الأمنية.","grp":"المهارات الرقمية"}]},{"t":"خاتمة","src":"guide","pg":86,"p":["يُعَدُّ الاحتراق الوظيفي ظاهرةً متزايدةً في بيئات العمل الحديثة، تتطلّب اهتمامًا جادًا من قِبَل الأفراد والمنظمات على حدٍّ سواء. إنَّ فهم أسباب الاحتراق الوظيفي وآثاره السلبية على الصحة النفسية والجسدية للعاملين يُمكِّننا من تطوير استراتيجيات فعّالة للوقاية منه ومعالجته.","من خلال تعزيز بيئات عمل داعمة، يمكن للمنظمات توفير بيئة عمل تشجّع على التعاون والتواصل المفتوح بين الموظفين والإدارة. هذا يشمل تقديم برامج تدريبية تهدف إلى تطوير مهارات التعامل مع الضغوط وإدارة الوقت بشكل فعّال.","توفير الدعم النفسي هو عنصر أساسي آخر، حيث يمكن للمنظمات تقديم خدمات استشارية نفسية للموظفين، بالإضافة إلى تنظيم ورش عمل حول الصحة النفسية والرفاهية، هذه الخطوات تساعد في تقليل مستويات التوتر وتعزيز الصحة النفسية للعاملين.","تشجيع التوازن بين الحياة المهنية والشخصية يُعَدُّ أيضًا من العوامل المهمة في مكافحة الاحتراق الوظيفي. يمكن تحقيق ذلك من خلال سياسات مرنة للعمل، مثل العمل عن بُعد أو ساعات العمل المرنة، مما يسمح للموظفين بإدارة وقتهم بشكل أفضل وتخصيص وقت كافٍ للراحة والأنشطة الشخصية.","لذا، يجب أن تكون الجهود المشتركة بين الموظفين وأرباب العمل مستمرة لضمان بيئة عمل صحية ومستدامة، كما يجب على المنظمات تبنّي سياسات وإجراءات تدعم رفاهية الموظفين وتقلّل من عوامل الضغط المهني، مثل تقليل ساعات العمل الزائدة وتوفير فرص للتطوير المهني.","في النهاية، من خلال هذه الجهود المتكاملة، يمكننا تقليل معدلات الاحتراق الوظيفي وتحسين جودة الحياة العملية، مما ينعكس إيجابًا على الإنتاجية والرضا الوظيفي."],"key":"يجب أن تكون الجهود المشتركة بين الموظفين وأرباب العمل مستمرة لضمان بيئة عمل صحية ومستدامة"}],"strat":["success_protocols","assertive","mindful","emo_intel"],"ev":[{"sid":"gaza2010","x":"أظهر المبحوثين قبولا لمستوى الصلاحيات الممنوحة لهم، حيث إن المستويات الإدارية المبحوثة هنا ليست مستويات أخذ قرار و عليه يشعر الموظفين المبحوثين بأن الصلاحيات الممنوحة لهم بموجب اللوائح و القوانين الحكومية كافية."},{"sid":"gaza2010","x":"أظهر المبحوثين عدم رضا عن نظام التعزيز و الحوافز بمختلف أشكالها المتبعة في الوزارة."},{"sid":"syria","x":"المقابلات مع الإدارات أوضحت وجود جو من سوء التخطيط في بعض الإدارات مما يؤدي إلى الاحتراق الوظيفي لدى العاملين مع ضغوط العمل، والمهام، والمهام الطارئة"},{"sid":"syria","x":"أكد المدراء وجود المهام الطويلة والمفاجئة، والتقارير المطوّلة، والبيئة البيروقراطية مع هزالة التخطيط التي تؤدي إلى تجاوز الأوقات المحددة لإنهاء المهام، مما يزيد الضغط أكثر على الموظفين لإنهاء المهام، وانخفاض جودة العمل، وقلة الرغبة في العمل، وللأسف لا يوجد أي حلول من قبلهم، حسب الإدارة. (خلاصة المقابلات مع 6 إداريين)"},{"sid":"jeddah","x":"العنصر البشري هو عجلة الدفع الموجودة داخل أي منظمة خدمية بالطبع لأنه هو عنصر الإنتاج المتاح بها والقائم عليه نجاح تلك المنظمة من عدمه وبالنظر إلى التطور والترابط التكنولوجي الذي نعاصره نرى أننا بصدد الحصول دائماً على طاقات بشرية ذات قدرات خاصة على مواكبة هذا التطور ومزامنة العمل مع ما يحتاجه للوصول بتلك المنشأة لدرجة النجاح المنشودة، وإذا كان العنصر البشري هو حجر الأساس الذي تقوم عليه تلك المنشأة كان الاهتمام بتوفير كل وسائل العناية والراحة هو واحد من أهم الأمور التي يجب أن تحرص عليها تلك المنشأة بالطبع إلا أنه ومع ذلك نجد أن هناك عدد لا بأس به من تلك القوة البشرية تعاني من الضغط النفسي ويواجهون العديد من الأثار السلبية لما يسمى بالاحتراق الوظيفي.","th":1}],"match":{"t":"مهارات النجاح المهني","s":"صل كل مهارة بمجموعتها كما في الدليل.","l":"المهارة","r":"المجموعة","pairs":[["التواصل الفعّال","المهارات الشخصية"],["حل المشكلات","المهارات الحياتية"],["التفكير النقدي","المهارات المهنية"],["التفويض","المهارات القيادية"],["تحليل البيانات","المهارات الرقمية"]]},"quiz":[{"q":"بماذا يبدأ دور المنظمات في الحد من الاحتراق بحسب الدليل؟","o":["بفهم سلوك الموظف المحترق دون إصدار أحكام","بقياس انتشار الظاهرة بين موظفيها بمقياس ماسلاك","بتدريب المديرين على رصد علامات الاحتراق المبكرة","بتقديم المكافآت لتعزيز الولاء المؤسسي"],"src":"guide","why":"يبدأ هذا الدور بفهم سلوك الموظف المحترَق نفسيًا دون إصدار أحكام","pg":67},{"q":"أي مما يلي من وسائل المنظمة للحد من الاحتراق في الدليل؟","o":["تعديل جداول العمل بخيارات مرنة","ربط الأجر بعدد ساعات العمل الإضافية","تقليص عدد الموظفين لتوزيع الأعباء","منع التنقل بين الأقسام للاستقرار"],"src":"guide","why":"تعديل جداول العمل بتقديم خيارات مرنة مثل العمل عن بُعد أو ساعات العمل المرنة","pg":67},{"q":"بحسب نصائح النجاح المهني في الدليل، كل كم أسبوعاً يُنصح باستراحة لمنع الإرهاق؟","o":["كل ستة أسابيع","كل أربعة أسابيع","كل ثلاثة أشهر","كل ثمانية أسابيع"],"src":"guide","why":"خذ استراحة أسبوعية كل ستة أسابيع لمنع الإرهاق","pg":79},{"q":"في دراسة سورية، ما الذي أكده المدراء في المقابلات؟","o":["المهام المفاجئة والبيروقراطية مع ضعف التخطيط","أن أداء العاملين بقي عالي الجودة رغم الضغوط","أن الإدارة وضعت حلولاً فعالة للحد من الضغوط","أن الرواتب المنخفضة هي السبب الرئيس للضغط"],"src":"guide","why":"أكد المدراء وجود المهام الطويلة والمفاجئة، والتقارير المطوّلة، والبيئة البيروقراطية مع هزالة التخطيط"},{"q":"في دراسة غزة، عن أي شيء أظهر الموظفون عدم رضا؟","o":["نظام التعزيز والحوافز","مستوى الصلاحيات الممنوحة","العلاقات الاجتماعية","وضوح الأعمال الإدارية"],"src":"guide","why":"أظهر المبحوثين عدم رضا عن نظام التعزيز و الحوافز بمختلف أشكالها المتبعة في الوزارة."},{"q":"ما خلاصة خاتمة الدليل؟","o":["استمرار الجهود المشتركة للموظفين وأرباب العمل","تحميل المنظمة وحدها مسؤولية الحد من الاحتراق","أن التعافي مسؤولية الموظف وحده دون المنظمة","الاكتفاء بالمبادرات الحكومية والتشريعات الدولية"],"src":"guide","why":"يجب أن تكون الجهود المشتركة بين الموظفين وأرباب العمل مستمرة لضمان بيئة عمل صحية ومستدامة","pg":86}]}],"check":{"intro":"خلال الأسابيع الماضية، كم مرة لاحظت في نفسك هذه المؤشرات؟ اختر لكل مؤشر: نادراً، أو أحياناً، أو غالباً. المؤشرات منقولة من الدليل، وكلها تخصك وحدك.","note":"هذه مراجعة ذاتية من مؤشرات الدليل وأعراضه، تساعدك على الانتباه والوقاية، ولا تغني عن مختص. وإن كانت الأعراض تؤثر في قدرتك على أداء مهامك اليومية في المنزل أو العمل، فالدليل ينصح بالبحث عن مساعدة مختص.","groups":[{"t":"المؤشرات المنذرة","ic":"flag","items":["الانشغال الدائم والاستعجال في إنهاء المهام اليومية","تأجيل الأنشطة الاجتماعية والترفيهية بسبب الانشغال","العيش وفق قاعدة «يجب» و«ينبغي»","الانغماس في العمل بشكل مفرط","النزعة الكمالية، فأرى كل شيء مهماً وعاجلاً"]},{"t":"علامات جسدية","ic":"bat","items":["قلة النوم المصحوبة بإرهاق مستمر","الشعور المستمر بالإنهاك والتعب","الصداع المتكرر","الشد العضلي","مشاكل في الظهر والرقبة","تغيرات في الشهية"]},{"t":"علامات نفسية","ic":"heart","items":["فقدان الدافعية والشغف","الإرهاق العاطفي","الشعور الدائم بالضغط","عدم الاكتراث بالعمل","تقلبات مزاجية مثل الغضب والحزن","ضعف التركيز","فقدان الابتكار والروح الإبداعية"]},{"t":"علامات سلوكية","ic":"users","items":["تأجيل المسؤوليات أو تأخير الأعمال الهامة","الانسحاب من المسؤوليات والاجتماعيات","الانفعال السريع حتى في المواقف البسيطة","تغييرات في عادات النوم","التذمر المستمر من العمل","فقدان الاهتمام بالأنشطة والهوايات التي كانت تمنحني المتعة","كثرة الحديث عن التقاعد هروباً من ضغوط العمل"]}],"levels":[{"t":"إشاراتك قليلة","x":"هذا مطمئن. حافظ على ما يحميك: التوازن بين العمل والحياة، والنوم الجيد، والعلاقات الطيبة. وعد إلى هذه المؤشرات بين حين وآخر، فالدليل يذكّر بأن الاحتراق يبدأ بشكل غير ملحوظ."},{"t":"بعض الإشارات تتكرر","x":"هذا وقت مناسب للوقاية قبل أن تشتد. اقرأ محطة الوقاية، واختر في «خطتي» استراتيجية أو اثنتين، وابدأ بخطوة صغيرة هذا الأسبوع. والتحدث مع شخص تثق به يخفف كثيراً."},{"t":"إشارات كثيرة تتكرر","x":"هذه ليست نتيجة تشخيص، لكنها تستحق اهتمامك الآن. تحدث مع شخص تثق به، وناقش أعباءك مع مسؤولك، واطلب استشارة مختص نفسي، فالدليل يؤكد دور المعالج النفسي في التقييم ووضع خطة مناسبة. وابدأ بمحطة التعافي."}],"go":[[4,"محطة الوقاية"],[5,"محطة التعافي"]]},"strategies":[{"id":"self_know","kind":"prevent","t":"فهم الذات","why":"فهم سماتك الشخصية يساعدك على تحديد ما إذا كان العمل يدفعك للعطاء المتوازن أو يتجاوز طاقتك، مما يجعلك عرضة للاحتراق إذا لم تستعد طاقتك بالراحة والاستمتاع.","steps":["فهم سماتك الشخصية يساعدك على تحديد ما إذا كان العمل يدفعك للعطاء المتوازن أو يتجاوز طاقتك","العمل في مجال تستمتع به وترى فيه قيمة معنوية وروحية يمكن أن يقلل من احتمالية الاحتراق الوظيفي","فهم أهدافك يساعدك على توجيه طاقتك بشكل متوازن واستعادة نشاطك من خلال الراحة والاستمتاع.","فهم الذات يساعدك على وضع أهداف واقعية وقابلة للتحقيق في العمل، مما يقلّل من الشعور بالإحباط والضغط.","كما يعزّز تطوير مهارات حياتية مهمة مثل المرونة النفسية، وتوكيد الذات، والذكاء العاطفي، واليقظة الذهنية، وإدارة الضغوط، وإدارة الوقت، وحل المشكلات."],"pg":45},{"id":"know_others","kind":"prevent","t":"فهم الآخرين","why":"معرفة سمات الشخصيات المحيطة بك يمكن أن يساعدك في تحسين التعامل معهم بشكل أفضل.","steps":["تحسين التعامل مع المدراء، بما في ذلك التحدث حول تخفيف الأعباء عند الحاجة والاستفسار عن المهام غير الواضحة ومناقشة التوقّعات.","التركيز على الجوانب الإيجابية في العمل ومناقشة الصعوبات مع الزملاء.","تقليل التوقعات الخاصة بالعمل والإدارة لمواجهة التحديات الضاغطة، مع ضرورة الاستراحة وضبط النفس.","تغيير بيئة العمل إذا لزم الأمر، سواء بالانتقال إلى قسم آخر أو البحث عن وظيفة جديدة.","فهم طبيعة الزملاء وطلب الدعم منهم في تنظيم وإعداد المهام."],"pg":46},{"id":"higher_values","kind":"prevent","t":"ربط الإنجاز بقيم عليا","why":"ربط الإنجاز بقيم متعددة يساعد الموظف على تعويض ضعف إحدى القيم بقيمة أخرى، مما يقلّل من خطر الاحتراق النفسي ويعزّز الشعور بالرضا والاستمرارية في العمل.","steps":["يجب أن نجد في عملنا قيمة تعزّز من دوافعنا للإنجاز. يمكن أن يكون للعمل دور كبير في مساعدة المجتمع، وتسهيل حياة الناس، أو تقديم فوائد مثل التعليم، أو العلاج، أو حفظ الأمن.","التعامل مع الرغبة في الإنجاز بلغة هادئة ومطمئنة يساعد في تقليل التوتر","ربط الإنجاز برضا الله سبحانه وتعالى يعزّز الدافع الداخلي، مما يساعد على تحقيق الأهداف بروح إيجابية ومستدامة."],"pg":46},{"id":"clear_limits","kind":"prevent","t":"وضع حدود واضحة","why":"وزّع العمل واطلب المساعدة لتجنّب الإرهاق.","steps":["حدد أوقاتًا محددة للعمل وأخرى للراحة والأنشطة الشخصية، والتزم بها.","اعمل بحدود طاقتك وتجنّب الساعات المفتوحة.","وزّع العمل واطلب المساعدة لتجنّب الإرهاق.","بعد انتهاء ساعات العمل، اترك المهام المتبقية لليوم التالي واسترح."],"pg":47},{"id":"priorities","kind":"prevent","t":"ترتيب الأولويات (مصفوفة آيزنهاور)","why":"إنجاز العديد من المهام في وقت واحد يؤدي إلى الإجهاد وقلّة الإنتاجية.","steps":["حدد أهدافًا واضحة وقابلة للقياس، واستخدم قوائم المهام لتقليل الضغط النفسي.","صنّف المهام حسب الأهمية والإلحاح باستخدام مصفوفة آيزنهاور.","كما قال الباحث جيم كولينز: إذا كان لديك أكثر من ثلاث أولويات، فليس لديك أولويات.","من المهم مناقشة هذه الأولويات مع المسؤول لضمان التركيز على المهام الأكثر أهمية وتحقيق أفضل النتائج."],"pg":48},{"id":"time_alloc","kind":"prevent","t":"تخصيص الوقت","why":"لتكتشف مدى توازنك في توزيع وقتك.","steps":["استخدم جداول زمنية أو تطبيقات إدارة الوقت.","دوّن أنشطتك اليومية ومدة كل منها لتكتشف مدى توازنك في توزيع وقتك.","حدّد أوقاتًا محددة للتحقق من البريد الإلكتروني ووسائل التواصل الاجتماعي لتجنّب التشتت."],"pg":48},{"id":"tech_tools","kind":"prevent","t":"الاستفادة من التكنولوجيا","why":"تطبيقات تحديد الأولويات تضمن أنك تبقى على المسار الصحيح.","steps":["استخدم أدوات مثل التقويمات الرقمية لتخطيط مواعيدك، وتطبيقات المهام لتتبع تقدمك وإنجازاتك.","برامج إدارة المشاريع تساعد في تنسيق العمل مع فريقك، بينما تطبيقات تحديد الأولويات تضمن أنك تبقى على المسار الصحيح."],"pg":48},{"id":"short_breaks","kind":"prevent","t":"أخذ استراحات قصيرة","why":"من المهم أخذ استراحات قصيرة والقيام بتمارين الاسترخاء.","steps":["القيام بتمارين الاسترخاء.","يُنصح بالحصول على فترات راحة منتظمة خلال اليوم أو إجازات أطول للاستجمام."],"pg":49},{"id":"pomodoro","kind":"prevent","t":"تقنية بومودورو","why":"لزيادة التركيز والإنتاجية وتقليل التوتر.","steps":["قسّم العمل إلى فترات قصيرة (25 دقيقة)","تتبعها فترات راحة قصيرة (5 دقائق).","بعد أربع فترات عمل، خذ استراحة أطول (15-30 دقيقة)"],"pg":49},{"id":"sleep","kind":"prevent","t":"النوم الجيد","why":"الحفاظ على جودة النوم يعزز الأداء والإنتاجية، ويحسن الذاكرة والتركيز، ويقلّل من الإجهاد.","steps":["الشخص البالغ قد يحتاج إلى النوم من 6 إلى 8 ساعات يوميًا، مع إمكانية إضافة ساعة قيلولة","يجب أن يكون النوم في ساعات منتظمة لتجنّب اضطرابات النوم","ممارسة تمارين الاسترخاء مثل التنفس العميق","إنشاء روتين ثابت للنوم يتضمن أنشطة مريحة قبل النوم","وإذا استمرت مشكلات النوم، يُفضّل استشارة مختص في العلاج المعرفي السلوكي."],"pg":51},{"id":"nutrition","kind":"prevent","t":"التغذية السليمة","why":"تلعب التغذية الصحية دورًا كبيرًا في تحسين الصحة العامة وتقليل الإجهاد.","steps":["لتقليل التوتر، يُنصح بتناول الأطعمة الغنية بالأوميغا-3، والكربوهيدرات المعقّدة، والمغنيسيوم، والأطعمة المخمرة","تجنّب الأطعمة المعالجة والمشروبات المحلّاة بالسكر، بالإضافة إلى تجنّب التدخين والكحول.","شرب الماء بانتظام يحسن التركيز ويخفف التعب","لا تأكل وتنام مباشرة، بل نم واستيقظ ثم تناول الطعام.","تناول وجبات غذائية متوازنة تحتوي على جميع العناصر الغذائية الضرورية، وتجنّب الأطعمة السريعة والمشروبات الغازية."],"pg":51},{"id":"exercise","kind":"prevent","t":"الأنشطة الرياضية","why":"للرياضة تأثير كبير على الصحة النفسية، حيث تساهم في تحسين المزاج وزيادة الطاقة وتقليل الإجهاد","steps":["ممارسة 150 دقيقة من النشاط البدني أسبوعيًا، موزعة على 3-4 مرات في الأسبوع، كل مرة لمدة 30-40 دقيقة.","يجب أن يكون النشاط مكثّفًا بما يكفي لزيادة معدل ضربات القلب، مثل تمارين الكارديو، وأبسطها المشي","يُنصح بممارسة الأنشطة الفردية مرتين في الأسبوع والأنشطة الجماعية مرة واحدة على الأقل."],"pg":52},{"id":"career","kind":"prevent","t":"المهنة","why":"وتذكر أن حوالي 16 ساعة من يومك تذهب في العمل والنوم.","steps":["اختر مهنة تحبها وتحقّق لك دخلاً جيدًا","فإذا كنت تعمل في وظيفة لا تحبها، ابحث عن أخرى تلبي احتياجاتك المالية والشخصية","ليس كل هواية يمكن تحويلها إلى مهنة، لذا استمر في العمل حتى تجد ما تحب ويحقق لك دخلاً جيدًا."],"pg":52},{"id":"purchases","kind":"prevent","t":"المشتريات","why":"عند الشراء، من المهم التمييز بين الحاجات الأساسية والرغبات.","steps":["الحاجات هي الأشياء الضرورية مثل الأكل والشرب والمسكن، بينما الرغبات هي الأشياء التي يمكن تأجيلها حتى تكون لديك القدرة المالية","ركز على شراء الضروريات وتأجيل الكماليات حتى تتمكّن من تحمّل تكاليفها."],"pg":52},{"id":"budget","kind":"prevent","t":"الموازنة الشخصية","why":"لضمان مستقبل مالي مستقر.","steps":["ابدأ بإعداد ميزانية شهرية تشمل الإيرادات والمصروفات","فإذا كانت المصروفات تتجاوز الإيرادات، حاول تقليلها أو زيادة دخلك","وفي حال كانت الإيرادات أكبر، استثمر الفائض لتحقيق عائد مستقبلي أو استخدمه لشراء حاجات إضافية.","ادخر جزءًا من دخلك بانتظام وفكر في استثمار أموالك لتنميتها على المدى الطويل.","ضع خططًا مالية طويلة الأجل مثل: التخطيط للتقاعد أو شراء منزل"],"pg":53},{"id":"religion","kind":"prevent","t":"الدين","why":"الالتزام بالحد الأدنى من الطاعات والعبادات يمكن أن يمنحك الرضا الروحي ويساعد في بناء ذهنية النمو، مما يسهم في التعامل مع الضغوط وتقليل احتمالية الإصابة بالاضطرابات النفسية.","steps":["نسأل أنفسنا: ما هو الحد الأدنى من الأمور التي إذا قمنا بها نكون ملتزمين بديننا؟","وكم من الوقت تأخذ منا يوميًا وأسبوعيًا وشهريًا؟","نحاول تخصيص وقت منتظم للطاعات التي نقصّر فيها ونقوم بها بشكل أكثر انتظامًا."],"pg":53},{"id":"love","kind":"prevent","t":"الحب","why":"لتحقيق توازن صحي بين العمل والحياة الشخصية.","steps":["خصص وقتًا للعلاقات مع الأهل والأصدقاء، واهتم بحياة اجتماعية نشطة","تواصل جيدًا مع العائلة والأصدقاء لتعزيز الروابط","واهتم بشريك حياتك لقضاء لحظات مميزة معًا."],"pg":53},{"id":"hobbies","kind":"prevent","t":"الهوايات","why":"تنمية الهوايات ليست رفاهية، بل هي جزء مهم من الاستقرار النفسي والصحي، وتساعدك على الاسترخاء والتجديد.","steps":["نمِّ اهتماماتك الخارجية وخصص وقتًا لممارسة هواياتك","املأ وقت فراغك بأنشطة تحبها أو طور هواية جديدة.","تأكد أن الهواية لا تأخذ من وقتك المخصّص للنوم أو العمل أو الطاعات.","المشاركة في الأنشطة الخيرية والتطوعية تعزّز الشعور بالانتماء والتواصل الاجتماعي"],"pg":54},{"id":"lifelong","kind":"prevent","t":"التعلم المستمر","why":"هذا النوع من التعلم يعزّز الثقة بالنفس والقدرة على التكيّف مع التغيرات المستمرة في الحياة والمهنة.","steps":["القراءة","الدورات التدريبية","المشاركة في الندوات والمؤتمرات","التعلم من التجارب الشخصية والمهنية","الاستفادة من المنصات التعليمية عبر الإنترنت"],"pg":54},{"id":"self_aware","kind":"prevent","t":"الوعي الذاتي","why":"يلعب دورًا مهمًا في النمو بعد الصدمة، حيث يساعد الشخص على فهم أسباب تعثّره واكتساب الخبرة اللازمة للتطور.","steps":["استمر في تطوير مهاراتك ومعرفتك من خلال التعلم المستمر."],"pg":55},{"id":"relax","kind":"prevent","t":"التأمّل والاسترخاء","why":"يمكن أن يساعد في تقليل مستويات التوتر.","steps":["ممارسة التأمّل أو اليوغا لتحسين التركيز وتهدئة العقل.","ممارسة الهوايات التي تثير اهتمامك وتساعدك على الاسترخاء.","احترام حدودك الشخصية وتخصيص وقت للراحة.","يمكنك شحن طاقتك بالجلوس مع أحبائك وممارسة هواياتك، والحصول على إجازة للاستجمام والسفر.","أخذ استراحات قصيرة أثناء العمل وممارسة تمارين الاسترخاء مع الاستماع إلى موسيقى هادئة","تعلم تقنيات التحكم في الضغط مثل التأمل والتنفس العميق واليوغا"],"pg":55},{"id":"balance_steps","kind":"prevent","t":"كيف يمكنك تحقيق التوازن بين العمل والحياة الشخصية؟","why":"التوازن الحقيقي بين العمل والحياة الشخصية يعني تحقيق التوازن في طاقتك أيضاً.","steps":["عليك أولاً تحديد مقدار الوقت والجهد الذي تستثمره في كل جانب من جوانب حياتك، وما الذي تتلقّاه بالمقابل؟","ضع جدولاً زمنياً والتزم به.","لا تسمح لجانب من حياتك أن يتداخل مع الجوانب الأخرى: تجنّب قراءة البريد الإلكتروني المهني خلال العشاء في المنزل أو الاتصال بعميل أثناء إجازتك","جدولك الزمني وحده ليس كافياً: تأكد من معرفة جداول المحيطين بك حتى لا يحدث تعارض.","حلّل وقتك: استفد من وقتك بأقصى قدر ممكن من خلال قضاءه في الأنشطة التي تعود عليك بالفائدة.","فكّر أبعد من مجرّد الوقت: تجنّب الانشغال بالعمل أثناء الاجتماعات العائلية، والعكس صحيح.","جدّد طاقتك: احرص على مراقبة مستوى طاقتك ونشاطك، ولا تتردّد في أخذ قسط من الراحة عند الحاجة."],"pg":55},{"id":"success_protocols","kind":"prevent","t":"بروتوكولات النجاح المهني","why":"تلعب بروتوكولات النجاح المهني دورًا حيويًا في مساعدتك على تحقيق النجاح وتجنّب الاحتراق الوظيفي","steps":["نظّم وقتك ومواردك بشكل صحيح، واعرف حدودك واهتم باحتياجاتك الأساسية، وقم بمهمة واحدة في كل مرة وحدّد الأولويات.","حافظ على علاقات طيبة ومحترمة في العمل، لا تجعل من كل زميل أو مدير عدوًا","كن على طبيعتك في العمل، وكن صادقًا مع نفسك ومع الآخرين.","اعتنِ بنفسك كأولوية، وخذ استراحة أسبوعية كل ستة أسابيع لمنع الإرهاق، واعرف كيف تقول لا بإيجابية.","اعمل بساعات مرنة أو بنظام العمل المختلط، وفوّض المهام التي يمكن للآخرين القيام بها","حياتك الشخصية تخصّك وحدك فلا تتحدّث عنها في العمل","قل لا لأي مهام إضافية ليست من ضمن مسؤولياتك.","ضع حدوداً للمزاح والكلام في العمل لتجنب المشاكل والحفاظ على التوازن.","كن حازماً لا تكن دائمًا لطيفًا ومسالماً، حتى لا يتم استغلالك."],"pg":78},{"id":"assertive","kind":"prevent","t":"توكيد الذات","why":"تساعدك هذه المهارة على الحفاظ على حقوقك وبناء احترام متبادل مع الآخرين، مما يعزز الثقة بالنفس ويزيد من الرضا الوظيفي ويحميك من استنزاف الطاقة والشعور بالاستغلال.","steps":["التعبير عن أفكارك ومشاعرك بثقة واحترام، دون التوجه نحو العدوانية أو الخضوع","تطوير مهارات التفاوض والتواصل الصريح."],"pg":82},{"id":"mindful","kind":"prevent","t":"اليقظة الذهنية","why":"تساعدك هذه المهارة في زيادة التركيز والإنتاجية وتقليل التوتر والقلق، مما يساهم في تحقيق شعور الرضا والهدوء النفسي.","steps":["التركيز الكامل على اللحظة الحالية","استخدام تقنيات مثل التأمل والتنفس العميق والانتباه الواعي."],"pg":82},{"id":"emo_intel","kind":"prevent","t":"الذكاء العاطفي","why":"يساعدك في التحكم بالتوتر وإدارة الصراعات بفعالية.","steps":["فهم مشاعرك ومشاعر الآخرين وإدارتها بطريقة إيجابية","يتضمن التعاطف وضبط النفس والوعي الذاتي."],"pg":81},{"id":"face_burnout","kind":"recover","t":"مواجهة الاحتراق الوظيفي عند ظهور العلامات المبكرة","why":"هذا سيساعدك على تقييم وضعك المهني ومستوى التوتر والضغوط التي تواجهها","steps":["من المهم أولاً الاعتراف بوجود المشكلة","التحدث إلى رئيسك في العمل أو أي مسؤول آخر يمكنه المساعدة.","جرّب بعض الحلول لتقليل التوتر واستعادة طاقتك، مثل أخذ إجازة قصيرة لتجديد طاقتك الذهنية والبدنية.","معرفة حقوقك وواجباتك","إعادة صياغة أهدافك لتكون واقعية وقابلة للتحقيق"],"pg":59},{"id":"root_cause","kind":"recover","t":"البحث عن السبب الجذري (تغير في بيئة العمل)","why":"معرفة السبب الجذري للمشكلة يجنّبك كراهية العمل بأكمله، ويساعدك في التعامل مع الجزء المحدّد من المشكلة.","steps":["من المهم كذلك أن تفهم السبب الأساسي وراء هذه المشاعر، قد يكون السبب شخصًا معينًا أو أسلوبًا معينًا في التعامل","لو كنت تحت ضغط تسليم مشروع، مما يجعلك عنيفًا في التعامل وتضطر للعمل لساعات طويلة، فهذا ليس الوضع الطبيعي، بل حالة طارئة وستمر."],"pg":59},{"id":"rebalance","kind":"recover","t":"إعادة التوازن في الحياة (تغير في الحياة الشخصية)","why":"التغيرات في الحياة الشخصية قد تجعل الشخص غير قادر على الأداء أو العمل.","steps":["هناك 12 عنصرًا يجب مراعاتها، وأهمها النوم، الذي غالبًا ما نضحي به عند الشعور بالضغط، لكنه في الواقع ميزان الحياة."],"pg":60},{"id":"no_perfection","kind":"recover","t":"تجنب السعي وراء الكمال (تغير في طريقة إدراك الأمور)","why":"السعي للكمال في كل شيء والنظر للأمور من منظور مثالي يمكن أن يكون مرهقًا ومهلكًا.","steps":["من المهم أن نتذكر أن الكمال ليس مطلوبًا، وأن الاعتناء بالنفس يأتي أولاً."],"pg":60},{"id":"stage_initial","kind":"recover","t":"تدخلات المرحلة الأولية من الاحتراق الوظيفي","why":"إذا كان أسلوب حياتك يحتاج إلى تغيير، بادر الآن بإرادتك لتجنّب التغيير تحت الضغط لاحقًا.","steps":["الرعاية الذاتية: ممارسة الرياضة بانتظام، تناول وجبات متوازنة، الحصول على قسط كافٍ من النوم.","الاستجمام: أخذ فترات راحة منتظمة والقيام بأنشطة ترفيهية لتجديد الطاقة وتحسين المزاج.","دعم الأهل والأصدقاء: التحدث مع الأصدقاء والعائلة للحصول على الدعم العاطفي وتفهم الظروف التي تمر بها.","الحد من التوتر القائم على اليقظة: تقنيات مثل التأمل والتنفس العميق تساعد في تهدئة الدماغ وتقليل التوتر.","الابتعاد عن مصادر الاحتراق الوظيفي: الوعي بالعوامل التي تسبب التوتر ومراقبة أسلوب الحياة."],"pg":61},{"id":"stage_middle","kind":"recover","t":"تدخلات المرحلة المتوسطة من الاحتراق الوظيفي","why":"لتعزيز شعورك بالإنجاز والتحفيز.","steps":["إحداث التغييرات في بيئة العمل: تحسين ظروف العمل مثل تقليل عبء العمل أو تحسين العلاقات مع الزملاء والمديرين، والتفاوض على مهام العمل وطلب المساعدة عند الحاجة.","استشارة مدرب مهني بانتظام: تطوير استراتيجيات للتعامل مع الاحتراق الوظيفي وتحسين توازن العمل والحياة.","الاستفادة من كتب وقنوات المساعدة الذاتية: الحصول على نصائح وأدوات مفيدة للتعامل مع التوتر والاحتراق الوظيفي.","الدعم الاجتماعي: الانضمام إلى مجموعات دعم يوفر بيئة آمنة لمشاركة التجارب والحصول على الدعم العاطفي والنصائح المفيدة.","كتابة ملاحظات حول حالتك: متابعة تقدمك وتحديد النجاحات الصغيرة والاحتفال بها لتعزيز شعورك بالإنجاز والتحفيز."],"pg":61},{"id":"stage_advanced","kind":"recover","t":"تدخلات المرحلة المتقدمة من الاحتراق الوظيفي","why":"الحصول على العلاج المناسب إذا تطور الموضوع إلى اضطراب نفسي مصاحب.","steps":["استشارة مختص نفسي: العلاج النفسي لتحسين صحتك النفسية عند ظهور علامات الاحتراق الأولية أو المتقدمة.","العلاج المعرفي السلوكي (CBT): تغيير أنماط التفكير السلبية وتحسين التعامل مع الضغوط.","العلاج الجماعي: مشاركة التجارب والتعلم من الآخرين في بيئة داعمة.","العلاج الإنساني: التركيز على النمو الشخصي وتحقيق الذات.","استشارة طبيب نفسي: الحصول على العلاج المناسب إذا تطور الموضوع إلى اضطراب نفسي مصاحب."],"pg":62},{"id":"no_relapse","kind":"recover","t":"تجنّب العودة إلى الاحتراق الوظيفي","why":"لضمان عدم العودة إلى الاحتراق الوظيفي","steps":["من المهم التمييز بين الاحتراق الوظيفي وعدم الرضا الوظيفي أو عدم الرضا عن أسلوب الحياة.","تغيير الفريق أو موقع العمل يمكن أن يكون خطوة مفيدة إذا لزم الأمر.","من الجيد مراجعة قوانين وأنظمة الشركة قبل قبول أي وظيفة جديدة، والبحث عن السياسات التي تعزّز صحتك النفسية واستقرارك العملي.","كن نموذجًا يحتذى به في العمل من خلال مساعدة الآخرين الذين يعانون من المشكلة نفسها، ومشاركة طرقك في التعافي.","يمكن استخدام مقاييس علمية لقياس علامات الاحتراق الوظيفي، مثل مقياس ماسلاك ومقياس دنبرا."],"pg":63},{"id":"social_support","kind":"recover","t":"الدعم الاجتماعي من الأصدقاء والعائلة","why":"يلعب الدعم الاجتماعي من الأصدقاء والعائلة دورًا حاسمًا في التخفيف من أعراض الاحتراق الوظيفي وتحسين الصحة النفسية بشكل عام.","steps":["الدعم العاطفي: الاستماع والتعاطف من الأصدقاء والعائلة","تقديم النصائح والإرشاد: تقديم المشورة حول كيفية التعامل مع الضغوط والتحديات","المشاركة في الأنشطة الاجتماعية: مثل الخروج مع الأصدقاء أو قضاء وقت مع العائلة","تقديم الدعم العملي: مثل المساعدة في الأعمال المنزلية أو تقديم الدعم المالي عند الحاجة","تعزيز الشعور بالانتماء: العلاقات القوية والداعمة تعزّز الثقة بالنفس والشعور بالأمان"],"pg":64},{"id":"therapist","kind":"recover","t":"الاستعانة بالمعالج النفسي","why":"يساعد في وضع خطة علاجية مناسبة.","steps":["التقييم والتشخيص","العلاج النفسي: جلسات فردية أو جماعية لمناقشة المشاعر والأفكار السلبية والعمل على تغييرها. تقنيات مثل العلاج السلوكي المعرفي (CBT) تكون فعالة في هذا السياق.","تطوير استراتيجيات التأقلم","التوجيه والدعم","التوعية والتعليم: مما يساعد في تجنّب الانتكاسات.","التواصل مع بيئة العمل: في بعض الحالات، قد يتواصل المعالج النفسي مع بيئة العمل لتقديم توصيات حول تحسين ظروف العمل وتقليل الضغوط على الموظف."],"pg":65}],"studies":[{"id":"gaza2010","title":"ظاهرة الاحتراق الوظيفي لدى الموظفين الإداريين العاملين في وزارة التربية والتعليم العالي بقطاع غزة: أسبابها وكيفية علاجها","author":"سماهر مسلم عياد أبو مسعود","supervisor":"د. يوسف عبد عطية بحر","uni":"الجامعة الإسلامية بغزة","type":"رسالة ماجستير","aim":"هدفت هذه الدراسة إلى التعرف على مدى انتشار ظاهرة الاحتراق الوظيفي لدى الموظفين الإداريين العاملين في وزارة التربية والتعليم العالي بقطاع غزة و تحديد العلاقة ما بين ظاهرة الاحتراق الوظيفي ومجموعة من العوامل الديموغرافية (الجنس، العمر، الراتب، المؤهل العلمي، المسمى الإداري، الحالة الاجتماعية) و تحديد أسباب و مصادر انتشارها و السبل الكفيلة بعلاجها.","method":"المنهج الوصفي التحليلي","tool":"استبانة من 61 فقرة: القسم الأول السمات الشخصية؛ المجال الأول مقياس الاحتراق الوظيفي (قائمة ماسلاك للاحتراق الوظيفي Maslach Burnout Inventory بعد تعديلات بسيطة، 21 فقرة) بأبعاده: الإجهاد الانفعالي (9 فقرات)، عدم الإنسانية (5 فقرات)، الإنجاز الشخصي (7 فقرات)، بمقياس ليكرت خماسي بدلاً من بعدي التكرار والشدة؛ المجال الثاني مصادر الاحتراق الوظيفي (40 فقرة): صلاحيات العمل (6)، العلاقات الاجتماعية (8)، ضغط العمل (9)، صراع القيم (8)، قلة التعزيز الايجابي (9). معامل ألفا كرونباخ لجميع فقرات الاستبانة 0.844، ولمقياس الاحتراق 0.686.","sample":{"pop":"821 موظف","n":"258 استبانة مستردة من أصل 300 استبانة موزعة (حجم العينة المقرر 262 موظف، إضافة إلى عينة استطلاعية حجمها 45 استبانة)","who":"العاملون في الوظائف الإدارية بوزارة التربية و التعليم بغزة و المديريات التابعة لها، ممن يشغلون وظائف (رئيس قسم، رئيس شعبة، موظف إداري، سكرتير)، اختيروا بطريقة العينة العشوائية البسيطة؛ 182 ذكراً (70.5%) و 76 أنثى (29.5%)","rate":"86%"},"short":"دراسة غزة","where":"قطاع غزة، فلسطين","year":"2010","toolShort":"مقياس ماسلاك بأبعاده الثلاثة، ومقياس لمصادر الاحتراق من 40 فقرة","head":"83.7% من الموظفين في مستوى متوسط من الاحتراق، و13.2% في مستوى مرتفع، وأقوى علاقة كانت مع ضغط العمل","results":[{"x":"العاملين في الوظائف الإدارية في وزارة التربية و التعليم العالي بقطاع غزة والمديريات التابعة لها يعانون بصفة عامة درجات متوسطة من الاحتراق الوظيفي على بعدي الإجهاد الانفعالي و عدم الانسانية، أما على البعد الثالث (الانجاز الشخصي) فقد أظهرت النتائج انخفاض مستوى الاحتراق الوظيفي لدى المبحوثين.","topic":"stats"},{"x":"مما سبق نستطيع أن نرى أن ما نسبته 83.7% يعانون من احتراق وظيفي متوسط في حين كان ما نسبته 13.2% يعاني من ارتفاع في مستوى الاحتراق الوظيفي.","topic":"stats"},{"x":"وبشكل عام يمكن القول بأن المتوسط الحسابي يساوي 3.02، وأن المتوسط الحسابي النسبي لجميع فقرات المجال يساوي 60.45 ... لذلك يعتبر مجال \" الإجهاد الانفعالي \" غير دالة إحصائياً ... و هذا يدل على أن الموظفين غير قادرين على إعطاء رؤية واضحة تعكس مدى معاناتهم من الاحتراق على هذا البعد.","topic":"dims"},{"x":"وبشكل عام يمكن القول بأن المتوسط الحسابي يساوي 2.32، وأن المتوسط الحسابي النسبي لجميع فقرات المجال يساوي 46.36 ... مما يعكس عدم معاناة المبحوثين من احتراق على هذا البعد.","topic":"dims"},{"x":"وبشكل عام يمكن القول بأن المتوسط الحسابي يساوي 3.77، وأن المتوسط الحسابي النسبي لجميع فقرات المجال يساوي 75.39 ... مما يعكس عدم معاناة الموظفين من احتراق وظيفي على هذا البعد حيث إن هذا البعد معكوس بمعنى أن الموافقة تعني احتراق منخفض.","topic":"dims"},{"x":"توجد علاقة عكسية ذات دلالة إحصائية بين صلاحيات العمل و درجة الاحتراق الوظيفي بأبعاده الثلاثة. حيث إنه كلما زادت الصلاحيات الممنوحة للموظف كلما قل شعوره بالاحتراق الوظيفي على أبعاده الثلاثة حيث إن عدم إتاحة الفرصة للموظفين للمشاركة في اتخاذ القرارات يؤدي حتما لشعورهم بالمعاناة و السلبية و تدني مستوى رضاهم و شعورهم بالعجز و فقدان التحكم في عملهم.","topic":"causes"},{"x":"توجد علاقة طردية ذات دلالة إحصائية بين انعدام العلاقات الاجتماعية و درجة الاحتراق الوظيفي بأبعاده الثلاثة مما يعني أنه كلما زاد انعدام العلاقات الاجتماعية السائدة بين العاملين كلما زاد الاحتراق الوظيفي بأبعاده الثلاثة. فالعلاقات الايجابية و الطيبة بين الموظفين و رؤسائهم من جهة و مع زملائهم من جهة أخرى أو مع المراجعين ستنعكس حتما على رضا و نفسية الموظفين و بالتالي مستوى احتراقهم.","topic":"causes"},{"x":"توجد علاقة طردية ذات دلالة إحصائية بين ضغط العمل و درجة الاحتراق الوظيفي حيث كانت العلاقة بين الضغوط و الاحتراق من أقوى العلاقات المبحوثة في هذه الدراسة.","topic":"causes"},{"x":"توجد علاقة طردية ذات دلالة إحصائية بين صراع القيم و درجة الاحتراق الوظيفي بأبعاده الثلاثة. فكلما زادت حدة صراع القيم بين الموظفين كلما زادت درجة الاحتراق على أبعاده الثلاثة فكلما كان هناك تعارض في قيم الموظف مع قيم من حوله أو قيم بيئة عمله فان ذلك سيؤثر حتما على نفسيته و من ثم شعوره بالاحتراق.","topic":"causes"},{"x":"توجد علاقة عكسية ذات دلالة إحصائية بين قلة التعزيز الايجابي و درجة الاحتراق الوظيفي مما يعني أنه كلما قل التعزيز الايجابي كلما زادت درجة الاحتراق الوظيفي بأبعاده الثلاثة لدى الموظفين فالحوافز و الأجور غير العادلة و غير المرضية تولد شعورا لدى الموظفين بالإحباط.","topic":"causes"},{"x":"أظهر المبحوثين قبولا لمستوى الصلاحيات الممنوحة لهم، حيث إن المستويات الإدارية المبحوثة هنا ليست مستويات أخذ قرار و عليه يشعر الموظفين المبحوثين بأن الصلاحيات الممنوحة لهم بموجب اللوائح و القوانين الحكومية كافية.","topic":"org"},{"x":"العلاقات الاجتماعية موجود و سائدة بين الموظفين عينة الدراسة و ذلك يعود لطبيعة المجتمع الفلسطيني المترابط و الاجتماعي.","topic":"causes"},{"x":"أظهر المبحوثين عدم معاناتهم من ضغوط العمل و ذلك قد يعود لوضوح الأعمال الإدارية المناطة بهم و عدم تعقدها. إلا أن الضغوط سجلت أقوى علاقة مع الاحتراق الوظيفي خاصة على البعد الأول (الإجهاد الانفعالي).","topic":"causes"},{"x":"لا يعاني الموظفين من صراع القيم و ذلك يعود لطبيعة بيئة العمل التي تنسجم قيمها مع قيم الموظفين، إلا أن الموظفين أظهروا وجود خلافات سياسية و حزبية ملحوظة بين زملاء العمل في الوزارة.","topic":"causes"},{"x":"أظهر المبحوثين عدم رضا عن نظام التعزيز و الحوافز بمختلف أشكالها المتبعة في الوزارة.","topic":"org"},{"x":"جنس الموظف (ذكر / أنثى) لا يؤثر على مستوى الاحتراق الوظيفي بأبعاده الثلاثة و ذلك يرجع لمساواة الموظفين من الجنسين في العبء الوظيفي و تكافؤ فرص الجنسين في الحصول على الوظائف بالإضافة لمشاركة المرأة في تحمل الأعباء الحياتية شانها شأن الرجل.","topic":"groups"},{"x":"هناك فروق ذات دلالة إحصائية في مستوى الاحتراق بأبعاده الثلاثة تعزى لمتغير الحالة الاجتماعية حيث أظهرت النتائج أن فئة المتزوجين كانت الأقل معاناة من الاحتراق على أبعاده الثلاثة من الفئات الأخرى و ذلك يعود لكون هذه الفئة أكثر استقرارا من الناحية النفسية و العاطفية من غيرهم فالحالة الاجتماعية تضيف عبئا على الموظف و تزيد من شعوره بالإحباط و عدم الاستقرار.","topic":"groups"},{"x":"هناك فروق ذات دلالة إحصائية في مستوى الاحتراق على بعد الانجاز الشخصي تعزى لمتغير العمر، حيث وجدت الدراسة أن من هم أكبر من 50 سنة أقل معاناة من غيرهم من الفئات العمرية الأخرى على بعد الانجاز الشخصي و يرجع ذلك لكون هذه الفئة أكثر فهما لأعمالهم بحكم خبرتهم فهم أكثر تمرسا لأعمالهم من غيرهم فيكون تقديرهم لأدائهم ايجابي بعكس الجدد الذين يكون مستوى طموحاتهم عال في بداية عملهم و يصطدموا بواقع العمل الذي لا يشبع طموحاتهم مما يؤثر على نفسياتهم.","topic":"groups"},{"x":"هناك فروق ذات دلالة إحصائية في مستوى الاحتراق على بعد عدم الإنسانية تعزى لمتغير المؤهل العلمي، حيث وجدت الدراسة أن حملة الدبلوم أكثر معاناة من غيرهم من الفئات من الاحتراق على بعد عدم الإنسانية و يرجع ذلك لكون حملة الدبلوم غالبا ما يعملوا بوظيفة سكرتير فهم الأكثر تعاملا مع الجمهور و بشكل مباشر و غالبا ما يتسم عملهم بالنمطية و الروتينية مما يؤثر على نفسياتهم.","topic":"groups"},{"x":"هناك فروق ذات دلالة إحصائية في مستوى الاحتراق على بعد عدم الإنسانية تعزى لمتغير سنوات الخبرة حيث وجدت الدراسة أن الموظفين ذوي سنين الخبرة من 4 إلى 7 أكثر معاناة من غيرهم من الاحتراق على بعد عدم الإنسانية، في حين أظهرت الدراسة أن ذوي سنين الخبرة أكثر من 11 سنة أقل معاناة من الاحتراق على بعد الانجاز الشخصي و يرجع ذلك لان الموظف كلما زادت سنوات خبرته و عمله كلما زاد تقبله لوظيفته و رضاه و تصبح طموحاتهم و توقعاتهم من عملهم واقعية بعكس الموظفين الجدد الذين تكون توقعاتهم مثالية مما يؤثر على نفسياتهم و معاناتهم من الاحتراق.","topic":"groups"},{"x":"لا توجد فروق ذات دلالة إحصائية في مستويات الاحتراق الوظيفي تعزى لمتغير الراتب الشهري و يعود ذلك لانخفاض مستوى التباين في الرواتب الممنوحة للعاملين في المستويات الإدارية المبحوثة و بالتالي لا يكون للراتب ذلك الأثر المميز على مستوى الاحتراق.","topic":"groups"},{"x":"هناك فروق ذات دلالة إحصائية في مستوى الاحتراق الوظيفي على بعد عدم الإنسانية تعزى لمتغير المستوى الإداري، حيث كان العاملين بوظيفة سكرتير أكثر معاناة من غيرهم من الاحتراق لكونهم الأكثر تعاملا مع الجمهور و الأكثر معاناة من تسلط و قرارات رؤسائهم والأكثر معاناة من ضغوط العمل، في حين كان العاملين في وظيفة رئيس قسم الأقل معاناة من غيرهم على بعد الانجاز الشخصي و يرجع ذلك لان مستوى الصلاحيات الممنوحة لهم أكبر مما يؤثر على مستوى تقييمهم لانجازهم.","topic":"groups"}],"recs":["التقرب من الله بالصبر و الصلاة و التقوى و تبني القيم و التعاليم الدينية في المعاملات فلو حرص كل موظف على أن يكون خلقه القرآن في التعامل مع رئيسه أو زميله أو جمهور المراجعين من جهة و رضي بقدر الله و رزقه و تبنى قناعة بأن عمله و وظيفته عبادة قبل أن تكون وسيلة لكسب الرزق أو تحقيق مكانة اجتماعية فإن ذلك من شأنه التخفيف من حدة معاناة الموظفين من الاحتراق الوظيفي.","ضرورة اهتمام أصحاب القرار في وزارة التربية و التعليم بهذه الظاهرة من خلال تبني استراتيجيات تكسر الجمود و الصرامة و الروتين الملاحظ في الأعمال الحكومية بتبني سياسة التدوير بحيث لا يمكث الموظف في وظيفته أكثر من 5 سنوات فمن المعاناة فعلا أن يمكث الموظف في وظيفته حتى يحال للتقاعد و العمل على دراسة أهم الأسباب التي أدت لمعاناة نسبة لا يستهان بها من الموظفين من الاحتراق على البعدين الإجهاد الانفعالي و عدم الإنسانية.","العمل على اهتمام الوزارة بالجانب الترفيهي لموظفيها لكسر الجمود و الصرامة في تأدية أعمالها واستحداث برامج ترفيهية من شأنها تجديد طاقات الموظفين على سبيل المثال تخصيص بعض الأيام على مدار السنة للاحتفال بمناسبات اجتماعية كتخصيص يوم للعائلة يحتفل و يرفه فيه الموظف عن نفسه و يخرج عن جو العمل و الضغط مع عائلته، أو الخروج لرحلات ترفيهية جماعية للموظفين خلال عطلة نهاية الأسبوع أو خلال العطل و المناسبات الدينية و القومية، هذا بالإضافة لتقوية العلاقات الاجتماعية و المساندة الاجتماعية ما بين زملاء العمل.","إعطاء دورات إدارية مركزة و بشكل دوري للعاملين في المستويات الإدارية العليا في فن الإدارة العلمية و فن التعامل مع موظفيهم و تفويض الصلاحيات و رفع معنويات موظفيهم من خلال تبني صنوف مختلفة من الحوافز المعنوية كشهادات الشكر والتقدير أو بالتعزيز القولي مما سيؤثر في نفسيات مرءوسيهم هذا بالإضافة إلى إيجاد قنوات اتصال فعالة بحيث تتيح للإدارة العليا التعرف على المصادر المسببة للاحتراق الوظيفي و بحيث يشعر العاملون بأن اقتراحاتهم و شكاواهم تصل إليهم و تؤكد دورهم في المشاركة في عملية صنع القرارات.","استحداث برامج مساعدة للعاملين من خلال تقديم خدمات طبية و علاجية لهم و تقديم النصح و المشورة و الإجراءات الوقائية المناسبة، و الاهتمام بالموظفين الجدد و مساعدتهم في عملية الاندماج في العمل و تحقيق مستوى من التوازن ما بين طموحاتهم و واقع عملهم.","العمل على زرع روح التعاون ما بين الموظفين حيث أظهرت النتائج وجود علاقة ما بين العلاقات الاجتماعية السائدة ما بين الموظفين و مستوى الاحتراق الوظيفي.","النظر في أسلوب توزيع الأعمال بين الأفراد على أساس إعادة تصميم الوظائف و بما يتفق و مواصفات الفرد و العمل و مراعاة العدل و المساواة في توزيع الأعباء على الأفراد بحيث يكون هدف إعادة التصميم تخفيف الأعباء أو إثراء للوظيفة لزيادة الشعور بالمسئولية و الصلاحيات الممنوحة و الاستقلالية، أو خلق حالة من التعاون الحماسي و المشاركة عن طريق التدوير الوظيفي أو أداء الوظيفة بالتناوب للتغلب على الشعور بالوحدة والعزلة و الملل، حيث أظهرت النتائج وجود علاقة ما بين ظاهرة الاحتراق و ضغط العمل و الصلاحيات الممنوحة للموظفين.","عقد دورات و توزيع نشرات تثقيفية حول ظاهرة الاحتراق الوظيفي و كيفية التعامل مع ضغوط العمل أو صراع القيم أو لتعزيز العلاقات الاجتماعية لتلافي المعاناة من الاحتراق الوظيفي.","عقد دورات و توزيع نشرات تثقيفية للحد من ظاهرة التحزب لدى الموظفين العاملين في مؤسسات السلطة الوطنية الفلسطينية مما يقضي على الصراعات الحزبية الملموسة ما بين الموظفين و زرع ثقافة الولاء الديني و الوطني لا الحزبي.","تطوير نظم الاختيار و التعيين و التوفيق بين متطلبات الوظيفة و خصائص و قدرات الأفراد حيث يمكن تحقيق قدر أكبر من التوافق بين الفرد و متطلبات الوظيفة، حيث إن سياسة الاختيار والتعيين ستؤثر حتما في مدى شعور الموظف بالرضا عن عمله و مدى شعوره بملائمة عمله لقدراته مما يؤثر حتما على نفسيته و بالتالي على معاناته من الاحتراق.","السعي بشكل أكبر لتطوير قدرات و مهارات العاملين في الوزارة من خلال عقد دورات تدريبية شاملة و دورية و طبقا لاحتياجات الموظفين مما يعطي الموظفين شعورا باهتمام الإدارة بهم.","إعادة النظر في نظم الأجور والحوافز بنوعيها المادية و المعنوية، و ضرورة تطويرها وفق رغبات العاملين مما يؤدي على التخلص من أسباب الاحتراق الوظيفي والقلق و الكآبة و الإحباط لأن الاهتمام بهذه الأمور ووضع الأسس والقواعد التي تكفل المساواة للجميع و العمل على إزالة المعوقات سواء كانت إدارية أو مالية مما يكون له انعكاسات ايجابية على الفرد و أدائه، و العمل على تعزيز الموظفين العاملين بحيث يشعر الموظف المخلص بأن هناك تقدير لجهوده و ذلك من خلال وسائل عدة مثل عقد مسابقة سنوية لاختيار الموظف المثالي على مستوى الوزارة مثلا و تقديم مكافأة رمزية له.","الأخذ في الاعتبار الوسائل الشخصية و التنظيمية التي ذكرت في الجزء النظري لمعالجة الاحتراق الوظيفي و آثاره.","التنسيق ما بين وزارة التعليم العالي و الجامعات المحلية و الجهات المعنية من المؤسسات الحكومية و غيرها و توظيف نتائج البحوث العلمية لتطوير و تحسين الأداء الإداري في مؤسسات السلطة الوطنية الفلسطينية و غيرها من المؤسسات المحلية."],"tables":[{"t":"جدول (27): مستويات الاحتراق الوظيفي (العدد والنسبة %)","head":["البعد","احتراق منخفض","احتراق متوسط","احتراق مرتفع"],"rows":[["الإجهاد الانفعالي (منخفض 0 إلى 15، متوسط 16 إلى 30، مرتفع 31 إلى 45)","7 (2.7%)","182 (70.5%)","69 (26.7%)"],["عدم الإنسانية (منخفض 0 إلى 8، متوسط 9 إلى 16، مرتفع 17 إلى 25)","69 (26.7%)","148 (57.4%)","41 (15.9%)"],["الإنجاز الشخصي، مقياس معكوس (منخفض 25 إلى 35، متوسط 13 إلى 24، مرتفع 0 إلى 12)","190 (73.6%)","68 (26.4%)","0 (0%)"]]},{"t":"خلاصة الجداول (23) إلى (26): المتوسط الحسابي لأبعاد مقياس الاحتراق (من 5) واختبار الإشارة","head":["البعد","المتوسط الحسابي","المتوسط الحسابي النسبي %","قيمة الاختبار","Sig."],"rows":[["الإجهاد الانفعالي (9 فقرات)","3.02","60.45","1.22","0.112"],["عدم الإنسانية (5 فقرات)","2.32","46.36","-10.69","0.000"],["الإنجاز الشخصي (7 فقرات، معكوس)","3.77","75.39","11.87","0.000"],["جميع فقرات المقياس بعد عكس البعد الثالث","2.59","51.80","-9.09","0.000"]]},{"t":"خلاصة الجداول (29) و (31) و (33) و (35) و (37): متوسطات مجالات مصادر الاحتراق (من 5)","head":["المجال","المتوسط الحسابي","المتوسط الحسابي النسبي %","قيمة الاختبار","Sig."],"rows":[["صلاحيات العمل (6 فقرات)","3.42","68.43","8.15","0.000"],["العلاقات الاجتماعية (8 فقرات)","2.64","52.80","-0.48","0.000"],["ضغط العمل (9 فقرات)","2.92","58.43","-11.81","0.018"],["صراع القيم (8 فقرات)","2.82","56.32","-2.52","0.006"],["قلة التعزيز الايجابي (9 فقرات)","2.64","52.74","-5.68","0.000"]]},{"t":"الجداول (30) و (32) و (34) و (36) و (38): معامل ارتباط سبيرمان بين مصادر الاحتراق ودرجة الاحتراق (جميعها دالة عند 0.05)","head":["المصدر","الإجهاد الانفعالي","عدم الإنسانية","الإنجاز الشخصي","مقياس الاحتراق الوظيفي"],"rows":[["صلاحيات العمل","-0.312","-0.205","-0.409","-0.471"],["انعدام العلاقات الاجتماعية","0.476","0.418","0.225","0.485"],["ضغط العمل","0.628","0.476","0.225","0.634"],["صراع القيم","0.468","0.464","0.350","0.577"],["قلة التعزيز الايجابي","-0.350","-0.179","-0.271","-0.380"]]}]},{"id":"jeddah","title":"الاحتراق الوظيفي وتأثيره على أداء العاملين في وزارة الشؤون البلدية والقروية (دراسة تطبيقية على الإداريين العاملين بأمانة محافظة جدة)","author":"منار محمد الصبحي","supervisor":"","uni":"جامعة جدة، كلية الأعمال","type":"بحث ماجستير تنفيذي، منشور في مجلة IJRSP","aim":"هدفت الدراسة إلى معرفة مستوى الاحتراق الوظيفي وأثره على الأداء الوظيفي لدى الموظفين الإداريين العاملين في وزارة الشؤون البلدية والقروية، أمانة محافظة جدة، ومعرفة مدى اختلاف مستوى الاحتراق الوظيفي لدى أفراد العينة باختلاف المتغيرات الديموغرافية (الجنس، الحالة الاجتماعية، العمر، المؤهل وسنوات الخبرة)","method":"المنهج الوصفي التحليلي","tool":"استبانة مطورة من الدراسات السابقة، 30 فقرة على مقياس ليكرت الخماسي، من أربعة أقسام: (1) البيانات الشخصية؛ (2) مقياس الاحتراق الوظيفي بثلاثة أبعاد: الإجهاد الانفعالي، عدم الإنسانية، الإنجاز الشخصي (3 فقرات لكل بعد)؛ (3) مصادر الاحتراق الوظيفي بخمسة أبعاد: صلاحيات العمل، العلاقات الاجتماعية، ضغط العمل، صراع القيم، قلة التعزيز الإيجابي (3 فقرات لكل بعد)؛ (4) الأداء الوظيفي ببعدين: الجهد المبذول في العمل، القدرات والخصائص الفردية (3 فقرات لكل بعد). معامل ألفا كرونباخ للمقياس ككل 0.737","sample":{"pop":"700 موظف (الموظفون الإداريون العاملون في وزارة الشؤون البلدية والقروية، أمانة محافظة جدة)","n":"149 (وُزعت 175 استبانة بعد عينة استطلاعية من 50 استبانة)","who":"الموظفون الإداريون بأمانة محافظة جدة، اختيروا بطريقة العينة العشوائية البسيطة: 90 ذكراً (60.4%) و53 أنثى (35.6%) و6 فضلوا عدم التصريح (4%)","rate":"95% كما ذكرت الباحثة"},"short":"دراسة جدة","where":"جدة، السعودية","year":"2022","toolShort":"استبانة من 30 فقرة: الاحتراق ومصادره والأداء الوظيفي","head":"درجات مرتفعة من الاحتراق على بعدي الإجهاد الانفعالي وعدم الإنسانية، ولا فروق تعزى للمتغيرات الشخصية","results":[{"x":"العاملين في الوظائف الإدارية في وزارة الشؤون البلدية والقروية، أمانة محافظة جدة يعانون بصفة عامة درجات مرتفعة من الاحتراق الوظيفي على بعدي الإجهاد الانفعالي والانجاز الشخصي، أما على البعد الثالث عدم الإنسانية فقد أظهرت النتائج انخفاض مستوى الاحتراق الوظيفي لعينة الدراسة.","topic":"dims"},{"x":"هناك علاقة عكسية ذات دلالة إحصائية بين صلاحيات العمل ودرجة الاحتراق الوظيفي بأبعاده الثلاثة. (معامل ارتباط بيرسون 0.260 دال عند 0.05، جدول 20)","topic":"causes"},{"x":"توجد علاقة طردية ذات دلالة إحصائية بين انعدام العلاقات الاجتماعية ودرجة الاحتراق الوظيفي بأبعاده الثلاثة مما يعني أنه كلما زاد انعدام العلاقات الاجتماعية السائدة بين العاملين كلما زاد الاحتراق الوظيفي بأبعاده الثلاثة فالعلاقات الإيجابية حتماً تنعكس على الموظفين سواء مع المراجعين أو المدراء. (معامل ارتباط بيرسون 0.370 دال عند 0.001)","topic":"causes"},{"x":"توجد علاقة طردية ذات دلالة إحصائية بين ضغط العمل ودرجة الاحتراق الوظيفي حيث كانت العلاقة بين الضغوط والاحتراق من أقوى العلاقات في هذه الدراسة. (معامل ارتباط بيرسون 0.534 دال عند 0.001)","topic":"causes"},{"x":"هناك علاقة ذات دلالة إحصائية بين صراع القيم ودرجة الاحتراق الوظيفي بأبعاده الثلاثة فكلما زادت حدة صراع القيم بين الموظفين كلما زادت درجة الاحتراق على أبعاده الثلاثة فكلما كان هناك تعارض في قيم الموظف وقيم من حوله فإن ذلك سيؤثر حتماً على نفسيته ويؤدي إلى زيادة احتراقه. (معامل ارتباط بيرسون 0.407 دال عند 0.001)","topic":"causes"},{"x":"هناك علاقة عكسية ذات دلالة احصائية بين قلة التعزيز الإيجابي ودرجة الاحتراق الوظيفي بأبعاده الثلاثة فكلما قل التعزيز زاد الاحتراق الوظيفي حيث أن الموظف يحتاج دائماً إلى التعزيز بطرق مختلفة. (معامل ارتباط بيرسون 0.166 دال عند 0.05)","topic":"causes"},{"x":"عدم وجود فروق ذات دلالة إحصائية بين متوسطات درجات أفراد العينة على مقياس الاحتراق الوظيفي تبعاً للأداء الوظيفي، حيث بلغت قيمة ف 0.692 وهذه القيمة غير دالة عند مستوى دلالة = 0.05.","topic":"effects"},{"x":"وجود علاقة دالة احصائيا بين الإجهاد الانفعالي والأداء الوظيفي، حيث بلغ معامل ارتباط بيرسون (0.251)، وهي قيمة دالة إحصائياً عند مستوي دلالة (0.001). وجود علاقة دالة احصائيا بين عدم الإنسانية والأداء الوظيفي، حيث بلغ معامل ارتباط بيرسون (0.353)، وهي قيمة دالة إحصائياً عند مستوي دلالة (0.001).","topic":"effects"},{"x":"الانحدار الخطي بين: الإجهاد الانفعالي والأداء الوظيفي، حيث أن معاملات الانحدار لديهم ليست ذات دلالة معنوية عند مستوى دلالة 0.05؛ عدم الإنسانية والأداء الوظيفي، حيث أن معاملات الانحدار لديهم ذات دلالة معنوية؛ الإنجاز الشخصي والأداء الوظيفي، حيث أن معاملات الانحدار ذات دلالة معنوية عند مستوى دلالة 0.001. (الميل β1: 0.059 بدلالة 0.614؛ 0.266 بدلالة 0.043؛ 0.905 بدلالة 0.000، جدول 19)","topic":"effects"},{"x":"عدم وجود فروق ذات دلالة إحصائية بين متوسطات درجات أفراد العينة على مقياس الاحتراق الوظيفي تبعاً للنوع والحالة الاجتماعية والعمر والمؤهل التعليمي وسنوات الخبرة (قيم ف في جدول 9: 1.173، 0.831، 2.326، 1.612، 0.538، وكلها غير دالة عند 0.05).","topic":"groups"},{"x":"عدم وجود فروق ذات دلالة إحصائية بين متوسطات درجات أفراد العينة على مقياس الأداء الوظيفي تبعاً للنوع (ف 0.491) والحالة الاجتماعية (ف 2.576) والعمر (ف 1.222) والمؤهل التعليمي (ف 1.753) وسنوات الخبرة (ف 0.761)، وهذه القيم غير دالة عند مستوى دلالة = 0.05.","topic":"groups"},{"x":"جاءت أعلى فقرات مصادر الاحتراق وزناً نسبياً: (حجم الأعمال التي أقوم بها تتناسب مع قدراتي وطموحاتي ومهاراتي) بوزن نسبي 76.38%، و(تحول الصراعات الشخصية دون انسجام العاملين) بوزن نسبي 75.70%، و(تنطوي وظيفتي على أداء أعمال قد ترضي بعضهم ولا ترضي البعض الآخر) بوزن نسبي 69.53%، و(أحياناً تكون المهام المسندة لي معقدة أو صعبة) بوزن نسبي 52.08%، و(يوجد فرص للحصول على حوافز معنوية (شهادة شكر، تقدير، الخ) في عملي) بوزن نسبي 57.99%.","topic":"causes"}],"recs":["الاهتمام من قبل الجهات المختصة في وزارة الشؤون البلدية والقروية، أمانة محافظة جده بهذه الظاهرة وتبني استراتيجيات تكسر الصرامة وضغط العمل والروتين السائد في الاعمال الحكومية","الاهتمام بالجانب الاجتماعي وتقوية العلاقات مع الموظفين لكسر الجمود والصرامة في تأدية أعمالهم واستحداث برامج ترفيهية من شأنها تجديد طاقات الموظفين ومشاركتهم جميع المناسبات العامة والخاصة.","الاهتمام بالدورات الإدارية لجميع الموظفين في المستويات الإدارية المختلفة وخاصة العليا منها في فن الإدارة العلمية وفن التعامل مع موظفيهم وتفويض الصلاحيات ورفع المعنويات من خلال تبني التنوع في الحوافز المعنوية كشهادات الشكر والتقدير أو بالتعزيز القولي مما سيؤثر في نفسيات الموظفين.","تطوير برامج للموظفين تعمل على تقديم الخدمات الطبية والعلاجية لهم وتقديم المشورات الوقائية المناسبة، والاهتمام بالموظفين حديثي التوظيف ومساعدتهم في عملية الاندماج في العمل وتحقيق مستوى من التوازن ما بين طموحاتهم وواقع عملهم.","ضرورة زرع روح التعاون بين الموظفين حيث أظهرت النتائج وجود علاقة ما بين العلاقات الاجتماعية السائدة ما بين الموظفين ومستوى الاحتراق الوظيفي.","السعي بشكل أكبر لتطوير مهارات وقدرات الموظفين في وزارة الشؤون البلدية والقروية، أمانة محافظة جدة من خلال عقد الدورات التدريبية الشاملة والدورية طبقاً لاحتياجات الموظفين مما يعطي الموظفين شعوراً بأنهم من اولويات الإدارة."],"tables":[{"t":"جدول (10) استجابات أفراد العينة على مقياس مصادر الاحتراق الوظيفي","head":["البعد","العبارة","المتوسط","الانحراف المعياري","الوزن النسبي"],"rows":[["صلاحيات العمل","حجم الأعمال التي أقوم بها تتناسب مع قدراتي وطموحاتي ومهاراتي","3.82","1.14","76.38"],["صلاحيات العمل","فوضني رئيسي لاتخاذ قرارات تتعلق بالعمل","3.62","1.09","72.35"],["صلاحيات العمل","لدي مجالات كافية من السلطة والصلاحيات لإداء مهام وظيفتي","3.44","1.13","68.86"],["العلاقات الاجتماعية","تحول الصراعات الشخصية دون انسجام العاملين","3.79","1.22","75.70"],["العلاقات الاجتماعية","لا أشعر بأنني منتمي اجتماعيا لزملائي ومكان عملي","2.30","1.23","45.91"],["العلاقات الاجتماعية","أجد صعوبة في التوجه الى رئيسي في العمل عندما توجهني مشكلة ما","2.22","1.20","44.43"],["ضغط العمل","أحيانا تكون المهام المسندة لي معقدة او صعبة","2.60","1.11","52.08"],["ضغط العمل","أواجه صعوبة في الحصول على إجازة","2.44","1.19","48.72"],["ضغط العمل","اشعر بالاكتئاب وضيق الصدر أثناء أدائي لمهام عملي","2.05","1.03","41.07"],["صراع القيم","تنطوي وظيفتي على أداء أعمال قد ترضي بعضهم ولا ترضي البعض الآخر","3.48","1.19","69.53"],["صراع القيم","الثقافة السائدة في عملي لا تشعرني بالراحة والانتماء لعملي","2.87","1.22","57.32"],["صراع القيم","يطلب مني أداء اعمال تتناقض مع مبادئ العمل","2.19","1.11","43.76"],["قلة التعزيز الإيجابي","يوجد فرص للحصول على حوافز معنوية (شهادة شكر، تقدير، الخ) في عملي","2.90","1.35","57.99"],["قلة التعزيز الإيجابي","يتناسب راتبي مع حجم أدائي في عملي وهو محفز لي","2.64","1.21","52.75"],["قلة التعزيز الإيجابي","تتم الترقية في عملي بعدالة وموضوعية وهي مرتبطة بالأداء ومحفزة","2.54","1.32","50.87"]]},{"t":"جدول (20) معامل ارتباط بيرسون بين مصادر الاحتراق الوظيفي ودرجات الاحتراق الوظيفي","head":["المصدر","معامل الارتباط","الدلالة"],"rows":[["صلاحيات العمل","0.260*","0.05"],["العلاقات الاجتماعية","0.370**","0.001"],["ضغط العمل","0.534**","0.001"],["صراع القيم","0.407**","0.001"],["قلة التعزيز الإيجابي","0.166*","0.05"]]}]},{"id":"syria","title":"أثر الاحتراق الوظيفي على أداء العاملين ومعدل دوران العمل في المنظمات الانسانية (دراسة تطبيقية على عدد من المنظمات الإنسانية تحت مظلة الأمم المتحدة في سورية)","author":"هبة تراس","supervisor":"الدكتور عبدالحميد الخليل","uni":"المعهد العالي لإدارة الأعمال HIBA","type":"بحث ماجستير في إدارة الأعمال التنفيذية","aim":"يهدف البحث بصفة أساسية إلى ما يلي: (1) استكشاف الأسباب الكامنة وراء الاحتراق الوظيفي للعاملين. (2) استكشاف مستوى أداء العاملين في المنظمات الإنسانية في ظل الاحتراق الوظيفي وضغوط العمل في المنظمات الإنسانية العاملة في سورية تحت مظلة الأمم المتحدة. (3) استكشاف دوران العمل ونية ترك العمل لدى العاملين المنظمات الإنسانية في ظل الاحتراق الوظيفي وضغوط العمل في المنظمات الإنسانية العاملة في سورية تحت مظلة الأمم المتحدة. (4) استكشاف أثر الاحتراق الوظيفي على أداء العاملين في المنظمات الإنسانية في المنظمات الإنسانية العاملة في سورية تحت مظلة الأمم المتحدة. (5) استكشاف أثر الاحتراق الوظيفي على معدل دوران العمل في المنظمات الإنسانية في المنظمات الإنسانية العاملة في سورية تحت مظلة الأمم المتحدة. (6) الوصول إلى حلول لتقليل معدل دوران العمل، وتحسين أداء العاملين بتقليل آثار الاحتراق الوظيفي.","method":"المنهج الوصفي التحليلي الذي اعتمد على أداة الاستبانة كأداة للدراسة، وكذلك المنهج النوعي الاستكشافي الذي تضمن مجموعة التركيز المعمّقة مع العاملين لاستخلاص عبارات الاستبانة، وكذلك المقابلات مع الإداريين في بعض المنظمات الإنسانية العاملة في سورية تحت مظلة الأمم المتحدة. التحليل: المتوسط والانحراف المعياري واختبار one sample T-Test والانحدار الخطي البسيط","tool":"استبانة من أربعة محاور: المعلومات الديمغرافية (الجنس، الفئة العمرية، مستوى التعليم)؛ محور الاحتراق الوظيفي (14 عبارة، تستند بحسب حاشية الملحق إلى Maslach & Jackson 1982)؛ محور الأداء الوظيفي (10 عبارات)؛ محور دوران العمل (6 عبارات)؛ بمقياس خماسي من (غير موافق أبداً) إلى (موافق بشدة). ألفا كرونباخ: الاحتراق الوظيفي 0.891، أداء العاملين 0.824، معدل الدوران الوظيفي 0.868","sample":{"pop":"يتألف مجتمع البحث من جميع العاملين في المنظمات الإنسانية في سورية تحت مظلة الأمم المتحدة","n":"244 استبانة قابلة للتحليل من 260 وُزعت، إضافة إلى مجموعة تركيز معمقة من 8 عاملين (4 في صندوق الأمم المتحدة للسكان، 2 من UNDP، 2 من UNHCR) ومقابلات استجاب لها 6 من أفراد الإدارات العليا","who":"عدد ميسر من العاملين في منظمات UNFPA, UNHCR, UNDP؛ 63% إناث و37% ذكور؛ 51% من 21 إلى 30 سنة و36% من 31 إلى 40 سنة و8% من 41 إلى 50 سنة و5% من 51 سنة فأكبر؛ 49% جامعيون و42% دراسات عليا و7% معهد متوسط و2% ثانوي وما دون","rate":"94%"},"short":"دراسة سورية","where":"سورية، منظمات أممية","year":"بلا تاريخ","toolShort":"استبانة من 30 عبارة، ومجموعة تركيز، ومقابلات مع المدراء","head":"أثر الاحتراق على الأداء ضعيف (9%)، وعلى دوران العمل قوي (58%)","results":[{"x":"أظهرت النتائج أن الاحتراق الوظيفي ظاهر بين العاملين في المنظمات الإنسانية، وذلك نتيجة ظروف العمل غير المواتية من حيث طول ساعات العمل والمهام المفاجئة والعاجلة.","topic":"causes"},{"x":"كما ظهر أن الاحتراق الوظيفي ناتج عن عدم توفر العدالة والمساواة بين العاملين، وعدم التقدير من قبل الإدارة لجهود العاملين.","topic":"causes"},{"x":"المقابلات مع الإدارات أوضحت وجود جو من سوء التخطيط في بعض الإدارات مما يؤدي إلى الاحتراق الوظيفي لدى العاملين مع ضغوط العمل، والمهام، والمهام الطارئة","topic":"org"},{"x":"على الرغم من أن النتائج حول أداء العاملين أظهر أنهم على درجة عالية من الأداء، ولكن هذا كسمات شخصية في أنهم يجتهدون في إنجاز الأعمال في الأوقات المحددة، إلا أن مجموع التركيز ومقابلات الإدارات أظهرت أن الضغوط أثرت على سوية أداء العاملين لتجعلها أقل جودة وكفاءة.","topic":"effects"},{"x":"كما أظهرت النتائج على مستوى معدل دوران العمل، شعور العاملين في المنظمات الإنسانية، بأن عملهم مؤقت ولا بد في النهاية من الاستقرار، كما أظهرت النتائج أنهم على نية في ترك العمل، كما أن المقابلات أظهرت أن الضغوط وعدم المساواة وعدم التقدير تؤدي بالنهاية إلى ترك العمل، وهذا ما كان لهم من خبرة سابقة.","topic":"effects"},{"x":"من الجدول السابق نلاحظ أن قيمة معامل الارتباط بين الاحتراق الوظيفي وأداء العاملين هو R=0.296 وهو ارتباط ضعيف، علماً أن حجم الأثر حسب R Square يظهر أن الاحتراق الوظيفي يؤثر بنسبة 9% على أداء العاملين. ... علماً أن هذا الأثر عكسي لكون إشارة B سالبة، مما يعني أنه كلما زاد الاحتراق الوظيفي قلّ معه أداء العاملين. (R Square = 0.088، B = 0.224 بإشارة سالبة، Beta = 0.296 بإشارة سالبة، t = 4.826 بإشارة سالبة، Sig. = 0.000)","topic":"effects"},{"x":"من الجدول السابق نلاحظ أن قيمة معامل الارتباط بين الاحتراق الوظيفي ودوران العمل هو R=0.76 وهو ارتباط قوي، علماً أن حجم الأثر حسب R Square يظهر أن الاحتراق الوظيفي يؤثر بنسبة 58% على دوران العمل. ... علماً أن هذا الأثر طردي لكون إشارة B موجبة، مما يعني أنه كلما زاد الاحتراق الوظيفي زاد معه معدل دوران العمل. (R Square = 0.577، B = 1.062، Beta = 0.760، t = 18.169، Sig. = 0.000)","topic":"effects"},{"x":"من الجدول السابق يتضح أن الموظفين مستنزفون عاطفياً ومستهلكون بنهاية يوم عملهم، كما أن عملهم بجد وجهد كبير مع أشخاص يشكل مزيداً من الضغط، وقد جاءت جميع الإجابات السابقة بدرجة الموافق (المتوسطات 3.47 و3.74 و3.52). ... مع تأكيد ظهور حالات احتراق وظيفي حسب مجموعة التركيز، إلا أنها لم تصل إلى الدرجة العالية، وهذا ما أظهرته الإجابات على الاستبيان في العبارات السابقة.","topic":"dims"},{"x":"الإجابات حول إنجاز العاملين للأعمال المطلوبة منهم بكفاءة وفعالية، كما أنهم يحرصون على تحسين مستوى أداءهم، ويتحملون المسؤولية الناتجة عن أخطائهم جاءت بدرجة الموافق بشدة (المتوسطات 4.34 و4.33 و4.38). ... على الرغم من أن المستجيبين سجلوا موافقتهم على حرصهم الشخصي على تنفيذ الأعمال بوقتها والقيام بالأعمال المكلفين بها بالكفاءة والفاعلية، إلا أن ذلك يعكس مميزاتهم الشخصية، ولكن تبقى ظروف العمل غير مواتية من حيث الضغط، وساعات العمل الطويلة حسبما ظهر من إجابات مجموعة التركيز المعمّقة.","topic":"effects"},{"x":"اعتبار العمل مؤقت ولا بد من عمل آخر جاء بدرجة موافق (المتوسط 3.67)، مع جوهرية اختلاف متوسط الإجابة عن درجة الحيادي. ... بعموم الإجابات تبقى نية ترك العمل موجودة كون اعتبارهم للعمل مؤقت وحتمية الوصول إلى حالة أكثر استقراراً.","topic":"effects"},{"x":"مما سبق نلاحظ وجود حالات من الاحتراق الوظيفي التي قد تكون مؤقتة، موسمي، أو دائمة، وذلك حسب طبيعة العمل، والظروف المحيطة، لكن بشكل عام يظهر حالات الاحتراق الوظيفي، في ظل عدم التقيد بساعات العمل، والعمل لساعات طويلة وضمن الإجازات وبعد انتهاء الدوام غير مأجورة، إضافة إلى تحميل مهام ليست من التوصيف الوظيفي، أو أنها عاجلة وغير واضحة، ولم يتم التدريب عليها مسبقاً دون تحديد الأولويات ... مما ينتج عنه العزلة، والغربة في مكان العمل، الإرهاق الجسدي والنفسي، فقدان الثقة بالآخرين، القيام ببعض آليات التأقلم السلبية ومنها عدم الاكتراث، وضعف الإنجاز وعدم الاهتمام بجودة العمل. علماً أن الموظفين قد يميلون إلى ترك العمل لما لهم من تجربة في ترك عمل سابق بسبب عدم المساواة وقلة التقدير. (خلاصة مجموعة التركيز من 8 عاملين)","topic":"causes"},{"x":"أكد المدراء وجود المهام الطويلة والمفاجئة، والتقارير المطوّلة، والبيئة البيروقراطية مع هزالة التخطيط التي تؤدي إلى تجاوز الأوقات المحددة لإنهاء المهام، مما يزيد الضغط أكثر على الموظفين لإنهاء المهام، وانخفاض جودة العمل، وقلة الرغبة في العمل، وللأسف لا يوجد أي حلول من قبلهم، حسب الإدارة. (خلاصة المقابلات مع 6 إداريين)","topic":"org"}],"recs":["ضرورة أن تقوم المنظمات الإنسانية بالإحاطة أكثر بظروف العاملين لتقليل آثار الاحتراق الوظيفي لدى العاملين.","عمل إدارات المنظمات الإنسانية على خلق السياسات الخاصة بتوصية المدراء بأن يكونوا أكثر تكيفاً ومرونة بالتعامل مع العاملين في ظل الضغوط الشديدة للعمل.","ضرورة أن تتضمن السياسات مكافأة العاملين على جهودهم.","ضرورة أن تتوفر سياسة تتعلق بانتقال الموظفين بين الأقسام، كأسلوب لتخفيف الضغط المتعلق بكل قسم في المنظمة.","التأكيد على المساواة والعدالة بين الموظفين، وضرورة التحفيز بتقدير الجهود.","إتاحة مزيداً من الإجازات الشهرية والسنوية.","توفير أوقات استراحة كافية للعاملين ضمن الضغوط الشديدة بشكل مدروس","ضرورة أن تقوم الإدارات بإعادة ترتيب أولويات العمل من بداية كل يوم عمل، والتخطيط المسبق للمهام وأوقاتها المحددة، وبالتشاور مع العاملين الميدانيين خاصة.","ضرورة الاستراحة، وضبط النفس.","التواصل مع المدراء وتذكيرهم بالأسئلة والاستفسارات المتوقعة، وتحديد الجدول الزمني للمهام، وترتيب الأولويات.","الاهتمام بالصحة البدنية وممارسة الرياضة، وكذلك النفسية.","التقليل من التوقعات الخاصة بالعمل والإدارة.","استشارة طبيب نفسي عند اللزوم."],"tables":[{"t":"توجه الإجابات على محور دوران العمل","head":["العبارة","المتوسط الحسابي","الانحراف المعياري","توجه الإجابة","Sig.","المعنوية"],"rows":[["أفكر بتركي لعملي رغبة في الاستقرار","2.76","1.296","نوعاً ما","0.005","معنوي"],["أشعر بالوحدة والعزلة في مكان العمل، لذا دائماً أسعى للحصول على عمل آخر","2.45","1.231","غير موافق","0.000","معنوي"],["أقضي فترات طويلة في عملي مما يجعلني أفكر في ترك العمل","2.69","1.258","نوعاً ما","0.000","معنوي"],["أعتقد أن عملي الحالي مؤقت وفي النهاية لا بد من عمل آخر","3.67","1.250","موافق","0.000","معنوي"],["بقائي في عملي الحالي أمراً ضرورية لقلة الاختيارات الأخرى","3.40","1.278","نوعاً ما","0.000","معنوي"],["أفكر بتركي لعملي رغبة في الاستقرار (كذا مكرراً في الجدول؛ وعبارة الملحق السادسة: غالباً ما أفكر بقرار ترك العمل)","3.04","1.401","نوعاً ما","0.681","معنوي (كذا في الأصل)"]]},{"t":"الانحدار الخطي البسيط: أثر الاحتراق الوظيفي على أداء العاملين","head":["R","R Square","Adjusted R Square","Std. Error","B (Constant)","B (burnout)","Beta","t (burnout)","Sig."],"rows":[["0.296","0.088","0.084","0.51729","4.701","0.224 بإشارة سالبة","0.296 بإشارة سالبة","4.826 بإشارة سالبة","0.000"]]},{"t":"الانحدار الخطي البسيط: أثر الاحتراق الوظيفي على دوران العمل","head":["R","R Square","Adjusted R Square","Std. Error","B (Constant)","B (burnout)","Beta","t (burnout)","Sig."],"rows":[["0.760","0.577","0.575","0.65078","0.039 (Sig. 0.819)","1.062","0.760","18.169","0.000"]]}]}],"stats":[{"n":"76%","x":"من الموظفين يتعرّضون للاحتراق الوظيفي على الأقل في بعض الأحيان","src":"استطلاع مؤسسة غالوب (gallup.com)، بلا سنة في الدليل"},{"n":"28%","x":"منهم يعانون منه بشكل دائم أو في أغلب الأحيان","src":"استطلاع مؤسسة غالوب (gallup.com)، بلا سنة في الدليل"},{"n":"70%","x":"الموظفون الذين لديهم وقت كافٍ لأداء عملهم أقل عرضة بهذه النسبة للإرهاق الشديد","src":"تقرير مؤسسة غالوب 2018م"},{"n":"70%","x":"الموظفون الذين يشعرون بدعم قوي من مديرهم أقل عرضة بهذه النسبة للاحتراق الوظيفي","src":"تقرير مؤسسة غالوب 2018م"},{"n":"750 ألف (750,000)","x":"شخص يموتون سنويًا بسبب ساعات العمل الطويلة، وهو الخطر الأكبر","src":"تقرير WHO وILO المشترك، 2021م"},{"n":"42%","x":"ارتفاع نسبة الوفيات بسبب أمراض القلب بين 2000 و2016 بسبب ساعات العمل الطويلة","src":"تقرير WHO وILO المشترك، 2021م"},{"n":"190 مليار دولار سنويًا","x":"نفقات الرعاية الصحية الناجمة عن الاحتراق الوظيفي","src":"دراسة لجامعة ستانفورد (gsb.stanford.edu)، بلا سنة في الدليل"},{"n":"44%","x":"من الأطباء يعانون من الاحتراق الوظيفي رغم أن وظائفهم كانت شبه مكتبية","src":"دراسة طبية صدرت عام 2019م حول الاحتراق والاكتئاب والانتحار (لم يسمّها الدليل)"},{"n":"83.7%","x":"من الموظفين الإداريين في عينة دراسة غزة في مستوى متوسط من الاحتراق، و13.2% في مستوى مرتفع","src":"دراسة أبو مسعود، الجامعة الإسلامية بغزة، 2010"},{"n":"58%","x":"من التباين في دوران العمل يفسره الاحتراق الوظيفي في عينة دراسة سورية (R² = 0.577)","src":"دراسة هبة تراس، المعهد العالي لإدارة الأعمال، سورية"},{"n":"0.634","x":"معامل الارتباط بين ضغط العمل والاحتراق، وهو أقوى علاقة في دراسة غزة","src":"دراسة أبو مسعود، 2010"},{"n":"149","x":"موظفاً إدارياً في عينة دراسة جدة، من مجتمع قوامه 700 موظف","src":"دراسة منار الصبحي، جامعة جدة، 2022"}],"concepts":[{"term":"الاحتراق الوظيفي، المقدمة","def":"حالة من الإجهاد العاطفي والجسدي والعقلي الناتج عن ضغوط العمل المستمرة، مما يؤثر سلبًا على إنتاجية العاملين وكفاءتهم.","src":"guide"},{"term":"الاحتراق الوظيفي، علماء النفس","def":"حالة من الإرهاق العاطفي والجسدي والعقلي الناتج عن التعرّض المطوّل والمفرط للإجهاد والضغوطات في بيئة العمل. يحدث الاحتراق الوظيفي عندما يشعر الشخص بعدم الفاعلية وفقدان الدافعية، مما يؤدي إلى انخفاض الأداء والشعور بالإحباط والانعزال.","src":"guide"},{"term":"الاحتراق الوظيفي، فرويدنبرجر 1974","def":"حالة تتميز بالإرهاق الجسدي والعاطفي نتيجة الضغوط المستمرة في مكان العمل، وتشمل الشعور بالفشل وتدهور الأداء المهني والشخصي.","src":"guide"},{"term":"الاحتراق الوظيفي، فرويدنبرجر","def":"حالة من الإنهاك النفسي والبدني والعاطفي التي تستنزف الإنسان في جميع هذه الجوانب، مما قد يؤثر على قدرته على الإحساس بقيمة العمل الذي يقدّمه وربما يؤثر على ثقته بنفسه في جودة وكفاءة تقديم العمل.","src":"guide"},{"term":"الاحتراق الوظيفي، ماسلاش 1981","def":"مجموعة من أعراض الإجهاد النفسي، وتشمل الإرهاق العاطفي، والتبلّد الشخصي، والإحساس بعدم الرضا عن المنجز الشخصي والأداء المهني","src":"guide"},{"term":"الاحتراق الوظيفي، بينس 1988","def":"حالة من الإرهاق الجسدي والعاطفي والعقلي التي تحدث نتيجة الانخراط طويل الأمد في مواقف تتطلّب جهدًا عاطفيًا كبيرًا.","src":"guide"},{"term":"الاحتراق الوظيفي، علوطي ومغار 2017","def":"حالة نفسية تتضمّن مجموعة من الأعراض مثل الإجهاد العاطفي، الاستجابة العدائية تجاه الآخرين، والشعور بانخفاض الإنجاز الشخصي. غالبًا ما تصيب هذه الحالة الأفراد الذين تتطلّب وظائفهم تفاعلًا مستمرًا مع الناس.","src":"guide"},{"term":"الاحتراق الوظيفي، ICD-11 2019","def":"ظاهرة مهنية بشكل رسمي، محددةً أبعاده الثلاثة: الإرهاق العاطفي، والتباعد الشخصي، وانخفاض الكفاءة المهنية.","src":"guide"},{"term":"الوهن العصبي (Neurasthenia)","def":"كان الوهن العصبي يستخدم لوصف حالات الإرهاق النفسي والجسدي نتيجة للضغوطات المهنية.","src":"guide"},{"term":"الكاروشي","def":"مصطلح ياباني يعني (الموت من الإرهاق)، ويشير إلى الوفاة المفاجئة الناتجة عن العمل المفرط، غالبًا بسبب النوبات القلبية أو السكتات الدماغية.","src":"guide"},{"term":"مقياس ماسلاك للاحتراق (Maslach Burnout Inventory, MBI)","def":"أدوات قياس طوّرتها كريستينا ماسلاك وسوزان جاكسون لتقييم مستويات الاحتراق الوظيفي بين العاملين (عام 1980 كما يذكر الدليل).","src":"guide"},{"term":"الاحتراق النفسي","def":"عبارة عن خبرة نفسية سلبية داخلية تتضمّن المشاعر والاتجاهات والدوافع وتشمل استجابات سلبية وغير ملائمة نحو الغير ونحو الذات، تؤدي إلى فقدان الحيوية والنشاط بشكل عام، وليس فقط في سياق العمل.","src":"guide"},{"term":"الضغوط النفسية","def":"هي العوامل الخارجية التي تسبب التوتر والقلق، والتي يمكن أن تؤدي إلى الاحتراق النفسي عند تراكمها بشكل عام، وليس فقط في بيئة العمل","src":"guide"},{"term":"الإجهاد العادي","def":"حالة مؤقتة يمكن التعامل معها من خلال الراحة والاسترخاء، وتكون أعراضها أقل شدة ولا تؤدي إلى تأثيرات طويلة الأمد على الصحة النفسية والجسدية.","src":"guide"},{"term":"الإجهاد المزمن","def":"يشمل الإجهاد المستمر الذي يمكن أن يؤدي إلى مشاكل صحية طويلة الأمد، مثل أمراض القلب وارتفاع ضغط الدم","src":"guide"},{"term":"ضغط العمل","def":"حالة من الإجهاد الجسدي والنفسي الناتجة عن تراكم المسؤوليات والضغوطات التي تتجاوز قدرة الفرد على التحمل، وهو ظرف مؤقت يشعر به الموظف بوضوح، مما يسمح له باتخاذ خطوات للتعامل معه.","src":"guide"},{"term":"الاكتئاب","def":"اضطراب مزاجي يسبب شعورًا دائمًا بالحزن وفقدان الاهتمام، ويؤثر على كيفية شعور الشخص وتفكيره وسلوكه، مما يمكن أن يؤدي إلى مشاكل عاطفية وجسدية متعددة.","src":"guide"},{"term":"القلق","def":"حالة من التوتر المستمر التي يمكن أن تؤثر على الأداء الوظيفي والشخصي، وتزيد من احتمالية الشعور بالإرهاق","src":"guide"},{"term":"الإنهاك العاطفي","def":"شعور الموظف باستنزاف موارده العاطفية، مما يؤدي إلى فقدان الثقة بالنفس والروح المعنوية، وفقدان الاهتمام بالمستفيدين من الخدمة","src":"guide"},{"term":"الشعور بتدني الإنجاز الشخصي","def":"الإحساس بانخفاض الكفاءة والإنتاجية، مما يؤدي إلى تقييم الذات بشكل سلبي والشعور بالفشل.","src":"guide"},{"term":"فقدان العنصر الإنساني أو الشخصي في التعامل","def":"يشير إلى استجابة سلبية تتمثّل في تجريد المستفيدين من الصفة الشخصية، مما يؤدي إلى معاملة الأفراد باعتبارهم أشياء وليسوا بشرًا.","src":"guide"},{"term":"مثلث الاحتراق الوظيفي","def":"يتكون مثلث الاحتراق الوظيفي من: الضغط (الحرارة)، والدافع (الوقود)، والدعم (الأكسجين). عندما تتوفر هذه العناصر بشكل غير متوازن، يحدث الاحتراق الوظيفي، مما يؤثر على صحة الموظف.","src":"guide"},{"term":"إدمان العمل","def":"كان شغوفًا بعمله، وهذا الشغف تحول إلى إدمان للعمل، وهو أحد أشكال الاحتراق الوظيفي.","src":"guide"},{"term":"تنظيم وتخطيط الوقت","def":"عملية تنظيم وتخطيط كيفية تقسيم وقتك بين الأنشطة المختلفة تهدف لتحقيق أقصى قدر من الكفاءة والإنتاجية.","src":"guide"},{"term":"مصفوفة آيزنهاور","def":"صنّف المهام حسب الأهمية والإلحاح باستخدام مصفوفة آيزنهاور.","src":"guide"},{"term":"تقنية بومودورو","def":"قسّم العمل إلى فترات قصيرة (25 دقيقة) تتبعها فترات راحة قصيرة (5 دقائق). بعد أربع فترات عمل، خذ استراحة أطول (15-30 دقيقة)","src":"guide"},{"term":"العلاج المعرفي السلوكي للأرق (CBT-I)","def":"يستخدم تقنيات لتحسين نوعية النوم من خلال تعديل الأفكار والسلوكيات، يشمل ذلك إعادة هيكلة الأفكار السلبية، وتقييد وقت النوم، والتحكّم بالمحفزات","src":"guide"},{"term":"التعلم المستمر","def":"هو عملية تطوير المهارات والمعرفة بشكل دائم من خلال القراءة، الدورات التدريبية، المشاركة في الندوات والمؤتمرات، التعلم من التجارب الشخصية والمهنية، والاستفادة من المنصات التعليمية عبر الإنترنت.","src":"guide"},{"term":"الحاجات والرغبات","def":"الحاجات هي الأشياء الضرورية مثل الأكل والشرب والمسكن، بينما الرغبات هي الأشياء التي يمكن تأجيلها حتى تكون لديك القدرة المالية","src":"guide"},{"term":"قاعدة باريتو","def":"قاعدة باريتو تُعبّر عن مبدأ أن 80% من النتائج تأتي من 20% من الأسباب أو المدخلات، بمعنى أن جزءًا صغيرًا من الجهد يمُكِن أن يُحدِث تأثيرًا كبيرًا على النتائج.","src":"guide"},{"term":"النظرية السلوكية","def":"تفسّر النظرية السلوكية الاحتراق الوظيفي في ضوء عملية التعلم أنه سلوك غير سوي يتعلمه الفرد نتيجة العوامل البيئية غير المناسبة","src":"guide"},{"term":"النظرية المعرفية","def":"ترى النظرية المعرفية أن مصدر سلوك الإنسان داخلي معرفي كالعمليات العقلية التي يدرك من خلالها الفرد الموقف","src":"guide"},{"term":"النظرية الوجودية","def":"تركز النظرية الوجودية في تفسيرها للاحتراق الوظيفي على عدم وجود المعنى في حياة الفرد","src":"guide"},{"term":"نظرية التحليل النفسي","def":"فسّرت نظرية التحليل النفسي الاحتراق الوظيفي على أنه ناتج عن عملية ضغط الفرد على الأنا لمدة طويلة وذلك مقابل الاهتمام بالعمل","src":"guide"},{"term":"مقياس ماسلاش للاحتراق الوظيفي","def":"طورته الباحثة كرستينا ماسلاش في عام 1981، يقيّم ثلاثة جوانب رئيسية: الإرهاق المهني، التشاؤم وتبدد الشخصية، الشعور بضعف الكفاءة المهنية أو الإنجاز الشخصي.","src":"guide"},{"term":"العناصر الداخلية والخارجية للتوازن","def":"تشمل العناصر الداخلية الجوانب التي تخصك كشخص، مثل الصحة الجسدية والنفسية، والنمو الشخصي والتطوير الذاتي، والاسترخاء والراحة. أما العناصر الخارجية فتشمل المحيطين بك من أشخاص وأماكن، مثل العلاقات الاجتماعية والعائلية، والبيئة المهنية والعمل، والأنشطة الترفيهية والمجتمعية.","src":"guide"}],"defs":[{"x":"حالة نفسية تصيب الأفراد بالإرهاق و التعب ناجمة عن أعباء إضافية، يشعر معها الفرد أنه غير قادر على تحملها و ينعكس ذلك على الأفراد العاملين و المتعاملين معهم، و على مستوى الخدمات المقدمة لهم.","by":"الخرابشة و عربيات، 2005: 301 (التعريف الإجرائي المعتمد في مصطلحات الدراسة)","src":"gaza2010"},{"x":"مجموعة أعراض من الإجهاد الذهني والاستنفاد الانفعالي والتبلد الشخصي، والإحساس بعدم الرضا عن المنجز الشخصي والأداء المهني، ويحدث الاحتراق الوظيفي عندما لا يكون هناك توافق بين طبيعة العمل وطبيعة الإنسان الذي ينخرط في أداء ذلك العمل، وكلما زاد التباين بين هاتين البيئتين زاد الاحتراق الوظيفي الذي يواجهه الموظف في مكان عمله.","by":"ماسلاك، نقلاً عن كفافي، 2009 (www.aleqt.com)","src":"gaza2010"},{"x":"حالة من الإنهاك تحصل نتيجة للأعباء و المتطلبات الزائدة و المستمرة و الملقاة على الأفراد على حساب طاقاتهم و قوتهم.","by":"فرويدنبيرجر H. Freudenberger، 1974 (نقلاً عن الطحاينة، 1995: 8)","src":"gaza2010"},{"x":"إحساس الفرد بالإجهاد الانفعالي، و تبلد المشاعر، و انخفاض الانجاز الشخصي، وتعرفان الإجهاد الانفعالي Emotional Exhaustion بأنه فقد طاقة الفرد على العمل والأداء، والإحساس بزيادة متطلبات العمل، كما تعرفان تبلد المشاعر Depersonalization بأنه شعور الفرد بأنه سلبي و صارم، و كذلك إحساسه باختلال حالته المزاجية، أما انخفاض الانجاز الشخصي Lower Personal Accomplishment فتعرفانه بأنه إحساس الفرد بتدني نجاحه، واعتقاده بأن مجهوداته تذهب سدى، هذا و يعتبر هذا التعريف من أكثر التعاريف قبولا و استخداما في هذا المجال.","by":"ماسلاك وجاكسون Maslach & Jackson، 1981: 109","src":"gaza2010"},{"x":"مجموعة أعراض تتمثل في الإجهاد العصبي واستنفاذ الطاقة الانفعالية والتجرد من النواحي الشخصية، والإحساس بعدم الرضا عن الانجاز في المجال المهني. والتي يمكن أن تحدث لدى الأشخاص الذين يؤدون نوعا من الأعمال التي تقتضي التعامل المباشر مع الناس.","by":"ماسلاك، 1982 (نقلاً عن القريوتي و الخطيب، 2006: 133)","src":"gaza2010"},{"x":"حالة من الإجهاد التي تصيب الفرد نتيجة لأعباء العمل التي تفوق طاقته وينتج عنها مجموعة من الأعراض النفسية والجسدية والعقلية.","by":"ماسلاك Maslach، 1991 (نقلاً عن الزيودي، 2007: 192)","src":"gaza2010"},{"x":"فالأحتراق الوظيفي هو حالة من الإرهاق العاطفي والبدني والعقلي الناجم عن الإجهاد المفرط والمطول.","by":"الباحثة في مقدمة الدراسة دون إسناد (الصبحي، 2022)","src":"jeddah"},{"x":"الأداء هو قدرة الموظف على تطويع مخرجات وظيفته في شكل نتائج نهائية بأقل تكلفة ممكنة.","by":"عدنان ماشي والي (2011)، تقييم الأداء الوظيفي، صفحة 20، بتصرّف","src":"jeddah"},{"x":"فالأداء الوظيفي لأحد الوظائف أبداً لا يقاس بمستوى جهد الفرد المبذول ولكن الهدف هنا هو قياس النتائج التي حققها هذا الشخص من خلال قيامه بأداء مهامه الوظيفية","by":"الصبحي (2022) استناداً إلى عدنان ماشي والي (2011)","src":"jeddah"},{"x":"استنفاد القوة الجسدية أو العاطفية أو الدافع في الغالب نتيجة للإجهاد لفترات طويلة أو بسبب الإحباط","by":"Chen, Hsu, Ho (2016)","src":"syria"},{"x":"شعور بالإنهاك الجسدي والعاطفي، وذلك بسبب الإجهاد من العمل مع الناس في ظل ظروف صعبة أو نتيجة كثرة المطالب. ويدل عليه العديد من الأعراض مثل التعب المزمن، وسرعة الغضب والشك، والتعرض لنزلات البرد والصداع والحمى","by":"Aksu, Temeloglu (2015)","src":"syria"},{"x":"إفراط الفرد في استخدام طاقاته، حتى يستطيع تلبية متطلبات العمل الزائدة عن قدرته","by":"نقلاً عن شاويش (2016)","src":"syria"},{"x":"مجموعة أعراض من الإجهاد النفسي والاستنفاذ الانفعالي، والتبلد الشخصي، والإحساس بعدم الرضا عن المنجز الشخصي والأداء المهني","by":"ماسلاك، نقلاً عن شاويش (2016)","src":"syria"},{"x":"حالة نفسية تؤرق الأفراد الذين يعملون في مهن يكون في طبيعتها التعامل مع أناس كثيرين وهؤلاء العاملون عادة يعطون أكثر مما يأخذون","by":"نقلاً عن شاويش (2016)","src":"syria"},{"x":"حالة استنزاف للطاقة المخزنة لدى الفرد يؤدي به إلى حالة من عدم التوازن النفسي \"الاضطراب\" التي تظهر نتيجة للضغوط النفسية الشديدة التي تسببها أعباء العمل ومتطلباته مما ينعكس آثاره سلباً بشكل مباشر على العملاء وعلى المؤسسة التي يعمل فيها الفرد","by":"نقلاً عن شاويش (2016)","src":"syria"}],"refs":["دراسات بحثية:","أثر الاحتراق الوظيفي على أداء العاملين ومعدل دوران العمل في المنظمات الإنسانية (دراسة تطبيقية على عدد من المنظمات الإنسانية تحت مظلّة الأمم المتحدة في سورية)، هبة تراس.","أثر مصادر الضغط المهني واستراتيجيات المقاومة والمعبرية الانفعالية والدفاعية الانفعالية/العقلانية على الاحتراق النفسي عند ضباط الشرطة (دراسة ميدانية بالمديرية العامة للأمن الوطني بالجزائر العاصمة)، مزياني فتحية (2006/2007).","الاحتراق النفسي وعلاقته ببعض سمات الشخصية لدى العاملات مع ذوي الاحتياجات الخاصة، نوال الزهراني (2007/2008).","الاحتراق الوظيفي لدى المرأة العاملة في مؤسسات السلطة الوطنية الفلسطينية في قطاع غزة، أماني بسام الجمل (1433هـ، 2012).","الاحتراق الوظيفي: الأسباب وطرق العلاج، باحث دكتوراه: سعيد بن علي القحطاني.","الاحتراق النفسي الوظيفي والرضا الوظيفي والعلاقة بينهما لدى معلمي غرف المصادر في الأردن، رامي طشطوش وآخرون (2013).","علاقة الاحتراق النفسي ببعض الاضطرابات النفسية والنفس جسدية لدى الممرضين، باحث دكتوراه: طايبي نعيمة (2012/2021).","مصنفات علمية:","الرضا الوظيفي ومهارة إدارة ضغوط العمل، د. عصام عبداللطيف عمر (الطبعة الأولى، 2015).","فكري، إيهاب (2013). 4 شارع النجاح. دار دون للنشر والتوزيع.","آل مكي، زينب. هل تراني أنني أحترق، 2020.","شوفلي، ويلمار. الاحتراق النفسي.","السلوك التربوي وعلاقته بالاحتراق النفسي، أ.د. واثق عمر التكريتي، د. جنار عبدالقادر الجباري (الطبعة الأولى، 2014).","نهاية الإجهاد النفسي: الخطوات الأربع لإعادة توجيه دماغك، دون جوزيف جيووي، ترجمة سعيد الحسنية (الطبعة الأولى، 1436هـ، 2015).","نادي الاحتراق النفسي، عمرو صالح (الطبعة الأولى، 2020).","مجتمع الاحتراق النفسي، بيونغ شول هان، ترجمة بدر الدين مصطفى (2022).","القيام بما يهم في أوقات الضغط النفسي: دليل مصور. منظمة الصحة العالمية (2020).","أرجوك لا تحترق وظيفياً، عبدالرحمن عثمان.","مواقع رسمية:","مايو كلينك (Mayo Clinic): mayoclinic.org/ar","منظمة الصحة العالمية (WHO): who.int/ar","منصة صبّار: sabbar.com","بيانات التواصل في الغلاف الخلفي (الصورة 101): المركز الوطني لتعزيز الصحة النفسية، 0118800865، info@ncmh.org.sa، NCMH.ORG.SA، رقم الإيداع 1446/18403، ردمك 978-603-8459-07-2"]};
